-- 0) Danh sách văn bản trong Excel (đã gộp trùng theo cột "VĂN BẢN GIAO NHIỆM VỤ")
DROP TEMPORARY TABLE IF EXISTS tmp_check_vb;
CREATE TEMPORARY TABLE tmp_check_vb (
    Stt         INT PRIMARY KEY,
    DocCode     VARCHAR(255),   -- cột "VĂN BẢN GIAO NHIỆM VỤ", sau UPDATE đã bỏ space quanh "-" "/"
    DocCodeGoc  VARCHAR(255),   -- nguyên văn trong Excel
    SoNVExcel   INT,            -- số nhiệm vụ trong Excel thuộc văn bản này
    DsSttExcel  TEXT,           -- STT các nhiệm vụ đó trong sheet
    SoHieu      VARCHAR(20),    -- chỉ có với mã viết tắt "TB 12" -> '12'
    LoaiVB      VARCHAR(20),    --                              -> 'tb'
    DocCodeNorm VARCHAR(255),
    KEY ix_code (DocCode),
    KEY ix_norm (DocCodeNorm)
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

