-- Bỏ khoảng trắng quanh "-" và "/": "63 -TB/VPTU", "63 - TB / VPTU" -> "63-TB/VPTU"
-- (gộp space đôi trước để ' -' / '- ' bắt được cả trường hợp nhiều dấu cách)
UPDATE tmp_check_vb
SET DocCodeGoc  = DocCode,
    DocCode     = TRIM(REPLACE(REPLACE(REPLACE(REPLACE(
                      REPLACE(REPLACE(REPLACE(TRIM(DocCode), '  ', ' '), '  ', ' '), '  ', ' '),
                  ' -', '-'), '- ', '-'), ' /', '/'), '/ ', '/')),
    DocCodeNorm = LOWER(REPLACE(REPLACE(REPLACE(REPLACE(
                      IFNULL(DocCode, ''), ' ', ''), CHAR(13), ''), CHAR(10), ''), CHAR(9), ''));

-- 1) Quét qlnv_resolution một lần, chuẩn hoá DocCode
DROP TEMPORARY TABLE IF EXISTS tmp_res_norm;
CREATE TEMPORARY TABLE tmp_res_norm (
    ResolutionId INT PRIMARY KEY,
    DocCode      VARCHAR(255),
    DocCodeNorm  VARCHAR(255),
    KEY ix_code (DocCode),
    KEY ix_norm (DocCodeNorm)
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

INSERT INTO tmp_res_norm (ResolutionId, DocCode, DocCodeNorm)
SELECT  r.ResolutionId,
        TRIM(REPLACE(REPLACE(REPLACE(REPLACE(
            REPLACE(REPLACE(REPLACE(TRIM(r.DocCode), '  ', ' '), '  ', ' '), '  ', ' '),
        ' -', '-'), '- ', '-'), ' /', '/'), '/ ', '/')),
        LOWER(REPLACE(REPLACE(REPLACE(REPLACE(
            r.DocCode, ' ', ''), CHAR(13), ''), CHAR(10), ''), CHAR(9), ''))
FROM qlnv_resolution r
WHERE IFNULL(TRIM(r.DocCode), '') <> '';

-- 2) Tìm khớp (MucKhop: 3 = chinh xac, 2 = gan dung, 1 = theo so)
DROP TEMPORARY TABLE IF EXISTS tmp_match_vb;
CREATE TEMPORARY TABLE tmp_match_vb (
    Stt          INT,
    ResolutionId INT,
    MucKhop      TINYINT,
    KEY ix_stt (Stt, ResolutionId)
);

INSERT INTO tmp_match_vb
SELECT c.Stt, r.ResolutionId, 3
FROM tmp_check_vb c JOIN tmp_res_norm r
  ON CONVERT(r.DocCode USING utf8mb4) COLLATE utf8mb4_bin = c.DocCode COLLATE utf8mb4_bin;

INSERT INTO tmp_match_vb
SELECT c.Stt, r.ResolutionId, 2
FROM tmp_check_vb c JOIN tmp_res_norm r ON r.DocCodeNorm = c.DocCodeNorm
WHERE c.DocCodeNorm <> '';

INSERT INTO tmp_match_vb
SELECT c.Stt, r.ResolutionId, 1
FROM tmp_check_vb c JOIN tmp_res_norm r
  ON  r.DocCodeNorm LIKE CONCAT(c.SoHieu, '-', c.LoaiVB, '/%')
   OR r.DocCodeNorm LIKE CONCAT(c.SoHieu, '/', c.LoaiVB, '/%')
   OR r.DocCodeNorm  =   CONCAT(c.SoHieu, '-', c.LoaiVB)
WHERE c.SoHieu IS NOT NULL;

-- 3) Số nhiệm vụ đang có trong DB theo từng văn bản khớp
DROP TEMPORARY TABLE IF EXISTS tmp_task_cnt;
CREATE TEMPORARY TABLE tmp_task_cnt (PRIMARY KEY (ResolutionId)) AS
SELECT t.ResolutionId,
       COUNT(*)                     AS SoNVDB,
       SUM(t.DeletedDate IS NULL)   AS SoNVDBChuaXoa
FROM qlnv_task t
JOIN (SELECT DISTINCT ResolutionId FROM tmp_match_vb) k ON k.ResolutionId = t.ResolutionId
GROUP BY t.ResolutionId;

-- 4) Chi tiết từng văn bản khớp (gộp để không đếm trùng)
DROP TEMPORARY TABLE IF EXISTS tmp_chi_tiet_vb;
CREATE TEMPORARY TABLE tmp_chi_tiet_vb AS
SELECT
    x.Stt,
    c.DocCode                                   AS DocCodeExcel,
    CASE x.MucKhop WHEN 3 THEN 'chinh xac' WHEN 2 THEN 'gan dung' ELSE 'theo so' END AS KhopTheo,
    x.MucKhop,
    r.ResolutionId,
    r.DocCode                                   AS DocCodeDB,
    r.ResolutionGroupId,
    g.Name                                      AS TenNhom,
    (r.ResolutionGroupId = 55)                  AS Nhom55,
    (r.DeletedDate IS NOT NULL)                 AS DaXoa,
    r.Status,
    r.Type,
    r.StartDate,
    r.CreateUser,
    r.AssignUserName,
    r.AssignOrganizationName,
    c.SoNVExcel,
    IFNULL(n.SoNVDB, 0)                         AS SoNVDB,
    IFNULL(n.SoNVDBChuaXoa, 0)                  AS SoNVDBChuaXoa,
    LEFT(r.Compendium, 300)                     AS TrichYeuDB
FROM (SELECT Stt, ResolutionId, MAX(MucKhop) AS MucKhop
      FROM tmp_match_vb GROUP BY Stt, ResolutionId) x
JOIN tmp_check_vb c      ON c.Stt = x.Stt
JOIN qlnv_resolution r   ON r.ResolutionId = x.ResolutionId
LEFT JOIN qlnv_resolution_group g ON g.ResolutionGroupId = r.ResolutionGroupId
LEFT JOIN tmp_task_cnt n ON n.ResolutionId = x.ResolutionId;

-- 4b) CHECK THEO TÊN NHIỆM VỤ: 571 nhiệm vụ Excel (cột "TÊN NHIỆM VỤ CỤ THỂ") so với qlnv_task.Title
--     Tên chuẩn hoá 2 phía giống nhau: CR/LF/TAB -> space, gộp space, bỏ dấu "." cuối, không phân biệt hoa thường.
DROP TEMPORARY TABLE IF EXISTS tmp_check_nv;
CREATE TEMPORARY TABLE tmp_check_nv (
    Stt     INT PRIMARY KEY,    -- STT trong sheet
    VbStt   INT,                -- = tmp_check_vb.Stt (văn bản giao của nhiệm vụ)
    Ten     TEXT,
    TenNorm TEXT COLLATE utf8mb4_bin,   -- tên đã chuẩn hoá (lower)
    TenHash CHAR(32),
    KEY ix_vb (VbStt),
    KEY ix_hash (TenHash)
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

INSERT INTO tmp_check_nv (Stt, VbStt, Ten) VALUES
(1, 1, 'Phân công 01 đồng chí lãnh đạo phụ trách xuyên suốt việc triển khai thực hiện Nghị quyết số 57 và các nhiệm vụ liên quan; tham gia đầy đủ các cuộc họp của Ban Chỉ đạo, Tổ Thường trực; chịu trách nhiệm trước cấp có thẩm quyền về tiến độ, chất lượng và hiệu quả thực hiện nhiệm vụ được giao'),
(2, 1, 'Đối với các nhiệm vụ, dự án được giao chủ trì trong Kế hoạch số 20-KH/BCĐ, Kế hoạch số 38/KH-UBND và các Thông báo kết luận của Ban Chỉ đạo, chủ động rà soát, đề xuất danh mục nhiệm vụ, dự án ưu tiên bố trí kinh phí; sắp xếp theo thứ tự ưu tiên từ cao xuống thấp; gửi Sở Khoa học và Công nghệ, Sở Tài chính để làm cơ sở tổng hợp, tham mưu phân bổ nguồn lực bảo đảm tập trung, hiệu quả'),
(3, 1, 'Rà soát toàn bộ các nhiệm vụ, dự án đang triển khai hoặc đang đề xuất; đánh giá nguy cơ lãng phí, trùng lặp; mạnh dạn báo cáo cấp có thẩm quyền xem xét chấm dứt đối với các nhiệm vụ, dự án trùng lặp vì đã có hệ thống dùng chung của Trung ương hoặc Thành phố; bảo đảm nguyên tắc tránh đầu tư chồng chéo, phân tán nguồn lực; trường hợp để xảy ra đầu tư trùng lặp, lãng phí do không rà soát đầy đủ hệ thống dùng chung của Trung ương hoặc Thành phố thì xem xét trách nhiệm người đứng đầu theo quy định'),
(4, 2, 'Bí thư Đảng ủy các xã: Hòa Lạc, Phú Cát, Hạ Bằng, Yên Xuân chịu trách nhiệm trước Ban Thường vụ Thành ủy về tiến độ giải phóng mặt bằng trên địa bàn quản lý. Yêu cầu xác định đây là nhiệm vụ chính trị trọng tâm của địa phương trong năm 2026. Chủ động xây dựng lộ trình thực hiện chi tiết, trường hợp phát sinh vướng mắc vượt thẩm quyền phải báo cáo các sở, ngành liên quan để xử lý dứt điểm, tuyệt đối không để xảy ra tình trạng đùn đẩy, né tránh trách nhiệm, làm chậm trễ tiến độ bàn giao mặt bằng cho dự án. Thực hiện cơ chế kiểm điểm tiến độ giải phóng mặt bằng theo quý; báo cáo rõ trách nhiệm cá nhân nếu chậm tiến độ'),
(5, 3, 'Giao Đảng ủy các xã, phường: Rà soát, quán triệt tới cán bộ lãnh đạo về nội dung khung năng lực số và chủ động cập nhật kiến thức, kỹ năng số bảo đảm đáp ứng yêu cầu; phối hợp với các đơn vị liên quan tổ chức đánh giá, tập huấn bồi dưỡng theo kế hoạch của Thành phố'),
(6, 4, 'Các sở, ban, ngành rà soát, chuẩn hóa, hoàn thiện các cơ sở dữ liệu chuyên ngành thuộc phạm vi quản lý, bảo đảm dữ liệu đúng, đủ, sạch, sống, thống nhất, dùng chung, kết nối và chia sẻ được; hoàn thành trước ngày 30/8/2026. Sở Khoa học và Công nghệ chủ trì hướng dẫn tiêu chuẩn kỹ thuật, kiến trúc dữ liệu, kết nối, chia sẻ dữ liệu; bảo đảm đồng bộ, thống nhất trong xây dựng, chia sẻ, tích hợp dữ liệu của các cơ quan, đơn vị.'),
(7, 5, 'Các cơ quan, đơn vị chịu trách nhiệm toàn diện về tiến độ, chất lượng các nhiệm vụ đã được giao; tập trung xử lý dứt điểm các nhiệm vụ chậm, quá hạn, kết quả chưa đáp ứng yêu cầu.'),
(8, 5, 'Các sở, ngành rà soát, khắc phục những hạn chế trong kết nối, liên thông dữ liệu giữa các ngành, lĩnh vực, trọng tâm là giữa y tế với các ngành có liên quan; giữa nông nghiệp và môi trường với cơ quan thuế; giữa công thương với cơ quan thuế. Phấn đấu đến cuối năm 2026 cơ bản hoàn thiện hệ thống cơ sở dữ liệu của Thành phố, đưa vào khai thác, sử dụng thực tế, làm nền tảng chuyển đổi phương thức lãnh đạo, chỉ đạo, điều hành trên cơ sở khoa học và dữ liệu; triển khai đồng bộ từ các sở, ngành Thành phố đến 126 xã, phường và các đơn vị trực thuộc.'),
(9, 5, 'Các sở, ngành lựa chọn, đăng ký từ 01-02 sản phẩm cụ thể gắn với phát triển kinh tế số của ngành, lĩnh vực; hoàn thành đăng ký trong đầu tháng 9/2026 để làm cơ sở kiểm đếm, đánh giá kết quả thực hiện vào cuối năm.'),
(10, 5, 'Các sở, ngành thực hiện nghiêm việc phân công 01 đồng chí lãnh đạo phụ trách xuyên suốt việc triển khai Nghị quyết số 57-NQ/TW và các nhiệm vụ có liên quan; bảo đảm ổn định, được giao đủ thẩm quyền xử lý công việc thuộc phạm vi phụ trách và chịu trách nhiệm về tiến độ thực hiện; gửi danh sách phân công về Ban Chỉ đạo 57 Thành ủy trước ngày 15/9/2026.'),
(11, 1, 'Chủ trì, phối hợp Trung tâm Phục vụ hành chính công Thành phố xây dựng quy trình thanh tra, kiểm tra điện tử đối với doanh nghiệp trên hệ thống văn bản điện tử kết nối doanh nghiệp; hoàn thành trước ngày 30/11/2026'),
(12, 6, 'Thanh tra việc quản lý, vận hành, khai thác hạ tầng tại Khu công nghệ cao Hòa Lạc; làm rõ nguồn lực nhà nước đầu tư, nguồn lực nhà đầu tư hạ tầng đầu tư, việc xác định mức giá cho thuê; kịp thời xử lý hoặc kiến nghị xử lý những tồn tại, bất cập, nguy cơ thất thoát, lãng phí; báo cáo kết quả thanh tra với cấp có thẩm quyền để xem xét, chỉ đạo.'),
(13, 7, 'Giao Thường trực HĐND Thành phố nghiên cứu, đề xuất giải pháp căn cơ nhằm tháo gỡ các vướng mắc về cơ chế tài chính trong lĩnh vực khoa học, công nghệ và chuyển đổi số; bảo đảm hành lang pháp lý thông thoáng, đồng bộ, tạo điều kiện thuận lợi cho việc triển khai các nhiệm vụ đột phá của Thành phố.'),
(14, 8, 'Lãnh đạo, chỉ đạo triển khai chuyển đổi số đồng bộ, thực chất, xác định đây là yêu cầu bắt buộc, không làm hình thức. Kiên quyết đổi mới phương thức lãnh đạo, chỉ đạo, điều hành và tổ chức thực hiện nhiệm vụ trên môi trường số; chấm dứt tình trạng vận hành song song giữa phương thức truyền thống và phương thức số đối với các quy trình, nghiệp vụ đã đủ điều kiện. Chậm nhất trước ngày 15/02/2026, ban hành Kế hoạch chuyển đổi số toàn hệ thống chính trị Thành phố (phân công rõ đầu mối, nhiệm vụ, lộ trình, chỉ tiêu định lượng, nguồn lực); gắn kết quả chuyển đổi số với trách nhiệm người đứng đầu và đánh giá mức độ hoàn thành nhiệm vụ của từng cơ quan, đơn vị.'),
(15, 9, 'Thành lập Trung tâm giám sát, điều hành thông minh Thành phố'),
(16, 9, 'Xây dựng, triển khai đề án ứng dụng IoT trong một số ngành, lĩnh vực như sản xuất thương mại, quản lý năng lượng, nông nghiệp thông minh, giao thông thông minh, y tế thông minh,...:'),
(17, 10, 'Hoàn thành việc chuyển giao Điểm Phục vụ hành chính công cấp xã về TTphục vụ hành chính công Thành phố'),
(18, 11, 'Thống nhất xây dựng một Trung tâm Điều hành Thông minh (IOC) dùng chung cho toàn bộ hệ thống chính trị thành phố, bảo đảm phục vụ đầy đủ các cơ quan Đảng, Chính quyền, Hội đồng Nhân dân và Mặt trận Tổ quốc; giao UBND Thành phố sớm đưa vào vận hành, hoàn thiện Trung tâm Điều hành Thông minh của UBND Thành phố làm nền tảng cho IOC chung'),
(19, 11, 'Hoàn thành triển khai xây dựng, đưa vào khai thác, sử dụng 114 cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành, trong đó tập trung ưu tiên hoàn thiện cơ sở dữ liệu: đất đai, xây dựng, bảo hiểm, tài chính, doanh nghiệp, lao động việc làm, y tế, giáo dục và kết nối, xác thực với Cơ sở dữ liệu quốc gia về dân cư trong tháng 8/2025, đồng bộ dữ liệu về Trung tâm dữ liệu quốc gia'),
(20, 11, 'Tham mưu, đề xuất Ban Thường vụ Thành ủy đưa đầy đủ các nội dung về KHCN, ĐMST và phát triển nguồn nhân lực chất lượng cao vào Chương trình hành động của Ban Thường vụ Thành ủy triển khai thực hiện Nghị quyết số 71-NQ/TW và Nghị quyết số 72-NQ/TW.'),
(21, 12, 'Thống nhất về nguyên tắc bố trí trụ sở làm việc của Trung tâm Phục vụ Hành chính công tại 126 xã, phường.'),
(22, 12, 'Chỉ đạo Sở Văn hóa và Thể thao, Sở Giáo dục và Đào tạo, Sở Y tế về công tác chuyển đổi số, ứng dụng khoa học, công nghệ và đổi mới sáng tạo..'),
(23, 7, 'Giao đồng chí Trương Việt Dũng, Phó Chủ tịch UBND Thành phố, Tổ phó Tổ Thường trực làm việc với 04 khối để thống nhất nhận thức, làm rõ cơ chế phối hợp, cách thức điều hành và phương pháp triển khai Kế hoạch hành động năm 2026 thực hiện Nghị quyết số 57-NQ/TW năm 2026 của Ban Chỉ đạo 57 Thành ủy gắn với lộ trình cụ thể.'),
(24, 8, 'lãnh đạo, chỉ đạo triển khai chuyển đổi số đồng bộ, thực chất, xác định đây là yêu cầu bắt buộc, không làm hình thức. Kiên quyết đổi mới phương thức lãnh đạo, chỉ đạo, điều hành và tổ chức thực hiện nhiệm vụ trên môi trường số; chấm dứt tình trạng vận hành song song giữa phương thức truyền thống và phương thức số đối với các quy trình, nghiệp vụ đã đủ điều kiện. Chậm nhất trước ngày 15/02/2026, ban hành Kế hoạch chuyển đổi số toàn hệ thống chính trị Thành phố (phân công rõ đầu mối, nhiệm vụ, lộ trình, chỉ tiêu định lượng, nguồn lực); gắn kết quả chuyển đổi số với trách nhiệm người đứng đầu và đánh giá mức độ hoàn thành nhiệm vụ của từng cơ quan, đơn vị.'),
(25, 8, 'Chỉ đạo tập trung nguồn lực để chuyển đổi số mạnh mẽ đối với dịch vụ công và các lĩnh vực quản lý Thành phố đã có đầy đủ dữ liệu như: dân cư, đất đai, đô thị, giao thông, giáo dục, y tế; lấy dữ liệu làm nền tảng nâng cao chất lượng phục vụ người dân, doanh nghiệp và hiệu quả quản lý nhà nước; chuyển mạnh từ xử lý thủ công sang xử lý số, từ báo cáo truyền thống sang chỉ đạo, điều hành dựa trên dữ liệu. Chậm nhất trong Quý II/2026, hoàn thành Danh mục cơ sở dữ liệu dùng chung và Danh mục hệ thống thông tin trọng điểm của Thành phố, bảo đảm kết nối – chia sẻ – khai thác hiệu quả phục vụ công tác lãnh đạo, chỉ đạo, điều hành.'),
(26, 8, 'Chỉ đạo tổ chức ra mắt “Chợ Chuyển đổi số” của Thành phố vào dịp 03/02/2026; thông qua đó, công bố các bài toán thực tiễn, nhu cầu ứng dụng, đặt hàng cụ thể; tạo điều kiện để doanh nghiệp giới thiệu sản phẩm, giải pháp sẵn sàng triển khai, thúc đẩy hợp tác công - tư trong chuyển đổi số.'),
(27, 8, 'Chỉ đạo xây dựng hệ thống tiêu chuẩn, quy chuẩn, yêu cầu chung về khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số áp dụng thống nhất trên phạm vi toàn Thành phố; khẩn trương hoàn thành công tác xây dựng định mức kinh tế - kỹ thuật và đơn giá đối với các sản phẩm, dịch vụ trong lĩnh vực khoa học, công nghệ. Trên cơ sở đó, chủ trì xây dựng, hoàn thiện và hướng dẫn áp dụng các tiêu chuẩn, quy chuẩn khoa học - công nghệ gắn với yêu cầu phát triển Thủ đô, trọng tâm là các lĩnh vực đô thị thông minh, khu đô thị mới, hạ tầng số, dữ liệu và môi trường, bảo đảm thống nhất, đồng bộ, tránh đầu tư dàn trải, thiếu liên thông kết nối; hoàn thiện trong Quý I/2026.'),
(28, 8, 'Chỉ đạo nghiên cứu, ban hành cơ chế ưu tiên lựa chọn doanh nghiệp trong nước trong hoạt động đầu tư, mua sắm, đặt hàng và thuê dịch vụ công nghệ, trong trường hợp doanh nghiệp trong nước đáp ứng yêu cầu về chất lượng, kỹ thuật với giá trị tương đương; hoàn thành trong Quý I/2026.'),
(29, 8, 'Chỉ đạo nghiên cứu, đề xuất các giải pháp tạo thị trường cho doanh nghiệp khoa học và công nghệ, nhất là doanh nghiệp vừa và nhỏ, thông qua cơ chế đặt hàng, giao nhiệm vụ và thuê dịch vụ công nghệ; chuyển từ tư duy đầu tư dàn trải sang sử dụng dịch vụ, lấy hiệu quả và giá trị mang lại làm thước đo chính trong lựa chọn giải pháp; báo cáo Ban Chỉ đạo trong Quý II/2026.'),
(30, 8, 'Chỉ đạo nghiên cứu, xây dựng các cơ chế, chính sách hỗ trợ công chức, viên chức, người lao động trong hệ thống chính trị Thành phố thực hiện nhiệm vụ khoa học công nghệ, đổi mới sáng tạo vào chuyển đổi số, các doanh nghiệp khoa học và công nghệ về hạ tầng, đất đai, không gian làm việc; đồng thời triển khai các mô hình thử nghiệm có kiểm soát (sandbox) để tạo điều kiện cho doanh nghiệp nghiên cứu, thử nghiệm, hoàn thiện và thương mại hóa các sản phẩm, giải pháp công nghệ mới, hoàn thành trong Quý I/2026. Khẩn trương kiện toàn tổ chức bộ máy, nhân sự của các cơ quan chuyên môn có liên quan đến phát triển khoa học công nghệ và chuyển đổi số, bảo đảm đáp ứng yêu cầu trong tình hình mới.'),
(31, 8, 'Chỉ đạo rà soát, tham mưu cho Tổ Thường trực Ban Chỉ đạo 57 Thành ủy ban hành danh mục các “đầu bài lớn” nhằm giải quyết những điểm nghẽn trong phát triển kinh tế - xã hội, quản lý đô thị, cải cách hành chính. Danh mục đầu bài phải được ban hành trong Quý I/2026.'),
(32, 8, 'Chỉ đạo xây dựng khung chi tiết về chuyển đổi số của Thành phố, trong đó xác định rõ mục tiêu, nhiệm vụ, giải pháp và lộ trình nâng cao tỷ lệ dịch vụ công trực tuyến toàn trình, bảo đảm thực chất, lấy người dân, doanh nghiệp làm trung tâm phục vụ; gắn kết quả thực hiện với trách nhiệm người đứng đầu và đánh giá mức độ hoàn thành nhiệm vụ của từng cơ quan, đơn vị; báo cáo Ban Chỉ đạo trong Quý I/2026.'),
(33, 11, 'Thống nhất với các đề xuất của UBND Thành phố về: (i) thí điểm các mô hình “Sổ đỏ trao tay”, “Mô hình Doanh nghiệp một chạm”, “Chiến dịch 90 ngày triển khai thu thập dữ liệu sống trong lĩnh vực y tế”; thí điểm ứng dụng trí tuệ nhân tạo (AI) trong y tế; xây dựng Đề án Bệnh viện thông minh Xanh Pôn; triển khai thí điểm Kho dữ liệu tập trung của Thành phố đối với dữ liệu thuộc các lĩnh vực: đất đai, y tế, tài chính, giáo dục. Trường hợp phát sinh khó khăn, vướng mắc trong quá trình triển khai thực hiện, UBND Thành phố kịp thời báo cáo, xin ý kiến Thường trực Thành ủy, Ban Thường vụ Thành ủy và Ban Chỉ đạo 57 của Thành ủy theo thẩm quyền.'),
(34, 13, 'Rà soát, xác định các nhiệm vụ cần bổ sung (nếu có), bảo đảm Kế hoạch hành động số 20-KH/BCĐ57 ngày 19/01/2026 được cập nhật đầy đủ theo ý kiến của Ban Chỉ đạo 57 Trung ương tại Chương trình số 02-CTr/BCĐTW và Văn phòng Trung ương Đảng tại Văn bản số 315-CV/VPTW; báo cáo kết quả Ban Chỉ đạo 57 Thành ủy (qua Văn phòng Thành ủy - Cơ quan Thường trực Ban Chỉ đạo).'),
(35, 13, 'Báo cáo Ban Chỉ đạo 57 Thành ủy phương án triển khai xây dựng Trung tâm tính toán thông minh (AIDC), bảo đảm tuân thủ quy định, khả thi về tiến độ và nguồn lực'),
(36, 13, 'Làm việc với Tập đoàn Viettel để thống nhất phương án hỗ trợ hạ tầng kho dữ liệu, bảo đảm tiếp nhận và đưa vào khai thác ngay các nhóm dữ liệu ưu tiên phục vụ công tác quản lý, điều hành của Thành phố, trước mắt gồm các nhóm dữ liệu: đất đai, y tế, giáo dục'),
(37, 13, 'Nghiên cứu ban hành bộ quy chuẩn, tiêu chuẩn đô thị thông minh đồng bộ, bảo đảm tương thích với các đô thị hiện đại trên thế giới và phù hợp với đặc thù phát triển của Thành phố. Trên cơ sở đó, xác định lộ trình thực hiện theo từng nhóm khu vực: (i) Đối với các khu đô thị mới: áp dụng tiêu chuẩn đô thị thông minh ngay từ khâu quy hoạch, thiết kế; (ii) Đối với các khu đang triển khai xây dựng và khu vực tái thiết: khẩn trương rà soát, tích hợp tối đa các tiêu chí thông minh, kịp thời điều chỉnh giải pháp thực hiện để bảo đảm thống nhất định hướng phát triển; (iii) Đối với khu vực hiện hữu không thuộc diện tái thiết: xây dựng kế hoạch đầu tư, nâng cấp theo lộ trình phù hợp, từng bước tiệm cận các tiêu chuẩn hiện đại'),
(38, 13, 'Tham mưu cơ chế, chính sách vượt trội thu hút, phát triển nguồn nhân lực chất lượng cao phục vụ khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số,    xác định đây là đầu tư chiến lược nhằm nâng cao năng lực cạnh tranh của Thủ đô trong bối cảnh cạnh tranh nguồn nhân lực toàn cầu; trong đó làm rõ nhóm đối tượng ưu tiên, tiêu chí lựa chọn, cơ chế tuyển dụng, sử dụng, đánh giá, chế độ đãi ngộ,    thu nhập tăng thêm và cơ chế huy động chuyên gia theo nhiệm vụ, bảo đảm phù hợp quy định, khả thi về nguồn lực và hiệu quả trong tổ chức thực hiện'),
(39, 13, 'Chỉ đạo các đơn vị liên quan rà soát, phân bổ và ưu tiên tối đa hạ tầng kỹ thuật, trang thiết bị công nghệ thông tin và đường truyền phục vụ nhiệm vụ bầu cử; tăng cường theo dõi, đôn đốc tiến độ cung cấp máy móc, thiết bị CNTT cho 126 xã, phường, bảo đảm đồng bộ điều kiện vận hành tại cơ sở, đáp ứng yêu cầu tổ chức bầu cử và vận hành thông suốt các hệ thống dùng chung trong giải quyết thủ tục hành chính'),
(40, 13, 'Xác định xây dựng “Bản sao số” là nhiệm vụ đột phá năm 2026. Ưu tiên tích hợp, chuẩn hóa dữ liệu về thiết chế văn hóa (gắn với phát triển du lịch) và lĩnh vực giáo dục. Đẩy mạnh thí điểm toàn diện tại xã Minh Châu, kịp thời đánh giá, rút kinh nghiệm để đề xuất mở rộng phù hợp'),
(41, 4, 'Căn cứ chỉ đạo của Trung ương, Thường trực Thành ủy, Ban Thường vụ Thành ủy và Kế hoạch số 20-KH/BCĐ57 ngày 19/01/2026 của Ban Chỉ đạo 57 Thành ủy, chỉ đạo Ban Quản lý các Khu công nghệ cao và Khu công nghiệp Thành phố Hà Nội xây dựng kế hoạch triển khai theo nguyên tắc “6 rõ, 1 xuyên suốt”; xác định rõ lộ trình, nội dung công việc, phân công cụ thể cơ quan chịu trách nhiệm, bảo đảm tổ chức thực hiện quyết liệt, hiệu quả'),
(42, 4, 'Rà soát tổng thể khung pháp lý hiện hành đối với các khu công nghiệp, cụm công nghiệp và khu công nghệ cao; xác định rõ từng nội dung vướng mắc, nguyên nhân, trách nhiệm tham mưu và đề xuất phương án xử lý cụ thể; nhận diện rõ các điểm nghẽn, nội dung không còn phù hợp với định hướng phát triển mới của Thủ đô để đề xuất phương án điều chỉnh, bổ sung hoặc kiến nghị cấp có thẩm quyền xem xét, tháo gỡ theo quy định'),
(43, 4, 'Xây dựng bộ tiêu chí cụ thể, định lượng đối với việc chuyển đổi các khu công nghiệp theo hướng công nghệ cao, công nghệ xanh (ban hành rõ danh mục cấm, hạn chế, ưu tiên thu hút đầu tư); trong đó, nghiên cứu quy định các điều kiện bắt buộc về tỷ lệ sử dụng năng lượng sạch, quy hoạch kết nối hạ tầng đồng bộ, phát triển hạ tầng xã hội, nhà ở và tiện ích phục vụ chuyên gia, người lao động'),
(44, 4, 'Làm việc với tổng thầu triển khai tuyến đường sắt đô thị số 5 (Văn Cao - Hòa Lạc), lựa chọn phương án tối ưu nhằm đẩy nhanh tiến độ'),
(45, 4, 'Nghiên cứu, đề xuất phương án tổ chức vận tải hành khách từ trung tâm Thành phố đến Khu công nghệ cao Hòa Lạc trong thời gian tuyến đường sắt đô thị số 5 chưa hoàn thành đưa vào sử dụng, bảo đảm kết nối thuận tiện, hiệu quả'),
(46, 2, 'Tổng kết, đánh giá toàn diện mục tiêu đầu tư tại Khu Công nghệ cao  Hòa Lạc từ giai đoạn hình thành đến nay; xác định rõ nội dung còn phù hợp để tiếp tục kế thừa, nội dung đã lạc hậu cần kiên quyết bãi bỏ, đồng thời cập nhật các mục tiêu mới phù hợp với yêu cầu phát triển hệ sinh thái kinh tế tri thức. Nhận diện rõ thực trạng đầu tư phân tán, thiếu tính kết nối hạ tầng; làm rõ nguyên nhân chủ quan trong công tác giải phóng mặt bằng; bảo đảm mọi nguồn lực đầu tư được tập trung, trọng điểm, tuyệt đối không để tình trạng đầu tư manh mún kéo dài gây lãng phí. Đồng thời, nghiên cứu đa dạng hóa nguồn lực tài chính, không phụ thuộc hoàn toàn vào ngân sách nhà nước; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 15/03/2026'),
(47, 2, 'Rà soát toàn diện quy hoạch Khu Công nghệ cao Hòa Lạc đảm bảo tính đồng bộ, hiện đại, đáp ứng đầy đủ các tiêu chuẩn, quy chuẩn kỹ thuật hiện hành. Đảm bảo công tác quy hoạch phải đi trước một bước, có tầm nhìn chiến lược và tính khả thi cao, làm cơ sở để thu hút các nguồn lực đầu tư. Ban Quản lý các Khu công nghệ cao và Khu công nghiệp thành phố Hà Nội tổ chức công bố công khai bằng các hình thức phù hợp, hiện đại nhằm tạo điều kiện thuận lợi nhất cho các trường đại học, viện nghiên cứu, trung tâm R&D và doanh nghiệp công nghệ cao để tiếp cận thông tin, nghiên cứu và triển khai dự án. Xây dựng kế hoạch truyền thông chính sách và xúc tiến đầu tư có trọng tâm, gắn với ngành lõi và danh mục bài toán – sản phẩm – đơn hàng công nghệ mà Thành phố cam kết triển khai. Công tác xúc tiến phải chủ động, có chọn lọc, làm việc trực tiếp với doanh nghiệp mục tiêu và quỹ đầu tư chiến lược, định vị rõ Hòa Lạc là trung tâm công nghệ lõi có cơ chế vận hành minh bạch và cam kết đồng hành dài hạn'),
(48, 2, 'Đề xuất hoàn thiện mô hình phát triển và chức năng quản trị Ban Quản lý các Khu công nghệ cao và Khu công nghiệp thành phố Hà Nội theo hướng tinh gọn, hiệu lực, hiệu quả nhằm đáp ứng yêu cầu phát triển trong tình hình mới. Trong đó, làm rõ mô hình quản trị theo hướng “một đầu mối – một cam kết thời hạn”, bảo đảm mỗi dự án chiến lược có một đầu mối chịu trách nhiệm xuyên suốt, có cơ chế phối hợp liên thông giữa các sở, ngành và thẩm quyền xử lý nhanh các thủ tục liên quan; công khai thời gian xử lý trung bình đối với từng nhóm thủ tục để tạo kỷ luật thực thi và tăng tính minh bạch'),
(49, 2, 'Rà soát tổng thể công tác quản lý, sử dụng quỹ đất và tiến độ triển khai của tất cả các dự án đầu tư trong Khu Công nghệ cao Hòa Lạc. Đối với các dự án đã hoàn thành nhưng không đáp ứng yêu cầu khai thác hoặc có dấu hiệu chậm trễ gây lãng phí quỹ đất, yêu cầu chủ đầu tư phải khẩn trương xây dựng phương án điều chỉnh, khắc phục và cam kết tiến độ cụ thể. Tuyệt đối không để tình trạng dự án "treo" hoặc sử dụng đất kém hiệu quả kéo dài, gây thất thoát nguồn lực và ảnh hưởng đến hệ sinh thái phát triển chung. Nguyên tắc chung trong tổ chức thực hiện là bảo đảm “Đồng bộ, hiện đại, không lãng phí, hiệu quả cao”. Đối với các dự án phục vụ trực tiếp 07 điều kiện trọng tâm, nghiên cứu áp dụng cam kết hai chiều về tiến độ triển khai (nhà đầu tư phải ký cam kết tiến độ kèm bảo đảm thực hiện bằng tiền hoặc bảo lãnh tài chính); trường hợp chậm tiến độ không có lý do chính đáng xử lý theo cơ chế phạt, thu hồi hoặc điều chỉnh quy mô dự án'),
(50, 2, 'Xây dựng phương án bảo đảm cung ứng năng lượng và nước sạch; trường hợp nguồn cung điện không đáp ứng yêu cầu thì nghiên cứu phương án xã hội hóa cung cấp năng lượng sạch; khuyến khích áp dụng giải pháp công nghệ mới, thân thiện môi trường'),
(51, 2, 'Giao Đảng ủy UBND Thành phố lãnh đạo, chỉ đạo UBND Thành phố giao các sở, ban, ngành, chính quyền các địa phương xây dựng kế hoạch, lộ trình triển khai theo chức năng, nhiệm vụ và phạm vi dự án; gửi UBND Thành phố để tổng hợp, chỉ đạo triển khai; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 15/03/2026'),
(52, 14, 'Rà soát, đánh giá toàn diện hiệu quả triển khai Kế hoạch số 20-KH/BCĐ57 trên địa bàn Thành phố, đặc biệt là hiệu quả sau đầu tư đối với các nhiệm vụ khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số, bảo đảm các dự án có sản phẩm cụ thể và được khai thác, sử dụng hiệu quả. Trong đó làm rõ hiệu quả đầu tư trang thiết bị công nghệ thông tin cho 126 xã, phường và các điểm phục vụ hành chính công, nhất là mức độ phục vụ người dân, doanh nghiệp và nâng cao năng lực quản lý, điều hành của chính quyền cơ sở; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 15/3/2026'),
(53, 14, 'Chỉ đạo rà soát, đẩy nhanh tiến độ triển khai Đề án đô thị thông minh trên địa bàn Thành phố; báo cáo tình hình thực hiện, các nội dung đã triển khai, những khó khăn, vướng mắc và nhiệm vụ cần tập trung chỉ đạo trong thời gian tới;          báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 15/3/2026'),
(54, 14, 'Nghiên cứu, đề xuất phương án đặt hàng các trang thiết bị phục vụ triển khai đô thị thông minh trên địa bàn Thành phố, bảo đảm thiết bị đạt tiêu chuẩn quốc tế, giá thành phù hợp và tăng tỷ lệ nội địa hóa. Đối với các thiết bị cốt lõi, quan trọng, xây dựng lộ trình làm chủ công nghệ, nâng cao năng lực sản xuất trong nước, đáp ứng nhu cầu sử dụng và hướng tới xuất khẩu'),
(55, 15, 'Giao UBND Thành phố chỉ đạo triển khai việc đầu tư nâng cấp Trung tâm Cấp cứu 115 Hà Nội theo đề xuất của Sở Y tế tại Văn bản số 1863/SYT-NVY ngày 06/3/2026 (trụ sở, phương tiện và thiết bị, hạ tầng công nghệ...); định kỳ báo cáo kết quả thực hiện về Ban Chỉ đạo 57 Thành ủy (thông qua Văn phòng Thành ủy) trước ngày 25 hằng tháng để theo dõi, đôn đốc'),
(56, 16, 'Rà soát tổng thể các điều kiện bảo đảm triển khai Nghị quyết số 57-NQ/TW trên địa bàn Thành phố, nhất là về cơ chế, chính sách, nguồn lực, hạ tầng kỹ thuật, thiết bị, nhân lực, dữ liệu và an toàn thông tin; kịp thời tháo gỡ khó khăn, vướng mắc thuộc thẩm quyền; tổng hợp, đề xuất xử lý đối với những nội dung vượt thẩm quyền.'),
(57, 16, 'Rà soát, tính toán đầy đủ chi phí đầu tư, vận hành, duy trì hằng năm và hiệu quả mang lại của Khu Công nghệ cao Hòa Lạc để tham mưu giải pháp sử dụng nguồn lực chặt chẽ, hiệu quả, không để lãng phí kéo dài.'),
(58, 17, 'Về hệ thống Trung tâm giám sát, điều hành thông minh (IOC) Giao đồng chí Trương Việt Dũng, Phó Chủ tịch UBND Thành phố chủ trì, phối hợp với Văn phòng Thành ủy, Văn phòng UBND Thành phố, Sở Khoa học và Công nghệ và các cơ quan liên quan nghiên cứu, thống nhất khung chung, mô hình vận hành, nguyên tắc kết nối, liên thông, chia sẻ dữ liệu để từng bước nâng cấp, phát triển IOC của Thành ủy thành hệ thống IOC dùng chung của Thành phố, bảo đảm các cơ quan, đơn vị trên địa bàn Thành phố sử dụng trên một hệ thống thống nhất, tránh chồng chéo, phân tán.'),
(59, 17, 'Về công khai, minh bạch thông tin phục vụ thu hút đầu tư Giao đồng chí Trương Việt Dũng, Phó Chủ tịch UBND Thành phố chỉ đạo Sở Tài chính, Sở Quy hoạch - Kiến trúc, Sở Nông nghiệp và Môi trường, Sở Khoa học và Công nghệ và các cơ quan, đơn vị liên quan khẩn trương rà soát, chuẩn hóa, công khai trên nền tảng số Thành phố (iHanoi) các thông tin cần thiết phục vụ thu hút đầu tư trên địa bàn Thành phố; trước hết là các thông tin về thủ tục, quy trình, quy mô dự án, quy hoạch, đất đai và các nội dung có liên quan; hoàn thành trong tháng 4/2026.'),
(60, 17, 'Về dữ liệu dùng chung của Thành phố Giao đồng chí Trương Việt Dũng, Phó Chủ tịch UBND Thành phố chỉ đạo Sở Khoa học và Công nghệ chủ trì, phối hợp với các sở, ngành, cơ quan, đơn vị liên quan đẩy nhanh tiến độ xây dựng, hoàn thiện các cơ sở dữ liệu chuyên ngành, bảo đảm yêu cầu “đúng, đủ, sạch, sống”, thống nhất, dùng chung trong nội bộ và sẵn sàng kết nối, chia sẻ với cơ sở dữ liệu dùng chung của Thành phố (Datalakehouse); hoàn thành trước ngày 31/12/2026.'),
(61, 18, 'UBND Thành phố chỉ đạo các sở, ngành được giao chủ trì tập trung hoàn thiện 20 văn bản trọng tâm cụ thể hóa Luật Thủ đô trong lĩnh vực khoa học, công nghệ, đổi mới sáng tạo, chuyển đổi số và phát triển Khu Công nghệ cao. Đối với từng văn bản, phải xác định rõ cơ quan chủ trì, cơ quan phối hợp, đường găng tiến độ, sản phẩm đầu ra và mốc hoàn thành từ khâu xây dựng dự thảo, lấy ý kiến, thẩm định, trình ban hành đến tổ chức thực hiện sau ban hành. Định kỳ hằng tuần cập nhật kết quả gửi Văn phòng Thành ủy - Cơ quan Thường trực Ban Chỉ đạo 57 Thành ủy để theo dõi, tổng hợp.'),
(62, 18, 'UBND Thành phố chỉ đạo Trung tâm Phục vụ hành chính công Thành phố chủ trì, phối hợp với các sở, ngành, cơ quan liên quan chuyển 25 dịch vụ công trực tuyến trọng điểm từ rà soát phương án sang cấu hình quy trình, kiểm thử, vận hành thực tế.'),
(63, 18, 'Đối với từng thủ tục, phải xác định rõ quy trình tái cấu trúc, dữ liệu cần khai thác, cơ quan phối hợp, thời hạn vận hành, chỉ tiêu giảm giấy tờ, giảm thời gian, giảm chi phí tuân thủ cho người dân, doanh nghiệp.'),
(64, 18, 'Tập trung xử lý các vướng mắc trong nhóm thủ tục có lưu lượng hồ sơ lớn, nhất là chứng thực bản sao, chứng thực chữ ký, đăng ký giao dịch bảo đảm và các thủ tục có khả năng chuyển toàn trình thực chất; làm rõ vướng mắc thuộc quy định pháp luật, kỹ thuật hệ thống hay tổ chức thực hiện để đề xuất phương án xử lý'),
(65, 18, 'UBND Thành phố chỉ đạo rà soát hệ thống nhiệm vụ, chỉ tiêu, sản phẩm chuyển đổi số theo 03 trụ cột: chính quyền số, kinh tế số, xã hội số. Việc đánh giá phải gắn với các chỉ tiêu phản ánh tác động thực tế đối với người dân, doanh nghiệp, gồm: mức giảm giấy tờ, thời gian, chi phí tuân thủ; tỷ lệ sử dụng dịch vụ số; tỷ lệ dữ liệu được tái sử dụng; mức độ hài lòng của người dân, doanh nghiệp; đóng góp của kinh tế số và mức độ phổ cập kỹ năng số trong xã hội. Lựa chọn một số nhiệm vụ chuyển đổi số thiết thực, có khả năng tạo chuyển biến rõ trong năm 2026 để tập trung triển khai; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 25/5/2026.'),
(66, 18, 'UBND Thành phố chỉ đạo rà soát, hoàn thiện mô hình phát triển Khu Công nghệ cao Hòa Lạc và Trung tâm Đổi mới sáng tạo Hà Nội gắn với nhu cầu phát triển của Thành phố. Trong năm 2026, phải xác định rõ sản phẩm đầu ra, mô hình có khả năng thử nghiệm, sản phẩm có khả năng ứng dụng, cơ chế lựa chọn, tiêu chí đánh giá và phương án nhân rộng.'),
(67, 18, 'UBND Thành phố chỉ đạo các sở, ngành, cơ quan, đơn vị liên quan đẩy nhanh tiến độ giải ngân các nhiệm vụ, dự án khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số. Rà soát các nhiệm vụ, dự án có kinh phí lớn nhưng giải ngân thấp; làm rõ vướng mắc ở từng khâu: hồ sơ, thẩm định, phê duyệt, đấu thầu, mua sắm, thuê dịch vụ, nghiệm thu, vận hành sau đầu tư; đề xuất phương án tháo gỡ cụ thể. Việc báo cáo nguồn lực phải làm rõ số đã giải ngân, sản phẩm đã hình thành, hệ thống đã vận hành và hiệu quả đã tạo ra; không dừng ở số vốn đã bố trí, đã phân bổ. Định kỳ hằng tuần cập nhật kết quả gửi Văn phòng Thành ủy - Cơ quan Thường trực Ban Chỉ đạo 57 Thành ủy để theo dõi, tổng hợp.'),
(68, 3, 'Giao Đảng uỷ UBND Thành phố lãnh đạo UBND Thành phố chỉ đạo tổ chức triển khai khung năng lực số của Bí thư, Chủ tịch các xã, phường; xây dựng chương trình, tài liệu tập huấn, bồi dưỡng; tổ chức đánh giá năng lực số; theo dõi, tổng hợp, báo cáo Thường trực Thành ủy, Ban Thường vụ Thành ủy kết quả thực hiện; hoàn thành trước ngày 30/5/2026'),
(69, 4, 'Rà soát, đánh giá toàn diện việc thực hiện các nhiệm vụ được phân công tại Kế hoạch số 20-KH/BCĐ57 ngày 19/01/2026; khu trú các nhiệm vụ trọng tâm, cấp bách, có tác động lớn, có khả năng tạo chuyển biến rõ trong năm 2026; xác định rõ nhiệm vụ nào tiếp tục thực hiện ngay, nhiệm vụ nào cần điều chỉnh tiến độ, phạm vi, sản phẩm đầu ra hoặc phương thức triển khai; mạnh dạn đề xuất giãn, dừng hoặc chuyển phương thức thực hiện đối với các nhiệm vụ chưa đủ điều kiện, còn hình thức, chưa rõ hiệu quả, chưa rõ nguồn lực; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 10/6/2026. (đã được nhắc lại tại TBKL 111-TB/VPTU)'),
(70, 4, 'Hoàn thiện các cơ chế, chính sách thuộc thẩm quyền trong lĩnh vực khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số; trọng tâm là đặt hàng, mua sắm sản phẩm khoa học công nghệ, thử nghiệm có kiểm soát, quỹ phát triển khoa học công nghệ và đổi mới sáng tạo, bảo hộ, định giá tài sản trí tuệ, chia sẻ, truy cập, khai thác dữ liệu, giao nhiệm vụ, nghiệm thu, thương mại hóa sản phẩm; hoàn thành trước ngày 15/6/2026.'),
(71, 4, 'Chỉ đạo lựa chọn một số nhóm dữ liệu trọng yếu có tác động trực tiếp đến quản lý, điều hành và thẩm định hồ sơ, gồm dữ liệu quy hoạch, đầu tư, tài chính - ngân sách, xây dựng, hạ tầng kỹ thuật; thực hiện chuẩn hóa, làm sạch, gắn nhãn dữ liệu, xây dựng API chia sẻ, tích hợp vào kho dữ liệu dùng chung của Thành phố; thí điểm sử dụng trong quy trình thẩm định dự án, đầu tư, xây dựng, tài chính - ngân sách nhằm tạo lực kéo thực chất cho chuyển đổi số, giảm thời gian xử lý hồ sơ, giảm yêu cầu cung cấp lại thông tin đã có trong hệ thống.'),
(72, 4, 'Về hạ tầng số, trung tâm dữ liệu, kho dữ liệu dùng chung, trung tâm tính toán hiệu năng cao và nền tảng AI dùng chung: phân loại rõ nội dung cần đầu tư, quản trị trực tiếp và nội dung thuê dịch vụ; đề xuất phương án đầu tư, thuê dịch vụ, quản trị, khai thác, bảo đảm hiệu quả, tránh dàn trải, lãng phí.'),
(73, 4, 'Nghiên cứu triển khai một số nhiệm vụ thử nghiệm có kiểm soát đối với các công nghệ chiến lược, lĩnh vực Thành phố có nhu cầu, có lợi thế; gắn với đặt hàng giải quyết các bài toán lớn của Thành phố, bảo đảm rõ đầu bài, sản phẩm đầu ra, tiêu chí đánh giá, nghiệm thu và phương án nhân rộng sau thử nghiệm. Các nhiệm vụ có tính chất thường xuyên phải được đưa vào kế hoạch theo dõi, cập nhật kết quả định kỳ; kịp thời báo cáo Ban Chỉ đạo 57 Thành ủy đối với nội dung cần xin chủ trương, tháo gỡ khó khăn, vướng mắc hoặc vượt thẩm quyền.'),
(74, 4, 'Rà soát, báo cáo phương án phát triển tổng thể Khu Công nghệ cao Hòa Lạc, nhất là khu vực mở rộng, theo hướng xác định Hòa Lạc là hạt nhân phát triển công nghệ cao, khoa học công nghệ và đổi mới sáng tạo của Thủ đô; nghiên cứu mô hình thu hút nhà đầu tư chiến lược có năng lực tài chính, công nghệ, quản trị, phát triển hạ tầng và xúc tiến đầu tư để tham gia phát triển tổng thể, quy mô lớn. Nhà đầu tư chiến lược được lựa chọn phải có khả năng tổ chức đầu tư đồng bộ hạ tầng kỹ thuật, hạ tầng đổi mới sáng tạo, hạ tầng dịch vụ; đồng thời có năng lực thu hút, dẫn dắt các nhà đầu tư thứ cấp, doanh nghiệp công nghệ cao, trung tâm R&D, phòng thí nghiệm, cơ sở đào tạo, quỹ đầu tư, doanh nghiệp vệ tinh và các thành phần của hệ sinh thái công nghệ cao. Thành phố giữ vai trò định hướng quy hoạch, xác lập tiêu chí lựa chọn nhà đầu tư, cơ chế giám sát, tiêu chuẩn công nghệ, hiệu quả sử dụng đất và yêu cầu phát triển hệ sinh thái; nghiên cứu cơ chế hỗ trợ phù hợp để nhà đầu tư chiến lược triển khai nhanh, đồng bộ, tiết kiệm nguồn lực ngân sách và nâng cao hiệu quả thu hút đầu tư.'),
(75, 19, 'Về cơ sở dữ liệu, kho dữ liệu dùng chung và số hóa hồ sơ, tài liệu: Giao UBND Thành phố chỉ đạo các sở, ngành, cơ quan, đơn vị khẩn trương chuẩn hóa, kết nối, chia sẻ dữ liệu thuộc phạm vi quản lý về kho dữ liệu dùng chung của Thành phố, bảo đảm hoàn thành trước ngày 30/8/2026. Thủ trưởng các cơ quan, đơn vị chịu trách nhiệm về chất lượng, tính đầy đủ, chính xác, khả năng kết nối, chia sẻ, khai thác dữ liệu; phân công lãnh đạo phụ trách, đầu mối chuyên môn phối hợp với Sở Khoa học và Công nghệ trong quá trình thực hiện'),
(76, 19, 'Về hệ thống IOC và điều hành đô thị thông minh: Giao đồng chí Trương Việt Dũng, Phó Chủ tịch UBND Thành phố chủ trì chỉ đạo Sở Khoa học và Công nghệ, Văn phòng Thành ủy, Văn phòng UBND Thành phố và các cơ quan liên quan rà soát, thống nhất mô hình triển khai IOC và các nền tảng dùng chung của Thành phố; bảo đảm kết nối, liên thông, khai thác dữ liệu từ kho dữ liệu dùng chung, tránh phân tán, chồng chéo, đầu tư trùng lặp, phát sinh nhiều hệ thống không đồng bộ.'),
(77, 19, 'Về hệ thống IOC và điều hành đô thị thông minh: Đối với lĩnh vực thoát nước, ngập úng đô thị, thủy lợi, giao UBND Thành phố chỉ đạo các sở, ngành liên quan rà soát hiện trạng dữ liệu, hệ thống, quy trình vận hành; đề xuất phương án số hóa, kết nối, điều hành trên nền tảng đô thị thông minh, phục vụ công tác chỉ đạo, điều hành trong mùa mưa.'),
(78, 19, 'Về kinh tế số, đổi mới sáng tạo và doanh nghiệp khoa học công nghệ: Giao UBND Thành phố rà soát, đánh giá toàn diện các đơn vị sự nghiệp công lập và doanh nghiệp nhà nước trực thuộc Thành phố có tiềm năng về khoa học công nghệ; đề xuất cơ chế đặt hàng, hỗ trợ đầu tư, khai thác nguồn lực phục vụ phát triển khoa học công nghệ, đổi mới sáng tạo và kinh tế số trên địa bàn Thành phố.'),
(79, 6, 'Rà soát, phân loại các đề xuất, kiến nghị của Ban Quản lý các Khu công nghệ cao và Khu công nghiệp thành phố Hà Nội; chủ động xem xét, xử lý theo thẩm quyền. Đối với nội dung vượt thẩm quyền, báo cáo cấp có thẩm quyền xem xét, quyết định. Kết quả rà soát, xử lý được tổng hợp trong Báo cáo tổng thể trình Ban Thường vụ Thành ủy.'),
(80, 20, 'Rà soát, đánh giá toàn diện việc thực hiện 65 nhiệm vụ phát triển kinh tế số; làm rõ kết quả, sản phẩm, nguyên nhân, trách nhiệm đối với các nhiệm vụ chậm, chưa hoàn thành. Tập trung kiểm điểm tiến độ và kết quả thực hiện 55 nhiệm vụ còn lại trong tháng 7/2026; đưa tiến độ, kết quả thực hiện vào chương trình giao ban định kỳ của UBND Thành phố.'),
(81, 20, 'Sớm tổ chức triển khai nhiệm vụ phát triển kinh tế số đến xã, phường; kịp thời nhân rộng các mô hình hiệu quả, gắn kết quả thực hiện với trách nhiệm người đứng đầu. Tăng cường cung cấp thông tin về cơ chế, chính sách của Thành phố; tổ chức làm việc với Hiệp hội Doanh nghiệp sản xuất sản phẩm công nghiệp chủ lực Thành phố và các doanh nghiệp để xác định nhu cầu, chuẩn hóa bài toán, lựa chọn nhiệm vụ có thể hợp tác, đặt hàng.'),
(82, 20, 'Đẩy mạnh kích cung, kích cầu, thương mại điện tử, chương trình khuyến mại và quảng bá sản phẩm Thủ đô trên môi trường số, trước hết đối với sản phẩm OCOP, sản phẩm làng nghề. Khẩn trương hoàn thiện, đưa gian hàng OCOP Thủ đô tại Cảng hàng không Quốc tế Nội Bài hoạt động vào dịp 19/8/2026.'),
(83, 20, 'Khẩn trương tổ chức đào tạo về trí tuệ nhân tạo và kinh tế số cho đội ngũ cán bộ, công chức, viên chức, người lao động trong hệ thống chính trị thành phố Hà Nội. Nghiên cứu hình thức kiểm tra, đánh giá thực chất năng lực số của đội ngũ lãnh đạo, quản lý, gắn đào tạo với khả năng ứng dụng trong thực tiễn.'),
(84, 20, 'Trên cơ sở kết quả rà soát, xác định các viện nghiên cứu, trường đại học, doanh nghiệp và đối tác trong nước, quốc tế có năng lực để phối hợp thực hiện; nghiên cứu hình thức giao nhiệm vụ, đặt hàng phù hợp. Đối với sản phẩm đáp ứng yêu cầu, Thành phố xem xét trở thành khách hàng đầu tiên để tạo thị trường và thúc đẩy đổi mới sáng tạo.'),
(85, 20, 'Rà soát, đề xuất danh mục nhiệm vụ nghiên cứu, thử nghiệm, đặt hàng, tập trung vào các lĩnh vực vật liệu thay thế, vật liệu san lấp và tái chế phế thải xây dựng; mô hình, giống cây, con và sản phẩm nông nghiệp công nghệ cao; xử lý nước thải tại nguồn; năng lượng sạch, chuyển đổi xanh và hạ tầng đô thị thông minh...'),
(86, 20, 'Rà soát, bổ sung tiêu chuẩn, quy chuẩn, định mức kỹ thuật áp dụng đối với khu đô thị mới, bảo đảm hạ tầng cấp, thoát nước, cấp điện, viễn thông và hào kỹ thuật được quy hoạch, đầu tư đồng bộ; quy định trách nhiệm tạo lập, cập nhật, kết nối dữ liệu và bảo đảm dữ liệu thuộc quyền quản lý của Thành phố.'),
(87, 20, 'Rà soát quỹ đất, hạ tầng còn dư địa tại các khu, cụm công nghiệp; nghiên cứu cơ chế bố trí đất, hạ tầng để hỗ trợ doanh nghiệp khoa học và công nghệ. Làm rõ chi phí đầu tư hạ tầng, nghĩa vụ tài chính, phương thức bố trí và tiêu chí lựa chọn doanh nghiệp, bảo đảm đúng quy hoạch, thẩm quyền và quy định pháp luật.'),
(88, 20, 'Nghiên cứu, đề xuất cơ chế giao nhiệm vụ, đặt hàng và lựa chọn nhà thầu phù hợp để huy động các doanh nghiệp khoa học và công nghệ của Thủ đô tham gia giải quyết các bài toán của Thành phố. Việc lựa chọn phải căn cứ năng lực làm chủ công nghệ, chất lượng sản phẩm, giải pháp và khả năng đáp ứng yêu cầu đăng ký bản quyền; bảo đảm công khai, minh bạch, đúng quy định.'),
(89, 20, 'Rà soát, xác định rõ cơ quan quản lý nhà nước, chủ đầu tư, đơn vị quản lý, khai thác, vận hành và cơ chế phối hợp; bảo đảm Sở Xây dựng thực hiện đầy đủ trách nhiệm quản lý nhà nước, tham gia xác định đầu bài, yêu cầu quản lý, khai thác và vận hành. Bảo đảm các hệ thống được tích hợp trong kiến trúc tổng thể của Trung tâm Điều hành thông minh Thành phố; không đầu tư phân tán, chồng chéo, thiếu khả năng kết nối.'),
(90, 20, 'Tập trung thực hiện 03 nhóm nhiệm vụ: (1) xây dựng đề án tổng thể, dài hạn về thoát nước đô thị; (2) phân công rõ trách nhiệm, xử lý ngay các vấn đề phát sinh trong mùa mưa trên cơ sở hạ tầng, thiết bị và hệ thống hiện có; (3) tập hợp, làm sạch, chuẩn hóa, kết nối dữ liệu phục vụ quản lý, giám sát, dự báo, điều hành và quyết định đầu tư.'),
(91, 20, 'Chuẩn hóa bài toán lớn về thoát nước, kiểm soát úng ngập; nghiên cứu tổng thể mối quan hệ giữa thoát nước đô thị với hệ thống thủy lợi, lưu vực sông, cốt nền, quá trình đô thị hóa và quy hoạch Thủ đô; phân định rõ hệ thống thu gom, xử lý nước mưa, nước thải. Xây dựng mô hình mô phỏng phục vụ dự báo, điều hành và làm căn cứ cho quyết định đầu tư.'),
(92, 20, 'Nghiên cứu lựa chọn tổ chức tư vấn, chuyên gia có uy tín, kinh nghiệm thực tế và khả năng đồng hành lâu dài với Thành phố trong công tác quy hoạch, đầu tư, quản lý và vận hành hệ thống thoát nước.'),
(93, 20, 'Chỉ đạo Công ty Cổ phần Trung tâm Đổi mới sáng tạo Hà Nội nghiên cứu, đánh giá doanh nghiệp, viện nghiên cứu, trường đại học và các tổ chức khoa học, công nghệ; tham mưu các nội dung Thành phố cần đặt hàng, hỗ trợ hoặc xem xét đầu tư, góp vốn theo quy định.'),
(94, 20, 'Giao Đảng ủy UBND Thành phố lãnh đạo, chỉ đạo UBND Thành phố tổ chức thực hiện các nhiệm vụ tại Thông báo này; phân công rõ trách nhiệm của từng sở, ngành, đơn vị. Các cơ quan, đơn vị được giao nhiệm vụ chịu trách nhiệm trực tiếp về tiến độ, chất lượng và sản phẩm đầu ra; chủ động phối hợp, không đùn đẩy, né tránh trách nhiệm.'),
(95, 21, 'Giao đồng chí Trương Việt Dũng, Phó Chủ tịch UBND Thành phố, chỉ đạo Văn phòng UBND Thành phố phối hợp với Văn phòng Thành ủy rà soát, thống nhất đầu bài, mô hình, phạm vi chức năng và phương án triển khai Hệ thống IOC dùng chung của Thành phố. Hệ thống IOC phải phục vụ hoạt động của 04 trục, là cấu phần của Thành phố thông minh, bảo đảm lãnh đạo Thành phố bao quát, giám sát công việc; Thành phố chỉ có một Hệ thống IOC dùng chung, không để chồng chéo, trùng lặp chức năng và dữ liệu. Chưa quyết định đơn vị triển khai chính thức khi chưa có kết quả thử nghiệm, đánh giá.'),
(96, 22, 'Ban hành văn bản chỉ đạo các cơ quan, đơn vị trên địa bàn thành phố về chỉnh lý, số hóa hồ sơ, tài liệu bảo đảm đúng quy định và hạn chế tối đa lãng phí ngân sách nhà nước.'),
(97, 22, 'Tiếp tục chỉ đạo các sở, ban, ngành tập trung hoàn thành 14 nhóm cơ sở dữ liệu ưu tiên trước ngày 30/8/2026'),
(98, 22, 'Đối với các cơ sở dữ liệu thuộc giai đoạn tiếp theo, chỉ đạo các sở, ban, ngành khẩn trương rà soát nhiệm vụ, hiện trạng dữ liệu, nhu cầu kinh phí và điều kiện tổ chức thực hiện bảo đảm rõ mục tiêu, sản phẩm và khả năng khai thác, sử dụng dữ liệu hiệu quả trên thực tế.'),
(99, 22, 'Trực tiếp chỉ đạo việc khai thác, sử dụng các cơ sở dữ liệu của Thành phố, trước hết là dữ liệu phục vụ giải quyết thủ tục hành chính; tái sử dụng dữ liệu đã có để cắt giảm thành phần hồ sơ, biểu mẫu và các trường thông tin người dân, doanh nghiệp phải kê khai.'),
(100, 22, 'chỉ đạo rà soát, hoàn thiện quy chế về quản lý, xác thực, kết nối, chia sẻ và khai thác dữ liệu; hoàn thành trước ngày 30/9/2026.'),
(101, 22, 'Nghiên cứu phương án điều chỉnh địa giới hành chính theo hướng bảo đảm Khu Công nghệ cao Hòa Lạc thuộc một đơn vị hành chính cấp xã, thống nhất đầu mối quản lý; báo cáo cấp có thẩm quyền xem xét, quyết định.'),
(102, 5, 'Giao UBND Thành phố tập trung chỉ đạo, khẩn trương xử lý dứt điểm 04  nhiệm vụ quá hạn đã được đồng chí Bí thư Thành ủy giao tại các Thông báo kết luận số 420-TB/TU ngày 12/5/2026 và số 452-TB/TU ngày 24/5/2026; xác định rõ trách nhiệm của cơ quan, đơn vị, người đứng đầu; hoàn thành, báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 15/9/2026.'),
(103, 5, 'UBND Thành phố tập trung chỉ đạo rà soát toàn bộ nhiệm vụ, dự án và kế hoạch vốn khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số; làm rõ khối lượng thực hiện, khả năng giải ngân, khó khăn, vướng mắc và trách nhiệm của từng cơ quan, đơn vị. Đến hết ngày 30/9/2026, yêu cầu các cơ quan, đơn vị đạt tỷ lệ giải ngân tối thiểu 60% kế hoạch vốn được giao; tập trung tháo gỡ khó khăn, đẩy nhanh thủ tục và khối lượng thực hiện đối với các nhiệm vụ, dự án có khả năng giải ngân. Sau thời điểm này, đối với các đơn vị không đạt tỷ lệ giải ngân tối thiểu theo yêu cầu do nguyên nhân chủ quan, UBND Thành phố kiên quyết cắt giảm, điều chuyển vốn sang các đơn vị có nhu cầu thực tế. Việc cắt giảm, điều chuyển vốn không làm thay đổi trách nhiệm hoàn thành nhiệm vụ đã được giao và trách nhiệm của cơ quan, đơn vị, người đứng đầu đối với nhiệm vụ chậm tiến độ, không hoàn thành.'),
(104, 5, 'Đồng chí Trương Việt Dũng, Phó Chủ tịch UBND Thành phố tiếp tục trực tiếp chỉ đạo, làm việc với các sở, ban, ngành; tổ chức hội nghị chuyên đề để rà soát tổng thể tiến độ xây dựng, chuẩn hóa, kết nối, chia sẻ và khai thác các cơ sở dữ liệu; làm rõ trách nhiệm, nguồn lực và phương án xử lý đối với từng nhiệm vụ; tập trung giải quyết dứt điểm các nhiệm vụ chậm, chưa có kết quả cụ thể. Từ quý IV/2026, các cơ sở dữ liệu đã được xây dựng, chuẩn hóa phải được đưa vào khai thác, sử dụng thực tế; dữ liệu bảo đảm chất lượng đến đâu tổ chức khai thác, sử dụng đến đó, không chờ hoàn thiện toàn bộ.'),
(105, 5, 'UBND Thành phố tập trung chỉ đạo phát triển kinh tế số theo hướng thực chất, gắn với từng ngành, lĩnh vực, địa bàn và sản phẩm cụ thể; hoàn thiện phương pháp, công cụ đánh giá, đo lường đóng góp của kinh tế số ngành; lấy doanh thu mới, năng suất tăng thêm, chi phí được cắt giảm và sản phẩm, dịch vụ mới hình thành làm căn cứ đánh giá kết quả. Tiếp tục hoàn thiện tiêu chí đánh giá mức độ sử dụng dịch vụ công trực tuyến, tiêu chí và phương pháp đánh giá, xếp hạng xã hội số, kinh tế số đối với các xã, phường, sở, ban, ngành; đánh giá thực chất hiệu quả hoạt động của Tổ chuyển đổi số cộng đồng và phong trào Bình dân học vụ số; tổ chức làm việc với các hội, hiệp hội doanh nghiệp Thành phố để thông tin, công bố, hướng dẫn doanh nghiệp tiếp cận các cơ chế, chính sách ưu đãi của Thành phố, nhất là các chính sách đặc thù theo Luật Thủ đô và cơ chế hỗ trợ từ Quỹ Đầu tư mạo hiểm.'),
(106, 23, 'Ủy ban MTTQ Việt Nam Thành phố tập trung xây dựng và triển khai mô hình “Thôn, tổ dân phố số”, phát huy vai trò của Mặt trận trong tuyên truyền, vận động, tổ chức thực hiện và giám sát từ cộng đồng dân cư. Nhiệm vụ năm 2026 cần xác định rõ nội dung, lộ trình triển khai, tiêu chí đánh giá và sản phẩm cụ thể.'),
(107, 8, 'lãnh đạo, chỉ đạo triển khai chuyển đổi số đồng bộ, thực chất, xác định đây là yêu cầu bắt buộc, không làm hình thức. Kiên quyết đổi mới phương thức lãnh đạo, chỉ đạo, điều hành và tổ chức thực hiện nhiệm vụ trên môi trường số; chấm dứt tình trạng vận hành song song giữa phương thức truyền thống và phương thức số đối với các quy trình, nghiệp vụ đã đủ điều kiện. Chậm nhất trước ngày 15/02/2026, ban hành Kế hoạch chuyển đổi số toàn hệ thống chính trị Thành phố (phân công rõ đầu mối, nhiệm vụ, lộ trình, chỉ tiêu định lượng, nguồn lực); gắn kết quả chuyển đổi số với trách nhiệm người đứng đầu và đánh giá mức độ hoàn thành nhiệm vụ của từng cơ quan, đơn vị.'),
(108, 7, 'Ban Tuyên giáo và Dân vận Thành ủy chủ trì lãnh đạo, chỉ đạo công tác thông tin, tuyên truyền, định hướng nhận thức trong cán bộ, đảng viên và Nhân dân về mục tiêu, ý nghĩa và các nội dung của Kế hoạch hành động năm 2026 của Ban chỉ đạo 57 Thành ủy.'),
(109, 24, 'Ban Tuyên giáo và Dân vận Thành ủy chủ trì, phối hợp với các cơ quan liên quan chủ động tổ chức công tác thông tin, tuyên truyền về chủ trương, định hướng và kết quả triển khai các nhiệm vụ theo đúng nội dung, phạm vi và phân công của Thành ủy'),
(110, 16, 'Đẩy mạnh tuyên truyền, nâng cao nhận thức, tạo sự thống nhất cao trong toàn hệ thống chính trị; công khai tiến độ các nhiệm vụ trọng tâm, các nhiệm vụ chậm, các khó khăn, vướng mắc lớn và kết quả xử lý trên các nền tảng phù hợp.'),
(111, 7, 'Giao Ban Tổ chức Thành ủy rà soát, đánh giá toàn diện chất lượng đội ngũ cán bộ, công chức, viên chức của bốn khối: Đảng, Hội đồng nhân dân, Ủy ban nhân dân và Ủy ban Mặt trận Tổ quốc Việt Nam Thành phố. Trên cơ sở đó, xây dựng phương án bố trí, sử dụng hiệu quả; kiên quyết tổ chức đào tạo, bồi dưỡng lại hoặc thay thế, sắp xếp lại đối với những cán bộ không đáp ứng yêu cầu, tư duy chậm đổi mới, làm hạn chế tiến trình chuyển đổi số và phát triển Thành phố.'),
(112, 24, 'Từ thực trạng báo cáo của Ban Quản lý các Khu công nghệ cao và Khu công nghiệp Thành phố cho thấy công tác quản lý, điều hành còn nhiều tầng nấc trung gian, rườm rà, thiếu hiệu quả, lạc hậu. Do vậy phải nghiên cứu xây dựng mô hình quản trị tiên tiến; rõ vai trò, trách nhiệm, tinh gọn thủ tục hành chính. Giao Ban Tổ chức Thành ủy chủ trì, chỉ đạo Sở Nội vụ tiếp tục rà soát việc phân công, phân cấp trong lĩnh vực này, bảo đảm khắc phục triệt để các hạn chế nêu trên; đồng thời đánh giá toàn diện chất lượng đội ngũ cán bộ, công chức, viên chức của Thành phố, trên cơ sở đó xây dựng phương án bố trí, sử dụng cán bộ phù hợp, hiệu quả và kế hoạch đào tạo, bồi dưỡng đáp ứng yêu cầu phát triển mới của Thành phố'),
(113, 3, 'Giao Ban Tổ chức Thành ủy nghiên cứu, tham mưu việc sử dụng khung năng lực số làm căn cứ trong công tác đánh giá, bồi dưỡng đối với Bí thư, Chủ tịch các xã, phường theo thẩm quyền, bảo đảm phù hợp với quy định của Trung ương và Thành ủy'),
(114, 21, '(1) Chủ trì, chịu trách nhiệm đến cùng về việc đánh giá cán bộ trên nền tảng số; chuẩn hóa đầu bài, xác định rõ mục tiêu, yêu cầu, nội dung, thứ tự ưu tiên và lộ trình thực hiện theo từng giai đoạn; phân nhóm đối tượng, xác định thẩm quyền, trách nhiệm và tiêu chí đánh giá phù hợp'),
(115, 21, '(2) Chủ trì, phối hợp với Văn phòng Thành ủy, Sở Khoa học và Công nghệ, Trung tâm Phục vụ hành chính công Thành phố và các cơ quan liên quan tổ chức làm việc, khảo sát trực tiếp tại một số xã, phường, sở, ban, ngành và nhóm cán bộ trực tiếp thực hiện; tập trung vào 03 nhóm nội dung: (i) Nhận thức và mức độ thống nhất về yêu cầu đánh giá cán bộ; (ii) Sự phù hợp của phương pháp, quy trình tổ chức đánh giá; (iii) Ưu điểm, hạn chế của công cụ đánh giá trên HanoiWork và kiến nghị điều chỉnh. Tổng hợp, báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 15/8/2026'),
(116, 21, '(3) Chủ trì, phối hợp với Sở Nội vụ và các cơ quan liên quan xây dựng mẫu giao nhiệm vụ thống nhất trong toàn Thành phố; xác định rõ nội dung nhiệm vụ, người giao, người thực hiện, thời hạn, sản phẩm. Giao Sở Nội vụ tổ chức thanh tra công vụ việc giao nhiệm vụ; đề xuất chế tài xử lý, bảo đảm thực hiện nghiêm túc, đồng bộ trong khối Đảng, khối Mặt trận Tổ quốc và khối chính quyền Thành phố'),
(117, 21, '(4) Trên cơ sở kết quả khảo sát và thông số thực tế, điều chỉnh kế hoạch tổng thể về đánh giá cán bộ trên nền tảng số; từng bước liên thông kết quả đánh giá với công tác phân công, bố trí, quy hoạch, đào tạo, bồi dưỡng, điều động và luân chuyển cán bộ, phấn đấu có kết quả bước đầu vào cuối năm 2026.'),
(118, 22, 'Chủ trì, phối hợp Văn phòng Thành ủy, Sở Khoa học và Công nghệ khẩn trương hoàn thiện phương án tổ chức tập huấn về trí tuệ nhân tạo và kinh tế số cho đội ngũ cán bộ trong hệ thống chính trị Thành phố trong tháng 8/2026.'),
(119, 5, 'Giao Ban Tổ chức Thành ủy, Sở Nội vụ, Trung tâm Phục vụ hành chính công Thành phố và Sở Tư pháp phối hợp rà soát, xác định phương án đối với lao động hợp đồng theo Nghị quyết số 26/2024/NQ-HĐND đang thực hiện nhiệm vụ tiếp nhận, giải quyết hồ sơ tại các Điểm Hỗ trợ dịch vụ công số trên địa bàn xã, phường; hoàn thành trước ngày 30/12/2026, bảo đảm ổn định đội ngũ và hoạt động của các Điểm Hỗ trợ dịch vụ công số.'),
(120, 5, 'Ban Tổ chức Thành ủy, Sở Nội vụ phối hợp với Sở Khoa học và Công nghệ rà soát, dự báo nhu cầu nguồn nhân lực công nghệ đến năm 2030; trên cơ sở đó tham mưu xây dựng Đề án đào tạo và thu hút nguồn nhân lực chất lượng cao phục vụ thực hiện Nghị quyết số 57-NQ/TW, gắn với đặt hàng đào tạo, tuyển dụng và chính sách thu hút nhân lực chất lượng cao.'),
(121, 9, 'Xây dựng Đề án phát triển đô thị thông minh thành phố Hà Nội'),
(122, 25, 'tham mưu, lựa chọn nhóm chuyên gia (Kiến trúc sư trưởng) về văn hóa và  công nghệ phục vụ xây dựng, triển khai Đề án phát triển đô thị thông minh thành 
 phố Hà Nội'),
(123, 23, 'Rà soát một số văn bản liên quan đến tạm dừng triển khai camera trên địa bàn; phân định rõ phạm vi tạm dừng, tránh gây ảnh hưởng đến hoạt động của các hệ thống camera phục vụ quản lý, vận hành chuyên ngành, nội bộ của các cơ quan, đơn vị. Tham mưu ban hành thống nhất quy chuẩn, tiêu chuẩn, quy chế kết nối; tạo điều kiện để các sở, ngành, địa phương chủ động triển khai theo phân cấp, bảo đảm hiệu quả, đồng bộ.'),
(124, 23, 'Chủ trì, phối hợp với các cơ quan, đơn vị liên quan tổ chức rà soát tổng thể hiện trạng các hệ thống camera hiện có của các đơn vị trên địa bàn Thành phố; ưu tiên kết nối, tích hợp và khai thác hiệu quả các hệ thống đã đầu tư'),
(125, 7, 'Xây dựng lộ trình triển khai chi tiết và khung kiến trúc tổng thể về lắp đặt hệ thống camera AI; xác định đây là điều kiện tiên quyết để xem xét, phê duyệt và tổ chức thực hiện, bảo đảm tính thống nhất, đồng bộ và hiệu quả đầu tư'),
(126, 16, 'Rà soát, đánh giá tình hình kết nối, tích hợp, chia sẻ dữ liệu; bảo đảm an ninh, an toàn dữ liệu, an ninh mạng trong toàn bộ quá trình triển khai.'),
(127, 18, 'Công an Thành phố chủ trì, phối hợp với Sở Khoa học và Công nghệ, Văn phòng Thành ủy và các cơ quan, đơn vị liên quan triển khai Trung tâm giám sát an ninh mạng, hệ thống camera AI và các nền tảng phục vụ an ninh, trật tự, quản trị đô thị thông minh.'),
(128, 18, 'Rà soát, phân loại, đôn đốc phê duyệt cấp độ an toàn thông tin đối với các hệ thống thông tin của Thành phố, trước hết là các hệ thống dùng chung, hệ thống phục vụ dịch vụ công, hệ thống có dữ liệu lớn, phạm vi sử dụng rộng, tác động trực tiếp đến người dân, doanh nghiệp và hoạt động điều hành của Thành phố. Định kỳ hằng tuần cập nhật kết quả gửi Văn phòng Thành ủy - Cơ quan Thường trực Ban Chỉ đạo 57 Thành ủy để theo dõi, tổng hợp.'),
(129, 19, 'Về an toàn, an ninh mạng và giám sát các hệ thống thông tin: Giao Công an Thành phố khẩn trương thẩm định, phê duyệt hồ sơ xác định cấp độ an ninh, an toàn thông tin của các cơ quan, đơn vị trên địa bàn Thành phố; phấn đấu hoàn thành trước ngày 20/6/2026. Các cơ quan, đơn vị có trách nhiệm hoàn thiện hồ sơ, phối hợp chặt chẽ với Công an Thành phố trong quá trình thẩm định, phê duyệt; trường hợp chậm thực hiện phải báo cáo rõ nguyên nhân, trách nhiệm và thời hạn khắc phục.
Đối với các hệ thống dùng chung, hệ thống triển khai diện rộng, yêu cầu bảo đảm an toàn, an ninh thông tin phải được xác định ngay từ giai đoạn thiết kế, đầu tư, kết nối, vận hành; không để phát sinh tình trạng triển khai hệ thống nhưng chưa bảo đảm đầy đủ điều kiện an toàn thông tin, an ninh mạng.(Đồng chí Bí thư Thành ủy có ý kiến đồng ý đề xuất tại Báo cáo số  715/BC-CAHN-ANM ngày 09/7/2026 kết quả thực hiện công tác đảm bảo an toàn hệ thống thông tin theo cấp độ trên địa bàn thành phố Hà Nội)'),
(130, 9, 'Tham mưu kiến nghị rà soát, điều chỉnh các quy trình nội bộ để đáp ứng các quy định của Luật Giao dịch điện tử; thực hiện các biện pháp, giải pháp linh hoạt sáng tạo, hiệu quả cho phép sử dụng các giấy tờ điện tử tích hợp trên tài khoản định danh điện tử thay thế với giấy tờ giấy khi thực hiện các thủ tục hành chính; sớm có phương án cắt giảm các thành phần hồ sơ khi dữ liệu đã được số hóa'),
(131, 9, 'Tái cấu trúc 50 thủ tục hành chính trọng điểm'),
(132, 10, 'Báo cáo về kết quả việc xây dựng Đề án “Xây dựng cơ sở dữ liệu dùng chung từ số hóa tài liệu của các cơ quan trên địa bàn thành phố Hà Nội” theo Thông báo kết luận số 2120-TB/TU ngày 11/4/2025 của Ban Thường vụ Thành ủy; báo cáo Thường trực Thành ủy, Ban Thường vụ Thành ủy, Ban chỉ đạo 57 Thành ủy'),
(133, 11, 'Cung cấp dịch vụ công trực tuyến toàn trình cho 100% thủ tục thuộc lĩnh vực  doanh nghiệp'),
(134, 11, 'Nghiên cứu, đặt tên rõ ràng cho các nền tảng công nghệ như: sHaNoi (nền tảng thông tin trực tuyến dịch vụ công/Service), và vHaNoi (văn phòng điện tử/điều hành/quản lý văn bản)'),
(135, 11, 'Hoàn thành việc kiện toàn Trung tâm dịch vụ hành chính công 01 cấp đồng bộ, chuyên nghiệp (trụ sở, trang thiết bị, nguồn nhân lực….). Trong đó, lưu ý việc chuyển giao trụ sở làm việc, con người…từ xã, phường về Trung tâm phải được tính toán kỹ lưỡng trong giai đoạn chuyển tiếp tránh ngắt quãng dịch vụ phục vụ người dân và doanh nghiệp'),
(136, 11, 'Xây dựng bàn làm việc số, tương tác trao đổi công việc cho Đảng viên, công chức, viên chức Thành phố'),
(137, 12, 'Về việc kết nối, đồng bộ dữ liệu của 04 thủ tục hành chính của Đảng'),
(138, 25, 'Tiếp tục hoàn thiện tổng đài AI 19001009 theo hướng lấy người dân làm trung tâm, nâng cao hiệu quả hỗ trợ, giải đáp, hướng dẫn thực hiện thủ tục hành chính. Đồng thời từng bước mở rộng phạm vi tương tác, tăng cường kết nối, chia sẻ thông tin với các cơ quan, đơn vị liên quan để kịp thời xử lý các vấn đề dân sinh bức xúc'),
(139, 25, 'Chủ động nghiên cứu, lựa chọn một số xã, phường đủ điều kiện về hạ tầng kỹ thuật, nhân lực và mức độ sẵn sàng chuyển đổi phương thức làm việc để tổ chức triển khai thí điểm mô hình “Không gian làm việc số” (MyHanoi) theo đúng quy định và thẩm quyền'),
(140, 13, 'Giao Trung tâm Phục vụ hành chính công Thành phố chủ trì, phối hợp các sở, ngành liên quan rà soát, chuẩn hóa quy trình thực hiện thủ tục hành chính;           kịp thời khắc phục các lỗi cấu hình ảnh hưởng đến chất lượng giải quyết hồ sơ và kết quả đánh giá Bộ chỉ số về chỉ đạo, điều hành, phục vụ người dân, doanh nghiệp trên môi trường điện tử. Tiếp tục triển khai thường xuyên, liên tục các giải pháp nâng cao chất lượng phục vụ, hướng tới hoàn thiện quy trình, nâng cao hiệu quả quản trị, bảo đảm thực chất, không chạy theo hình thức hoặc chỉ tiêu đánh giá'),
(141, 1, 'Về tái cấu trúc thủ tục hành chính và kết nối cơ sở dữ liệu: Chủ trì, phối hợp các sở, ngành rà soát, lựa chọn 25 thủ tục hành chính có tần suất phát sinh lớn để tập trung tái cấu trúc quy trình theo hướng đơn giản hóa, số hóa và liên thông dữ liệu. Trên cơ sở quy trình tái cấu trúc được thống nhất, giao Sở Khoa học và Công nghệ chủ trì, phối hợp Trung tâm và các đơn vị liên quan thực hiện kết nối API theo từng thủ tục với các cơ sở dữ liệu chuyên ngành, tổ chức triển khai thực hiện, hoàn thành trước ngày 30/6/2026. Bảo đảm tuân thủ đầy đủ quy định về an toàn thông tin, bảo mật dữ liệu và quản lý, khai thác, chia sẻ dữ liệu theo quy định hiện hành'),
(142, 1, 'Về tái cấu trúc thủ tục hành chính và kết nối cơ sở dữ liệu: Chủ trì xây dựng kế hoạch tổng thể và phương án khung triển khai tái cấu trúc tối thiểu 80% thủ tục hành chính thực hiện toàn trình trên môi trường số trước ngày 30/6/2026; gửi các sở, ngành rà soát, thống nhất. Trên cơ sở đó, các sở, ngành ban hành Kế hoạch tái cấu trúc thuộc phạm vi quản lý, hoàn thành trước ngày 19/5/2026.'),
(143, 1, 'Về đầu mối quản trị, vận hành dịch vụ công của bộ, ngành: Thống nhất giao Trung tâm là đầu mối duy nhất của Thành phố thực hiện cài đặt, cấu hình, phân quyền; tiếp nhận đề nghị tạo lập tài khoản; đồng thời hỗ trợ kỹ thuật, hướng dẫn sử dụng đối với các hệ thống dịch vụ công do bộ, ngành Trung ương triển khai, bảo đảm vận hành xuyên suốt, thống nhất, tránh phân tán đầu mối và chồng chéo trong công tác quản trị hệ thống.'),
(144, 1, 'Về tiêu chuẩn, định mức điểm số hóa giải quyết thủ tục hành chính: Chủ trì tham mưu xây dựng tiêu chuẩn, định mức đối với các điểm số hóa giải quyết thủ tục hành chính, bao gồm: định mức máy móc, trang thiết bị của nhân viên bưu chính thực hiện số hóa, cán bộ biệt phái; trang thiết bị phục vụ người dân tra cứu, thực hiện thủ tục hành chính; bảo đảm phù hợp thực tiễn, đồng bộ, tiết kiệm, hiệu quả'),
(145, 1, 'Về hệ thống văn bản điện tử kết nối doanh nghiệp: Chủ trì triển khai hệ thống văn bản điện tử kết nối doanh nghiệp với các sở, ngành, UBND cấp xã; bảo đảm kết nối đến 100% doanh nghiệp, tổ chức trên địa bàn Thành phố, hoàn thành trước ngày 30/4/2026. Các sở, ngành, UBND cấp xã thực hiện gửi, nhận văn bản điện tử toàn trình 100% đối với tổ chức, doanh nghiệp thông qua hệ thống này, chậm nhất trước ngày 30/6/2026.'),
(146, 1, 'Về hệ thống văn bản điện tử kết nối doanh nghiệp: Tiếp tục phát triển, hoàn thiện hệ thống để đáp ứng yêu cầu ký kết hợp đồng kinh tế điện tử giữa cơ quan nhà nước với doanh nghiệp, tổ chức; giữa doanh nghiệp với các đối tác, hoàn thành trước ngày 30/9/2026.'),
(147, 1, 'Về hệ thống văn bản điện tử kết nối doanh nghiệp: Chủ trì phát triển hệ thống kỹ thuật đáp ứng yêu cầu triển khai quy trình thanh tra, kiểm tra điện tử kết nối doanh nghiệp, hoàn thành trước ngày 31/12/2026'),
(148, 14, 'Chủ trì tham mưu UBND Thành phố, phối hợp với các sở, ban, ngành và các cơ quan Trung ương liên quan rà soát, lựa chọn và đánh giá 25 dịch vụ công trực tuyến có lưu lượng hồ sơ phát sinh lớn trên địa bàn Thành phố (tập trung vào các lĩnh vực đất đai, thuế, tư pháp và các lĩnh vực có tần suất sử dụng cao); đề xuất giải pháp tháo gỡ khó khăn, vướng mắc; tái cấu trúc quy trình giải quyết thủ tục hành chính; cắt giảm, đơn giản hóa thành phần hồ sơ trên cơ sở khai thác, tái sử dụng dữ liệu từ các CSDL và hệ thống thông tin của cơ quan nhà nước, nhằm giảm giấy tờ và chi phí tuân thủ cho người dân, doanh nghiệp. Hoàn thành việc rà soát, lựa chọn, tái cấu trúc quy trình và báo cáo kết quả thực hiện về Ban Chỉ đạo 57 Thành ủy trước ngày 30/4/2026.'),
(149, 4, 'Chỉ đạo Trung tâm Phục vụ hành chính công Thành phố chủ trì, phối hợp các cơ quan liên quan rà soát quy trình, thủ tục, điều kiện dữ liệu, pháp lý và liên thông hệ thống để xây dựng, hoàn thiện Đề án “Sổ đỏ trao tay”; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 30/5/2026.'),
(150, 19, 'Về cải cách thủ tục hành chính, dịch vụ công trực tuyến phục vụ người dân, doanh nghiệp: Giao Trung tâm Phục vụ hành chính công Thành phố chủ trì, phối hợp các sở, ngành, đơn vị liên quan tiếp tục hoàn thiện, triển khai thực chất các nhiệm vụ cải cách thủ tục hành chính, dịch vụ công trực tuyến; tập trung các thủ tục có lưu lượng hồ sơ lớn, các thủ tục đã phân cấp, ủy quyền về cấp xã và các nội dung có tác động trực tiếp đến người dân, doanh nghiệp.'),
(151, 19, 'Về cải cách thủ tục hành chính, dịch vụ công trực tuyến phục vụ người dân, doanh nghiệp: Hoàn thiện, triển khai Đề án “Sổ đỏ trao tay” và các quy trình liên thông trong lĩnh vực đất đai, giao dịch bảo đảm; làm rõ quy trình thực hiện, điều kiện triển khai, sản phẩm đầu ra, khó khăn, vướng mắc và kiến nghị xử lý. Tổng hợp đầy đủ khó khăn, vướng mắc trong quá trình vận hành cổng dịch vụ công trực tuyến; báo cáo Ban Chỉ đạo 57 Thành ủy để tổng hợp, kiến nghị Ban Chỉ đạo Trung ương xem xét, giải quyết theo thẩm quyền.'),
(152, 5, 'Đối với mô hình tổ chức, hoạt động của Trung tâm Phục vụ hành chính công Thành phố, tiếp tục thực hiện nghiêm kết luận của Bộ Chính trị và Ban Thường vụ Thành ủy; trước mắt giữ nguyên mô hình tổ chức, hoạt động hiện nay cho đến khi hoàn thành số hóa toàn trình, bảo đảm cán bộ, người lao động yên tâm công tác.'),
(153, 5, 'Giao Ban Tổ chức Thành ủy, Sở Nội vụ, Trung tâm Phục vụ hành chính công Thành phố và Sở Tư pháp phối hợp rà soát, xác định phương án đối với lao động hợp đồng theo Nghị quyết số 26/2024/NQ-HĐND đang thực hiện nhiệm vụ tiếp nhận, giải quyết hồ sơ tại các Điểm Hỗ trợ dịch vụ công số trên địa bàn xã, phường; hoàn thành trước ngày 30/12/2026, bảo đảm ổn định đội ngũ và hoạt động của các Điểm Hỗ trợ dịch vụ công số.'),
(154, 9, 'Giải quyết kiến nghị, đề xuất của các xã, phường và báo cáo Ban Chỉ đạo 57 Thành ủy'),
(155, 9, 'Chủ trì xây dựng lộ trình đổi mới công nghệ đến năm 2035 đối với các ngành kinh tế mũi nhọn, xác định công nghệ cốt lõi có thể tạo đột phá, nhu cầu thị trường trong và ngoài nước, khả năng tiếp cận công nghệ. Báo cáo Thường trực Ban Chỉ đạo kết quả thực hiện trước ngày 01/10/2025'),
(156, 9, 'Yêu cầu các đơn vị mở và kết nối dữ liệu'),
(157, 9, 'Thành lập Sàn Giao dịch công nghệ'),
(158, 9, 'Hoàn thành định mức KT-KT và đơn giá sản phẩm'),
(159, 9, 'Thành lập Tổ công tác đặc biệt về giải ngân và hạ tầng số'),
(160, 9, 'Ban hành Kế hoạch hành động thực hiện kết luận tại Hội nghị ngày 14/11/2025 của Ban Chỉ đạo'),
(161, 9, 'Nghiên cứu Kế hoạch hành động chiến lược và văn bản hướng dẫn của Cơ quan Thường trực Ban Chỉ đạo để cụ thể hoá vào kế hoạch hành động, chương trình, dự án của cơ quan, địa phương mình, phù hợp với các Hệ thống chiến lược và Sáng kiến đột phá'),
(162, 9, 'Hoàn thành Quy chế phối hợp liên ngành & triển khai 06 Nghị quyết HĐND TP về KHCN, ĐMST'),
(163, 9, 'Căn cứ quy định tại Nghị định số 180/2025/NĐ-CP ngày 01/7/2025, hướng dẫn của Bộ Tài chính tại Công văn số 11725/BTC-QLĐT ngày 31/7/2025, các bộ, ngành, địa phương khẩn trương xác định dự án/hoạt động xây dựng, phát triển cơ sở dữ liệu áp dụng cơ chế hợp tác công tư, gửi Bộ Tài chính, Bộ Khoa học và công nghệ để phối hợp thực hiện.'),
(164, 9, 'Lãnh đạo, chỉ đạo tổ chức triển khai thực hiện 06 Nghị quyết của HĐND Thành phố về KHCN, ĐMST'),
(165, 9, 'Công bố Danh mục dữ liệu dùng chung của Thành phố'),
(166, 11, 'Chỉ đạo cụ thể hóa và tổ chức triển khai thực hiện Nghị định số 271/2025/NĐ-CP về thành lập doanh nghiệp, góp vốn để thương mại hóa kết quả nghiên cứu khoa học, áp dụng đối với các đơn vị thuộc Thành phố, trong đó có Trường Đại học Thủ đô Hà Nội.'),
(167, 11, 'Giao Sở Khoa học và Công nghệ đôn đốc các sở, ngành Thành phố tiếp tục thực hiện các nhiệm vụ được giao tại các Thông báo kết luận của Ban Chỉ đạo 57 Thành ủy và Tổ Thường trực; tổng hợp, báo cáo kết quả gửi Văn phòng Thành ủy trước 12h00 thứ 5 hàng tuần.'),
(168, 11, 'Rà soát, hệ thống hóa danh mục các nhiệm vụ do Trung ương và Thành phố giao, bảo đảm thống nhất, không trùng lặp trong quá trình kiểm đếm và báo cáo tiến độ;'),
(169, 11, 'Từng bước số hóa danh mục nhiệm vụ, xây dựng dữ liệu dùng chung để xác định mục tiêu, kết quả then chốt và các chỉ số đánh giá hiệu quả thực hiện từng nhiệm vụ.'),
(170, 11, 'Giao Sở Khoa học và công nghệ chủ trì phối hợp với các Sở, ngành liên quan xây dựng hướng dẫn đánh giá kết quả thực hiện nhiệm chuyển đổi số của các cơ quan, đơn vị trên địa bàn Thành phố, trong đó lưu ý thời gian đánh giá của các xã, phường từ ngày 01/7/2025 đến ngày 15/12/2025;'),
(171, 11, 'Đối với đề xuất nghiên cứu, triển khai Trung tâm tính toán thông minh (AIDC) của Thành phố: UBND Thành phố sớm báo cáo, xin ý kiến Ban Chỉ đạo 57 Thành ủy để hoàn thiện phương án tổ chức thực hiện'),
(172, 12, 'Đánh giá hệ thống thông tin phục vụ chỉ đạo, điều hành, tác nghiệp của khối Đảng, khối Hội đồng nhân dân, khối Ủy ban nhân dân và khối Mặt trận Tổ quốc, các tổ chức chính trị – xã hội; làm rõ mức độ đáp ứng yêu cầu quản lý, phối hợp và chia sẻ dữ liệu giữa các khối; chỉ ra những hạn chế, bất cập và đề xuất giải pháp hoàn thiện trong thời gian tới, gửi Ban Chỉ đạo 57 Thành ủy.'),
(173, 12, 'Rà soát 20 ứng dụng của Trung ương và Thành phố đang vận hành tại cấp xã, phường theo Báo cáo của Ủy ban Kiểm tra Thành ủy; đề xuất phương án theo hướng một đầu mối truy cập, đăng nhập một lần, thuận tiện cho người dùng'),
(174, 12, 'Rà soát, cập nhật và công bố công khai danh mục các cơ quan, đơn vị có trách nhiệm thực hiện việc mở dữ liệu theo quy định của Luật dữ liệu và các văn bản hướng dẫn.'),
(175, 12, 'Về việc hoàn thiện cơ chế, chính sách về lĩnh vực khoa học và công nghệ'),
(176, 12, 'Xây dựng tiêu chí và tổ chức đánh giá năng lực số của Bí thư, Chủ tịch xã/phường trên địa bàn Thành phố.'),
(177, 12, 'Nghiên cứu và ban hành hướng dẫn triển khai các mô hình kinh tế số, xã hội số trên địa bàn Thành phố.'),
(178, 25, 'Tổ chức triển khai thí điểm mô hình “Bản sao số” tại một số xã, phường theo lộ trình, phạm vi phù hợp; triển khai thí điểm tại xã Minh Châu trên cơ sở đánh giá điều kiện thực tiễn, bảo đảm tính khả thi và hiệu quả định kỳ trước ngày 22 hằng tháng báo cáo UBND Thành phố kết quả triển khai thực hiện theo quy định'),
(179, 25, 'Chủ động tham mưu, xây dựng và tổ chức triển khai các giải pháp ứng dụng khoa học và công nghệ, đổi mới sáng tạo và chuyển đổi số nhằm tháo gỡ “05 điểm nghẽn” của Thành phố; xác định rõ mục tiêu, sản phẩm, tiến độ và trách nhiệm của các cơ quan liên quan'),
(180, 7, 'Chủ trì, phối hợp với Tổ thường trực Ban Chỉ đạo tiếp thu tối đa ý kiến góp ý tại cuộc họp, hoàn thiện dự thảo, trình Ban Chỉ đạo 57 Thành ủy'),
(181, 7, 'Khẩn trương xây dựng, chuẩn hóa và quản lý thống nhất Cơ sở dữ liệu chuyên gia, nhà khoa học và hệ thống dữ liệu sở hữu trí tuệ của Thành phố; hình thành ‘kho tài sản trí tuệ’ được đăng ký, định giá và quản lý tập trung, làm nền tảng cho việc huy động nguồn lực tài chính mới từ tài sản trí tuệ.'),
(182, 13, 'Sở Khoa học và Công nghệ nghiên cứu kỹ phương án thực hiện, đưa ra lộ trình, giải pháp triển khai Đề án “Xây dựng cơ sở dữ liệu dùng chung từ số hóa tài liệu tập trung của các cơ quan trên địa bàn Thành phố Hà Nội” (được duyệt chủ trương theo Quyết định 2112/QĐ-UBND ngày 19/4/2025 của Ủy ban nhân dân Thành phố) bảo đảm phát huy giá trị lịch sử, chính trị, xã hội, thực tiễn của hồ sơ, tài liệu. Đồng thời, chỉ đạo các Sở, ngành và các cơ quan, tổ chức có tài liệu thống kê, bảo quản an toàn hồ sơ, tài liệu được lưu giữ tại các điểm kho; tránh thất lạc, ẩm mốc, rách, hỏng hồ sơ, tài liệu; báo cáo Thường trực Thành ủy, Ban Thường vụ Thành ủy trước ngày 01/3/2026 (đã được thay đổi thời hạn thành 15/3/2026 theo TBKL 289) (đã được nhắc lại tại TBKL 452-TB/TU)'),
(183, 1, 'Thống nhất đưa vào nội dung báo cáo Ban Chỉ đạo tại cuộc họp tháng 3 các phương án triển khai: Trung tâm dữ liệu (DC), Trung tâm dữ liệu và trí tuệ nhân tạo (AIDC), Kho dữ liệu tập trung, nền tảng trí tuệ nhân tạo dùng chung, Bản sao số liên hợp; đồng thời hoàn thiện Phụ lục điều chỉnh, bổ sung nhiệm vụ về chuyển đổi số trong hệ thống chính trị thuộc Kế hoạch hành động số 20-KH/BCĐ57 ngày 19/01/2026 của Ban Chỉ đạo 57 Thành ủy.'),
(184, 1, 'Rà soát toàn bộ các chỉ tiêu chiến lược lớn; báo cáo với lãnh đạo UBND Thành phố để thống nhất căn cứ mô hình phát triển mới đạt 40% kinh tế số vào năm 2030, bảo đảm định hướng mục tiêu đến năm 2030 không thay đổi. Các chỉ tiêu đề xuất phải có giải trình rõ cơ sở lựa chọn, phương pháp tính và đánh giá tác động cụ thể đối với mục tiêu chung'),
(185, 1, 'Khẩn trương rà soát, tham mưu UBND Thành phố phương án phân cấp, ủy quyền trong chuyển đổi số, làm rõ nội dung, phạm vi trách nhiệm của từng cấp, bảo đảm thống nhất, tránh chồng chéo'),
(186, 1, 'Ban hành văn bản đề nghị các sở, ngành tiếp tục đề xuất các “bài toán lớn”, vấn đề cốt lõi của ngành, lĩnh vực; tổng hợp, báo cáo Thành phố để hình thành danh mục nhiệm vụ trọng tâm, giao Sở Khoa học và Công nghệ chủ trì tham mưu'),
(187, 1, 'Tập trung triển khai ngay nhiệm vụ xây dựng Bản sao số, bảo đảm cách tiếp cận tổng thể, đồng bộ, không đầu tư manh mún, phân tán đồng thời tận dụng những kết quả đã có, tránh lãng phí. Có đến đâu đưa vào khai thác, sử dụng ngay không chờ hoàn thành. Trình Ban Chỉ đạo phương án kiến trúc tổng thể và lộ trình triển khai theo giai đoạn, bảo đảm tính khả thi về nguồn lực và tiến độ thực hiện'),
(188, 14, 'Khẩn trương triển khai các nhiệm vụ trọng tâm, cốt lõi theo Kế hoạch số 20-KH/BCĐ57 của Ban Chỉ đạo 57 Thành ủy, gồm: Kho cơ sở dữ liệu dùng chung Thành phố, Trung tâm dữ liệu (DC), Trung tâm tính toán thông minh (AIDC), nền tảng trí tuệ nhân tạo tập trung của Thành phố, Bản sao số, số hóa hồ sơ, tài liệu tập trung của Thành phố. Trong thời gian từ nay đến khi hoàn thành đầu tư hạ tầng, rà soát, nghiên cứu, đề xuất phương án phù hợp nhằm bảo đảm kịp thời hạ tầng phục vụ vận hành, khai thác dữ liệu và các hệ thống số của Thành phố theo quy định. Định kỳ, hàng tuần báo cáo kết quả Ban Chỉ đạo 57 Thành ủy (qua Văn phòng Thành ủy).'),
(189, 14, 'Chủ trì xây dựng cơ sở dữ liệu dùng chung của Thành phố; đồng thời rà soát hiện trạng các cơ sở dữ liệu của các sở, ban, ngành và địa phương, xây dựng lộ trình kết nối, chia sẻ và khai thác dữ liệu giữa các hệ thống thông tin, bảo đảm dữ liệu được chuẩn hóa, thực hiện nguyên tắc “dữ liệu nhập một lần, sử dụng nhiều lần”, tăng cường tái sử dụng dữ liệu; hoàn thành trong tháng 3/2026.'),
(190, 14, 'Chủ trì xây dựng Đề án thu hút doanh nghiệp trong lĩnh vực khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số trong nước và quốc tế đầu tư, hoạt động tại Thủ đô Hà Nội, góp phần hình thành hệ sinh thái đổi mới sáng tạo và thúc đẩy phát triển kinh tế số của Thành phố; hoàn thành trước ngày 31/3/2026.'),
(191, 14, 'Chủ trì, phối hợp với các cơ quan liên quan xây dựng phương án cung cấp thiết bị công nghệ thông tin cho các cơ quan trong hệ thống chính trị Thành phố (Thành ủy, HĐND, UBND Thành phố, Ủy ban MTTQ Việt Nam Thành phố và các sở, ban, ngành), bảo đảm đồng bộ, hiệu quả, tránh chồng chéo, dàn trải, lãng phí; hoàn thành trước ngày 20/3/2026.'),
(192, 17, 'Về mô hình Không gian làm việc số (Hanoiwork) Giao Sở Khoa học và Công nghệ chủ trì, phối hợp với các cơ quan, đơn vị liên quan tiếp tục rà soát, hoàn thiện các tính năng của mô hình Không gian làm việc số (Hanoiwork); đẩy mạnh đào tạo, bồi dưỡng, tập huấn; tăng cường theo dõi, kiểm đếm mức độ sử dụng thực chất tại từng cơ quan, đơn vị.'),
(193, 17, 'Về dữ liệu dùng chung của Thành phố. Sở Khoa học và Công nghệ tiếp tục nghiên cứu, đề xuất phương án hình thành, quản lý, xác thực và khai thác kho dữ liệu dung chung Thành phố theo hướng phục vụ quản lý nhà nước phát triển kinh tế số, xã hội số và phục vụ người dân và doanh nghiệp.'),
(194, 18, 'Sở Khoa học và Công nghệ chủ trì, phối hợp với Văn phòng Thành ủy và các cơ quan, đơn vị liên quan rà soát tổng thể các phần mềm, nền tảng, cơ sở dữ liệu đang triển khai trong toàn hệ thống chính trị Thành phố. Việc rà soát phải làm rõ hiện trạng sử dụng, mức độ trùng lặp, khả năng kết nối, chia sẻ dữ liệu, hiệu quả vận hành, các hệ thống gây phát sinh thêm thao tác, tài khoản, báo cáo cho cơ sở. Trên cơ sở đó, đề xuất phương án giảm tài khoản, giảm nhập liệu lặp lại, giảm báo cáo thủ công, tăng dùng chung dữ liệu và từng bước hình thành báo cáo tự động trên nền dữ liệu; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 25/5/2026.'),
(195, 18, 'Sở Khoa học và Công nghệ chủ trì, phối hợp với các sở, ngành, đơn vị liên quan phân loại, thẩm định, lựa chọn các đề xuất thuộc 30 bài toán lớn của Thành phố có sản phẩm đầu ra rõ, có khả năng thử nghiệm, ứng dụng và nhân rộng. Việc triển khai 30 bài toán lớn phải chuyển từ tiếp nhận đề xuất sang cơ chế đặt hàng, sàng lọc, thử nghiệm, đánh giá, mua sắm, thuê dịch vụ hoặc nhân rộng đối với sản phẩm có hiệu quả; phát huy vai trò của Sàn Giao dịch công nghệ, Chợ chuyển đổi số và Trung tâm Đổi mới sáng tạo Hà Nội trong kết nối, thử nghiệm, thương mại hóa các giải pháp công nghệ phục vụ nhiệm vụ của Thành phố.'),
(196, 18, 'UBND Thành phố chỉ đạo Sở Khoa học và Công nghệ, các sở, ngành liên quan phối hợp với Văn phòng Thành ủy rà soát các nhiệm vụ nền tảng về dữ liệu, hạ tầng số, nền tảng dùng chung và an toàn thông tin. Đối với từng nhiệm vụ, phải xác định rõ sản phẩm cụ thể trong tháng 5, tháng 6/2026; sản phẩm đến hết quý III/2026 và cuối năm 2026; cơ quan chịu trách nhiệm chính; nguồn lực thực hiện; tiêu chí đánh giá sau khi hoàn thành. Báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 15/5/2026.'),
(197, 18, 'UBND Thành phố chỉ đạo Sở Khoa học và Công nghệ chủ trì, phối hợp với Văn phòng Thành ủy, Sở Nội vụ, Trung tâm Phục vụ hành chính công Thành phố và các cơ quan liên quan khẩn trương rà soát, hoàn thiện phương án triển khai Đề án xây dựng cơ sở dữ liệu dùng chung từ số hóa tài liệu của các cơ quan trên địa bàn Thành phố. Phương án phải làm rõ phạm vi dữ liệu, nhóm tài liệu ưu tiên, tiêu chí lựa chọn, mô hình số hóa, yêu cầu bảo quản an toàn tài liệu, chuẩn dữ liệu, phân quyền khai thác, sản phẩm đầu ra, lộ trình thực hiện, cơ quan chủ trì, cơ quan phối hợp và mốc hoàn thành; báo cáo Thường trực Thành ủy, Ban Thường vụ Thành ủy trước ngày 17/5/2026.'),
(198, 4, 'Chỉ đạo Sở Khoa học và Công nghệ chủ trì, phối hợp Sở Tài chính nghiên cứu, đề xuất phương án sử dụng phần mềm văn phòng có bản quyền cho đội ngũ cán bộ, công chức, viên chức, người lao động trong hệ thống chính trị Thành phố, bảo đảm đồng bộ, an toàn, bảo mật thông tin và nâng cao hiệu quả xử lý công việc trên môi trường số; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 31/7/2026.'),
(199, 4, 'Chỉ đạo Sở Khoa học và Công nghệ, Công ty Cổ phần Trung tâm Đổi mới sáng tạo Hà Nội và các cơ quan liên quan rà soát 30 bài toán lớn của Thành phố; sắp xếp thứ tự ưu tiên, lựa chọn các bài toán cấp bách, có tác động lớn, có khả năng tạo sản phẩm, giải pháp, mô hình ứng dụng trong năm 2026; báo cáo danh mục bài toán ưu tiên trước ngày 15/6/2026. Trong đó, nghiên cứu bổ sung lĩnh vực văn hóa, công nghiệp văn hóa và các sản phẩm sáng tạo gắn với lịch sử, văn hóa, di sản Hà Nội.'),
(200, 4, 'Chỉ đạo Sở Khoa học và Công nghệ chủ trì, phối hợp Sở Tài chính, Sở Nội vụ, Sở Tư pháp, Công ty Cổ phần Trung tâm Đổi mới sáng tạo Hà Nội và các cơ quan liên quan khẩn trương hoàn thiện điều kiện hoạt động; đồng thời xác lập rõ chức năng, nhiệm vụ của Công ty Cổ phần Trung tâm Đổi mới sáng tạo Hà Nội là đầu mối điều phối, kết nối, vận hành hệ sinh thái đổi mới sáng tạo của Thành phố; phân định rõ chức năng quản lý nhà nước của Sở Khoa học và Công nghệ với chức năng vận hành, kết nối, hỗ trợ đổi mới sáng tạo của Công ty; hoàn thiện phương án vốn điều lệ, cơ chế tài chính, quy chế hoạt động, cơ chế giao nhiệm vụ, cơ chế phối hợp, cơ chế sử dụng chuyên gia và cơ chế đánh giá kết quả theo sản phẩm đầu ra.'),
(201, 4, 'Đối với Nghị quyết hỗ trợ đào tạo 1.000 nghiên cứu sinh: rà soát, hoàn thiện chính sách theo hướng hỗ trợ trong quá trình đào tạo; bảo đảm có điều kiện, tiêu chí, thời hạn rõ ràng, gắn với kết quả nghiên cứu, sản phẩm đầu ra và yêu cầu phục vụ phát triển khoa học, công nghệ, đổi mới sáng tạo của Thành phố; trình cấp có thẩm quyền ban hành trước ngày 15/6/2026. (UBND giao lại cho Sở KHCN)'),
(202, 19, 'Về cơ sở dữ liệu, kho dữ liệu dùng chung và số hóa hồ sơ, tài liệu: Đối với số hóa hồ sơ, tài liệu, yêu cầu Sở Khoa học và Công nghệ thực hiện nghiêm các kết luận, chỉ đạo của Ban Chỉ đạo 57 Thành ủy, Tổ Thường trực; rà soát, lựa chọn tài liệu số hóa theo nhu cầu quản lý, khai thác, tái sử dụng, bảo đảm không số hóa dàn trải, hình thức.'),
(203, 19, 'Về quản lý, khai thác, sử dụng trang thiết bị công nghệ thông tin đã đầu tư cho 126 xã, phường: Giao UBND Thành phố chỉ đạo Sở Khoa học và Công nghệ chủ trì phối hợp Sở Tài chính và các cơ quan liên quan khẩn trương kiểm tra, đánh giá việc quản lý, khai thác, sử dụng trang thiết bị công nghệ thông tin đã đầu tư cho 126 xã, phường, báo cáo gửi Ban Chỉ đạo 57 Thành ủy trước ngày 30/6/2026'),
(204, 19, 'Về Không gian làm việc số HanoiWork và hệ thống báo cáo số: Giao Sở Khoa học và Công nghệ rà soát, hoàn thiện cơ sở pháp lý đối với Không gian làm việc số HanoiWork; xác định rõ hình thức văn bản cần ban hành, quy chế quản lý, vận hành, khai thác, tiêu chuẩn an toàn thông tin, an ninh mạng và điều kiện triển khai thống nhất tại các cơ quan, đơn vị trên địa bàn Thành phố.'),
(205, 20, 'Giao Sở Khoa học và Công nghệ tiếp tục thẩm định dự án Hệ thống hỗ trợ kiểm soát úng ngập; phối hợp với Sở Xây dựng và các cơ quan liên quan làm rõ bài toán, phạm vi, dữ liệu, chủ thể quản lý, phương án vận hành, khả năng kết nối và hiệu quả đầu tư, bảo đảm không chồng chéo, lãng phí; báo cáo UBND Thành phố xem xét, quyết định theo thẩm quyền.'),
(206, 20, 'Rà soát, phân loại 30 bài toán lớn của Thành phố theo từng ngành, lĩnh vực; giao các sở, ngành rà soát, cụ thể hóa yêu cầu, dữ liệu đầu vào, sản phẩm đầu ra và tiêu chí đánh giá. Lấy kết quả xây dựng và tổ chức thực hiện các bài toán lớn làm căn cứ đánh giá trách nhiệm, năng lực tổ chức thực hiện của người đứng đầu. Giao Sở Khoa học và Công nghệ tổng hợp, rà soát tham mưu UBND Thành phố báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 05/8/2026.'),
(207, 20, 'Đồng chí Nguyễn Xuân Lưu, Ủy viên Ban Thường vụ Thành ủy, Phó Chủ tịch UBND Thành phố, Tổ phó Tổ công tác của Ban Thường vụ Thành ủy về sắp xếp các đơn vị sự nghiệp công lập, doanh nghiệp nhà nước trên địa bàn Thành phố trực tiếp chỉ đạo Công ty Cổ phần Hanel, Công ty TNHH một thành viên Chiếu sáng và Thiết bị đô thị, Công ty TNHH một thành viên Thoát nước Hà Nội và Công ty Cổ phần Giống gia súc Hà Nội hoàn thiện đề án phát triển doanh nghiệp trên cơ sở Nghị quyết số 57-NQ/TW của Bộ Chính trị. Các đề án phải đánh giá đúng thực chất năng lực hiện có; xác định rõ định hướng phát triển, lộ trình thực hiện, tổ chức bộ máy, nhân lực và các kiến nghị, đề xuất với Thành phố; hoàn thành trước ngày 15/8/2026. Giao Sở Khoa học và Công nghệ chủ trì, phối hợp với các sở, ngành liên quan thẩm định, tham mưu UBND Thành phố báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 30/8/2026.'),
(208, 20, 'Các sở, ngành rà soát, bóc tách, đánh giá các chỉ số về khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số thuộc lĩnh vực quản lý; xác định hiện trạng, mức độ hoàn thành, nội dung cần tập trung chỉ đạo và nguồn lực ưu tiên; gửi Sở Khoa học và Công nghệ trước ngày 25/7/2026.Giao Sở Khoa học và Công nghệ tổng hợp, xác định các chỉ tiêu còn thấp, các lĩnh vực cần tập trung lãnh đạo, chỉ đạo; tham mưu UBND Thành phố nhiệm vụ, giải pháp và nguồn lực ưu tiên, báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 30/7/2026.'),
(209, 21, '(1) Tiếp tục duy trì thí điểm đánh giá cán bộ trên HanoiWork; xác định chức năng cốt lõi của HanoiWork là không gian làm việc số. Căn cứ đầu bài và kiến nghị của Ban Tổ chức Thành ủy, rà soát, điều chỉnh công cụ, quy trình, giao diện và phương thức cập nhật theo hướng thuận lợi, dễ sử dụng, giảm thao tác thủ công.'),
(210, 21, '(2) Phối hợp với Văn phòng Thành ủy, Văn phòng UBND Thành phố và các cơ quan liên quan xử lý các khó khăn, vướng mắc về kỹ thuật, dữ liệu, kết nối và phân quyền thuộc phạm vi quản lý; không để phát sinh chức năng, dữ liệu chồng chéo, trùng lặp.'),
(211, 22, 'Chủ trì hướng dẫn các sở, ngành cập nhật, tích hợp và khai thác dữ liệu chuyên ngành thống nhất trên nền tảng dùng chung của Thành phố. Các Sở, ngành khẩn trương cập nhật dữ liệu hiện có thuộc phạm vi quản lý lên nền tảng bản sao số Thành phố và kho dữ liệu dùng chung Thành phố.'),
(212, 5, 'Sở Khoa học và Công nghệ rà soát, đánh giá thực chất 93 danh mục dữ liệu mở của Thành phố; người đứng đầu các sở, ngành trực tiếp rà soát dữ liệu mở thuộc ngành, lĩnh vực quản lý. Dữ liệu chưa sẵn sàng, không được cập nhật hoặc chưa bảo đảm chất lượng, khả năng khai thác thì tạm dừng công khai; chỉ công bố lại khi bảo đảm điều kiện khai thác, sử dụng thực tế.'),
(213, 5, 'Sở Khoa học và Công nghệ hướng dẫn các sở, ngành vận dụng các cơ chế, chính sách đặc thù theo Luật Thủ đô để thu hút, ký hợp đồng với chuyên gia, nhà khoa học, nhất là trong những lĩnh vực Thành phố còn thiếu và yếu; xây dựng mạng lưới chuyên gia, huy động sự tham gia của các viện nghiên cứu, trường đại học, cơ sở đào tạo và tổ chức khoa học, công nghệ.'),
(214, 26, 'Hoàn thành triển khai xây dựng, đưa vào khai thác, sử dụng 114 cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành, trong đó tập trung ưu tiên hoàn thiện cơ sở dữ liệu: đất đai, xây dựng, bảo hiểm, tài chính, doanh nghiệp, lao động việc làm, y tế, giáo dục và kết nối, xác thực với Cơ sở dữ liệu quốc gia về dân cư trong tháng 8/2025, đồng bộ dữ liệu về Trung tâm dữ liệu quốc gia'),
(215, 27, 'Đề xuất lộ trình và phương án tăng cường kiểm soát, giảm thiểu ô nhiễm không khí phát sinh từ hoạt động xây dựng (quan trắc, áp dụng camera, cảm biến).'),
(216, 1, 'Yêu cầu các Sở Xây dựng, Sở Nông nghiệp và Môi trường, Sở Y tế, Sở Giáo dục và Đào tạo khẩn trương chuẩn hóa, hoàn thiện dữ liệu nền địa lý chuyên ngành thuộc phạm vi quản lý; bảo đảm đầy đủ, chính xác, đồng bộ, sẵn sàng tích hợp và ưu tiên áp dụng ngay vào hệ thống Bản sao số, phục vụ hiệu quả công tác quản lý, điều hành của Thành phố'),
(217, 12, 'Tham mưu, xây dựng, triển khai Đề án số hóa di sản văn hóa Thủ đô, ưu tiên số hóa các di sản văn hóa phi vật thể, di tích có nguy cơ mai một; xây dựng cơ sở dữ liệu về di sản, bảo đảm khả năng kết nối, chia sẻ dữ liệu với các hệ thống thông tin của Thành phố và Trung ương phục vụ bảo tồn và quảng bá rộng rãi giá trị di sản.'),
(218, 12, 'Hoàn thành việc triển khai các nhiệm vụ phục vụ chuyển đổi số, bảo đảm kết nối với Đề án 06, gồm: (Nhánh 8) Phát triển kinh tế đêm'),
(219, 1, 'Xác định 03 ngành Giáo dục, Y tế, Văn hóa là các lĩnh vực có lợi thế thị trường lớn, cơ sở dữ liệu tương đối ổn định, được lựa chọn làm lĩnh vực đột phá, tiên phong trong chuyển đổi số của Thành phố; tập trung chỉ đạo quyết liệt, triển khai bài bản, tạo hiệu ứng lan tỏa sang các ngành, lĩnh vực khác. Yêu cầu mỗi đơn vị phân công rõ 01 đồng chí trong Ban Giám đốc trực tiếp phụ trách, chỉ đạo xuyên suốt và chịu trách nhiệm toàn diện về tiến độ, chất lượng, hiệu quả thực hiện'),
(220, 1, 'Sở Văn hóa và Thể thao nghiêm túc rút kinh nghiệm tình trạng số hóa di tích còn phân tán, thiếu quy chuẩn trong thời gian qua; khẩn trương hoàn thiện và trình báo cáo Đề án kinh tế đêm chậm nhất ngày 15/3/2026. Không thành lập Quỹ đầu tư mạo hiểm lĩnh vực văn hóa từ ngân sách, sử dụng Quỹ đầu tư mạo hiểm chung của Thành phố; nghiên cứu phương án lồng ghép vào hệ sinh thái chợ chuyển đổi số để huy động nguồn lực xã hội hóa'),
(221, 17, 'Về các nội dung trong lĩnh vực văn hóa Khẩn trương xây dựng Đề án chuyển đổi số trong lĩnh vực văn hóa của Thành phố; trước hết tập trung rà soát, kiểm đếm, xác định hiện trạng, phân loại, xác định trọng tâm ưu tiên và lộ trình triển khai; báo cáo cấp có thẩm quyền xem xét trong quý II/2026.'),
(222, 17, 'Về các nội dung trong lĩnh vực văn hóa Tập trung số hóa, lưu giữ, bảo tồn và khai thác có hiệu quả các giá trị văn hóa, di sản của Thành phố; bảo đảm giữ gìn bản sắc, giá trị gốc, tính xác thực của di sản và phù hợp yêu cầu quản lý nhà nước.'),
(223, 17, 'Về các nội dung trong lĩnh vực văn hóa Nghiên cứu, đề xuất triển khai một số nội dung gắn với phát triển công nghiệp văn hóa, du lịch và kinh tế đêm, nhất là các nội dung liên quan đến Làng Văn hóa - Du lịch các dân tộc Việt Nam, chợ Đồng Xuân, không gian làng nghề, tuyến du lịch - văn hóa đặc trưng và các mô hình phù hợp khác; báo cáo cấp có thẩm quyền xem xét, chỉ đạo.'),
(224, 22, 'Phối hợp Sở Khoa học và Công nghệ hoàn thành cập nhật các lớp dữ liệu hiện có của ngành phục vụ việc rà soát, cụ thể hóa Quy hoạch tổng thể Thủ đô Hà Nội tầm nhìn 100 năm, hoàn thành trước ngày 25/8/2026. (Văn hóa, Thể thao và Du lịch)'),
(225, 22, 'Chủ trì, phối hợp các cơ quan, đơn vị liên quan hướng dẫn cấp xã, phường rà soát, chuẩn hóa và kế thừa tối đa các cơ sở dữ liệu, sản phẩm số hóa hiện có; tuyệt đối không làm lại từ đầu nhằm hạn chế tối đa tình trạng chồng chéo, lãng phí nguồn lực và ngân sách nhà nước'),
(226, 22, 'Đăng ký các sản phẩm dự kiến hình thành từ kết quả số hóa trong năm 2026, ưu tiên sản phẩm có khả năng khai thác, sử dụng và tạo giá trị ngay; báo cáo Ban Chỉ đạo 57 Thành ủy, UBND Thành phố trước ngày 30/8/2026'),
(227, 22, 'Nghiên cứu, xây dựng bản đồ khảo cổ Hà Nội, phối hợp với Sở Xây dựng đưa dữ liệu khảo cổ vào phục vụ quy hoạch, quản lý di sản và cấp phép xây dựng theo quy định.'),
(228, 5, 'Sở Văn hóa, Thể thao và Du lịch tập trung: (1) ứng dụng công nghệ kết nối các điểm di tích, văn hóa, điểm đến với hệ thống lưu trú, lữ hành, từng bước hình thành hệ sinh thái du lịch dùng chung; (2) kết nối các điểm di tích có thu phí, triển khai bán vé điện tử, quản lý, thống kê chính xác lượng khách; (3) cụ thể hóa định hướng phát triển công nghiệp văn hóa thành sản phẩm, dịch vụ có khả năng tạo doanh thu, đóng góp cho kinh tế số; (4) rà soát, chuẩn hóa, tích hợp, kế thừa tối đa và tiếp tục khai thác các kết quả số hóa di tích đã được triển khai, tránh trùng lặp, lãng phí.'),
(229, 7, 'Rà soát toàn diện hệ thống văn bản quy phạm pháp luật của Thành phố, đối chiếu với quy định của Trung ương để phát hiện, khắc phục các khoảng trống, bất cập, nội dung chưa thống nhất; kiến nghị ban hành cơ chế, chính sách đặc thù hoặc đề xuất cấp có thẩm quyền tháo gỡ các vấn đề vượt thẩm quyền'),
(230, 17, 'Về rà soát, chuẩn bị các điều kiện triển khai Luật Thủ đô (sửa đổi) và ứng dụng AI hỗ trợ tư vấn pháp luật Rà soát, tổng hợp các nội dung liên quan đến khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số trong Luật Thủ đô (sửa đổi) và các văn bản liên quan; báo cáo đồng chí Trương Việt Dũng, Phó Chủ tịch UBND Thành phố để chỉ đạo tổ chức lấy ý kiến các trường đại học, viện nghiên cứu, doanh nghiệp, đối tác có liên quan tham gia góp ý đối với các văn bản dưới luật, đồng thời chuẩn bị các điều kiện cần thiết, bảo đảm tính khả thi và sẵn sàng triển khai sau khi ban hành.'),
(231, 17, 'Về rà soát, chuẩn bị các điều kiện triển khai Luật Thủ đô (sửa đổi) và ứng dụng AI hỗ trợ tư vấn pháp luật Nghiên cứu, xây dựng mô hình, giải pháp trợ lý AI hỗ trợ tư vấn pháp luật miễn phí cho người dân, doanh nghiệp và chính quyền cơ sở trên nền tảng số của Thành phố (iHanoi) theo hướng thiết thực, dễ tiếp cận, hỗ trợ tra cứu, giải thích và vận dụng pháp luật trong thực tiễn.'),
(232, 9, 'Xây dựng kế hoạch hỗ trợ doanh nghiệp tham gia phát triển các ứng dụng, dịch vụ số mới theo hình thức hợp tác công tư (PPP)'),
(233, 9, 'Ưu tiên nguồn lực cho các lĩnh vực công nghệ chiến lược'),
(234, 9, 'Bố trí 4% chi ngân sách cho lĩnh vực KH&CN, ĐMST&CĐS: Tổng hợp, tham mưu UBND Thành phố giao dự toán thực hiện các nhiệm vụ KHCN, ĐMST & CĐS'),
(235, 9, 'Hoàn thành triển khai xây dựng, đưa vào khai thác, sử dụng 114 cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành, trong đó tập trung ưu tiên hoàn thiện cơ sở dữ liệu: đất đai, xây dựng, bảo hiểm, tài chính, doanh nghiệp, lao động việc làm, y tế, giáo dục và kết nối, xác thực với Cơ sở dữ liệu quốc gia về dân cư trong tháng 8/2025, đồng bộ dữ liệu về Trung tâm dữ liệu quốc gia'),
(236, 9, 'Đưa Trung tâm Đổi mới sáng tạo vào hoạt động'),
(237, 10, 'Giải quyết triệt để các khó khăn, vướng mắc trong việc giải ngân vốn đầu tư công và chi thường xuyên trong năm 2025 đối với lĩnh vực khoa học, công nghệ và chuyển đổi số; (ii) Sở Tài chính, Sở Khoa học và Công nghệ xây dựng phương án đầu tư đồng bộ hạ tầng công nghệ thông tin cho 126 xã, phường; (iii) Xây dựng các danh mục cụ thể các dự án, nhiệm vụ dự kiến triển khai trong năm 2026 cho lĩnh vực khoa học, công nghệ và chuyển đổi số; báo cáo Ban chỉ đạo 57 Thành ủy, Tổ thường trực'),
(238, 10, 'Báo cáo UBND Thành phố phương án đầu tư hạ tầng CNTT cho 126 xã, phường.'),
(239, 12, 'Chuẩn bị báo cáo về chuỗi hoạt động kỷ niệm 01 năm ngày ban hành Nghị quyết số 57-NQ/TW của Bộ Chính trị (công bố Mạng lưới Đổi mới sáng tạo Thành phố, …) gửi Thường trực Thành ủy, Ban Chỉ đạo 57 Thành ủy phục vụ Hội nghị tổng kết năm 2025 của Ban Chỉ đạo 57 Thành ủy'),
(240, 23, 'Khẩn trương đưa Quỹ đầu tư mạo hiểm Thành phố vào hoạt động'),
(241, 7, 'Nghiên cứu, xây dựng giải pháp tăng trưởng kinh tế hai con số gắn với xác lập mô hình tăng trưởng mới lấy khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số làm động lực chính; xác định rõ lộ trình, hệ thống chỉ tiêu và các công cụ chính sách cụ thể để hiện thực hóa mục tiêu này'),
(242, 7, 'Tổng hợp tình hình bố trí, phân bổ ngân sách, mức độ tiếp thu, chuyển hóa thành giải pháp và sản phẩm cụ thể trên 03 trục khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số; gửi Văn phòng Thành ủy trước ngày 25/01/2026 để tổng hợp, báo cáo giao ban cuối tháng 01/2026'),
(243, 1, 'Khẩn trương phối hợp với các cơ quan, đơn vị có liên quan hoàn thành cơ bản việc phân bổ nguồn vốn năm 2026 trước ngày 15/3/2026; đồng thời đẩy nhanh tiến độ phân bổ chi đầu tư và chi thường xuyên, bảo đảm kịp thời, hiệu quả, đáp ứng yêu cầu triển khai nhiệm vụ đã được giao'),
(244, 1, 'Chủ trì, phối hợp Sở Khoa học và Công nghệ tham mưu UBND Thành phố báo cáo HĐND Thành phố xem xét, cân đối lại tỷ lệ giữa chi đầu tư và chi thường xuyên cho lĩnh vực khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số; bảo đảm phân bổ kinh phí thuận lợi, đúng quy định và phù hợp tiến độ thực hiện nhiệm vụ, dự án.'),
(245, 17, 'Về bổ sung đối tượng thụ hưởng đối với hệ thống phòng họp trực tuyến Giao Sở Tài chính chủ trì, phối hợp với các cơ quan, đơn vị liên quan tổ chức triển khai theo quy định; trường hợp có khó khăn, vướng mắc, kịp thời báo cáo cấp có thẩm quyền xem xét, xử lý.'),
(246, 19, 'Về phân bổ, giải ngân kinh phí khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số: Giao UBND Thành phố chỉ đạo Sở Tài chính chủ trì, phối hợp Sở Khoa học và Công nghệ và các cơ quan, đơn vị liên quan rà soát tình hình phân bổ, sử dụng, giải ngân kinh phí đối với các nhiệm vụ khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số. Thủ trưởng cơ quan, đơn vị được giao nhiệm vụ chịu trách nhiệm về tiến độ hoàn thiện hồ sơ, khả năng giải ngân và hiệu quả sử dụng kinh phí; kịp thời báo cáo UBND Thành phố đối với khó khăn, vướng mắc vượt thẩm quyền'),
(247, 19, 'Về phân bổ, giải ngân kinh phí khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số: Sở Tài chính định kỳ hằng tuần tổng hợp tiến độ phân bổ, giải ngân kinh phí của các cơ quan, đơn vị; trong đó làm rõ tỷ lệ phân bổ, tỷ lệ giải ngân, nhiệm vụ chưa đủ điều kiện phân bổ, nhiệm vụ chậm giải ngân, khó khăn, vướng mắc và kiến nghị xử lý; gửi Văn phòng Thành ủy - Cơ quan Thường trực Ban Chỉ đạo 57 Thành ủy trước 17 giờ 00 thứ Sáu hằng tuần.'),
(248, 19, 'Về cơ sở dữ liệu đất đai, dữ liệu đầu tư công: Đối với dữ liệu đầu tư công, giao Sở Tài chính chủ trì, phối hợp các chủ đầu tư và cơ quan liên quan duy trì, cập nhật thường xuyên dữ liệu quản lý dự án đầu tư công trên hệ thống. Việc cập nhật dữ liệu phải được xác định là yêu cầu bắt buộc đối với chủ đầu tư, từng bước thay thế báo cáo giấy định kỳ; bảo đảm dữ liệu được cập nhật thường xuyên, phục vụ trực tiếp công tác lãnh đạo, chỉ đạo, điều hành.'),
(249, 9, 'Bộ Tư pháp, Bộ Nông nghiệp và Môi trường, Ủy ban nhân dân các địa phương khẩn trương phối hợp hoàn thành số hóa dữ liệu hộ tịch, đất đai, tái sử dụng dữ liệu đã số hóa để thực hiện cắt giảm thành phần hồ sơ theo thẩm quyền'),
(250, 9, 'Hoàn thành triển khai xây dựng, đưa vào khai thác, sử dụng 114 cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành, trong đó tập trung ưu tiên hoàn thiện cơ sở dữ liệu: đất đai, xây dựng, bảo hiểm, tài chính, doanh nghiệp, lao động việc làm, y tế, giáo dục và kết nối, xác thực với Cơ sở dữ liệu quốc gia về dân cư trong tháng 8/2025, đồng bộ dữ liệu về Trung tâm dữ liệu quốc gia'),
(251, 12, 'Tiếp tục nghiên cứu, ứng dụng công nghệ số, đặc biệt gắn với mô hình Bản sao số nhằm nâng cao hiệu quả quản lý chuyên ngành trên địa bàn Thành phố.'),
(252, 23, '"(1) Khẩn trương hoàn thiện, tổ chức khai thác hiệu quả cơ sở dữ liệu đất đai của Thành phố; 
(2) Phối hợp các đơn vị liên quan tích hợp, đồng bộ dữ liệu phục vụ xây dựng và vận hành Bản sao số của Thành phố."'),
(253, 13, 'Sở Nông nghiệp và Môi trường khẩn trương hoàn thiện và tổ chức khai thác hiệu quả cơ sở dữ liệu đất đai của Thành phố; phối hợp các đơn vị liên quan tích hợp, đồng bộ dữ liệu phục vụ xây dựng, vận hành Bản sao số. Rà soát lại tiến độ, xác định rõ khối lượng và tỷ lệ dữ liệu bảo đảm “đúng - đủ - sạch - sống”; xây dựng kế hoạch đưa ngay phần dữ liệu đã đạt chuẩn vào khai thác sử dụng, không chờ hoàn thiện 100%. Đăng ký lại tiến độ cụ thể và gửi Sở Khoa học và Công nghệ tổng hợp, đưa vào theo dõi trong kết luận'),
(254, 1, 'Tập trung hoàn thành dứt điểm bản đồ giải thửa, bao gồm cả 20% diện tích đất nông nghiệp còn lại, chậm nhất trong tháng 6/2026. Đến ngày 30/6/2026 phải hoàn thành cơ sở dữ liệu đất đai bảo đảm tiêu chí “đúng, đủ, sạch, sống”; tổ chức cập nhật định kỳ hằng tháng và thực hiện chia sẻ đầy đủ vào kho dữ liệu dùng chung của Thành phố theo quy định'),
(255, 1, 'Khẩn trương xây dựng, hoàn thiện các bộ dữ liệu lõi: Bản đồ địa chất, ưu tiên triển khai trước tại các khu vực quy hoạch phát triển đô thị để đánh giá điều kiện nền móng phục vụ xây dựng công trình ngầm; đặc biệt lưu ý khu vực phía Nam, cần tính toán kỹ phương án xử lý nền bùn'),
(256, 1, 'Khẩn trương xây dựng, hoàn thiện các bộ dữ liệu lõi: Bản đồ thủy văn, bảo đảm tính toán chi tiết độ dốc địa hình, lưu vực sông, đặc điểm mùa khô, mùa mưa lớn và hệ thống hồ chứa, phục vụ hiệu quả công tác dự báo, điều tiết và phân lũ;'),
(257, 1, 'Khẩn trương xây dựng, hoàn thiện các bộ dữ liệu lõi: Bản đồ thổ nhưỡng nông nghiệp, xác định rõ đặc tính đất đai, làm cơ sở định vị vùng trồng phù hợp, gắn với định hướng quy hoạch dài hạn 100 năm của Thành phố.'),
(258, 1, 'Yêu cầu các Sở Xây dựng, Sở Nông nghiệp và Môi trường, Sở Y tế, Sở Giáo dục và Đào tạo khẩn trương chuẩn hóa, hoàn thiện dữ liệu nền địa lý chuyên ngành thuộc phạm vi quản lý; bảo đảm đầy đủ, chính xác, đồng bộ, sẵn sàng tích hợp và ưu tiên áp dụng ngay vào hệ thống Bản sao số, phục vụ hiệu quả công tác quản lý, điều hành của Thành phố'),
(259, 16, 'Đẩy nhanh xây dựng, hoàn thiện, khai thác cơ sở dữ liệu chuyên ngành; gắn khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số với phát triển kinh tế nông nghiệp, quản lý tài nguyên, bảo vệ môi trường; lượng hóa, hạch toán rõ hiệu quả đóng góp trong lĩnh vực phụ trách.'),
(260, 18, 'UBND Thành phố chỉ đạo ban hành trước ngày 15/5/2026 Kế hoạch cao điểm hoàn thiện dữ liệu đất đai của Thành phố; phân công rõ trách nhiệm từng cơ quan, đơn vị; phân rã tiến độ theo tuần, theo địa bàn, theo nhóm dữ liệu'),
(261, 4, 'Chỉ đạo Sở Nông nghiệp và Môi trường chủ trì, phối hợp Công an Thành phố và các cơ quan liên quan triển khai Kế hoạch cao điểm hoàn thiện dữ liệu đất đai; phân rã tiến độ theo tuần, theo địa bàn, theo nhóm dữ liệu; hoàn thành trước ngày 30/6/2026.'),
(262, 19, 'Về cơ sở dữ liệu đất đai, dữ liệu đầu tư công: Đối với cơ sở dữ liệu đất đai, giao UBND Thành phố chỉ đạo Sở Nông nghiệp và Môi trường rà soát, báo cáo tiến độ, khối lượng còn lại, khó khăn, vướng mắc, nguyên nhân và khả năng hoàn thành trước ngày 30/6/2026; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 10/6/2026.'),
(263, 22, 'Khẩn trương rà soát khối lượng, hiện trạng, chỉ tiêu đã giao và tiến độ thực hiện của 126 xã, phường; đề xuất KPI phải hoàn thành đến ngày 30/8/2026 đối với từng đơn vị; lập bảng tổng hợp, nêu rõ tỷ lệ hoàn thành, KPI đề xuất và các đơn vị chưa quan tâm, thiếu quyết liệt hoặc có kết quả thấp, gửi Văn phòng Thành ủy trước ngày 21/8/2026'),
(264, 22, 'Phối hợp với Sở Khoa học và Công nghệ, Công an Thành phố và các cơ quan liên quan rà soát phương án bảo đảm an toàn, an ninh thông tin, định danh người sử dụng; kết nối cơ sở dữ liệu đất đai với nền tảng iHanoi để người dân kiểm tra, xác nhận và tham gia làm sạch dữ liệu, hoàn thành trước ngày 15/9/2026.'),
(265, 9, 'Dự thảo Nghị quyết ban hành Quy định thu hút, trọng dụng người có tài năng thành phố Hà Nội'),
(266, 9, 'Triển khai chương trình đào tạo “Công chức số Thủ đô”'),
(267, 9, 'Hoàn thành triển khai xây dựng, đưa vào khai thác, sử dụng 114 cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành, trong đó tập trung ưu tiên hoàn thiện cơ sở dữ liệu: đất đai, xây dựng, bảo hiểm, tài chính, doanh nghiệp, lao động việc làm, y tế, giáo dục và kết nối, xác thực với Cơ sở dữ liệu quốc gia về dân cư trong tháng 8/2025, đồng bộ dữ liệu về Trung tâm dữ liệu quốc gia'),
(268, 11, 'Hướng dẫn khung năng lực đối với cán bộ làm công tác chuyển đổi số cho các sở, ngành, các xã, phường để tìm kiếm được cán bộ có năng lực, trước mắt cần bổ sung cho các đơn vị thiếu hụt cán bộ bằng nhiều giải pháp như thuê chuyên gia, ký hợp đồng chuyên môn, điều động, tiếp nhận, thi tuyển.... để ưu tiên cho lĩnh vực khoa học công nghệ, chuyển đổi số và đổi mới sáng tạo'),
(269, 7, 'Nghiên cứu, đề xuất các cơ chế, chính sách đặc thù để thu hút, sử dụng và phát triển nguồn nhân lực chất lượng cao; tham khảo, vận dụng sáng tạo các mô hình thành công của một số nước tiên tiến trong khu vực'),
(270, 1, 'Tăng cường phối hợp chặt chẽ với Sở Tài chính rà soát tổng thể việc bàn giao trang thiết bị, máy tính cho các xã, phường; đôn đốc, tháo gỡ khó khăn phát sinh, bảo đảm hoàn thành đúng tiến độ, kịp thời phục vụ công tác chuyên môn tại cơ sở'),
(271, 1, 'Khẩn trương đôn đốc các cơ quan, đơn vị bố trí cán bộ, công chức tham gia thực hiện nhiệm vụ chuyển đổi số; bảo đảm đủ số lượng, phù hợp năng lực; khắc phục tình trạng chỉ tập trung vào chế độ, chính sách mà chưa chú trọng yếu tố nhân sự, tổ chức thực hiện'),
(272, 1, 'Chủ trì, phối hợp với Sở Khoa học và Công nghệ thí điểm thực hiện chấm điểm công tác đánh giá cán bộ, công chức theo hướng đổi mới; trên cơ sở ban hành quy định đánh giá hằng tháng, cụ thể hóa theo 4 trục nhiệm vụ, áp dụng phương pháp quản trị theo mục tiêu (OKR/KPI), bảo đảm đo lường được kết quả, gắn trách nhiệm cá nhân với sản phẩm đầu ra'),
(273, 1, 'Thống nhất bổ sung Sở Nội vụ và phường Từ Liêm là đơn vị thí điểm triển khai đổi mới công tác đánh giá cán bộ, công chức theo phương pháp quản trị theo mục tiêu (KPI/OKR). Giao các đơn vị xây dựng Kế hoạch triển khai cụ thể, trong đó xác định rõ mục tiêu, phạm vi áp dụng, bộ chỉ số đánh giá và lộ trình thực hiện; bảo đảm đồng bộ giữa hệ thống quản trị công việc với cơ chế đo lường, đánh giá hiệu quả thực thi nhiệm vụ. Báo cáo Tổ Thường trực kết quả thực hiện trước ngày 31/3/2026 để đánh giá, rút kinh nghiệm và làm cơ sở xem xét nhân rộng'),
(274, 4, 'Riêng đối với hồ sơ người có công, chỉ đạo Sở Nội vụ chủ trì, phối hợp Sở Khoa học và Công nghệ và các đơn vị liên quan rà soát hiện trạng hồ sơ, xác định phạm vi, lộ trình, phương án bảo quản hồ sơ gốc và số hóa dữ liệu; trình phương án thực hiện trước ngày 15/6/2026, phấn đấu hoàn thành số hóa trước ngày 30/10/2026.'),
(275, 4, 'Chỉ đạo Sở Nội vụ chủ trì, phối hợp Sở Khoa học và Công nghệ và các cơ quan liên quan nghiên cứu, đề xuất phương án triển khai thị trường lao động số của Thành phố; trong đó tập trung hình thành nền tảng tích hợp dữ liệu cung - cầu lao động, kỹ năng nghề nghiệp, nhu cầu tuyển dụng, đào tạo, chuyển đổi việc làm và dự báo xu hướng thị trường lao động; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 30/6/2026.'),
(276, 22, 'Triển khai ngay việc số hóa hồ sơ và xây dựng cơ sở dữ liệu người có công, hoàn thành trước ngày 31/12/2026'),
(277, 22, 'Tổ chức thực hiện xây dựng, phát triển thị trường lao động số thành phố Hà Nội; trọng tâm hoàn thiện Cổng thông tin việc làm Thành phố, kết nối cung - cầu lao động và phát huy hiệu quả các trung tâm dịch vụ việc làm trên môi trường số.'),
(278, 5, 'Giao Ban Tổ chức Thành ủy, Sở Nội vụ, Trung tâm Phục vụ hành chính công Thành phố và Sở Tư pháp phối hợp rà soát, xác định phương án đối với lao động hợp đồng theo Nghị quyết số 26/2024/NQ-HĐND đang thực hiện nhiệm vụ tiếp nhận, giải quyết hồ sơ tại các Điểm Hỗ trợ dịch vụ công số trên địa bàn xã, phường; hoàn thành trước ngày 30/12/2026, bảo đảm ổn định đội ngũ và hoạt động của các Điểm Hỗ trợ dịch vụ công số.'),
(279, 5, 'Ban Tổ chức Thành ủy, Sở Nội vụ phối hợp với Sở Khoa học và Công nghệ rà soát, dự báo nhu cầu nguồn nhân lực công nghệ đến năm 2030; trên cơ sở đó tham mưu xây dựng Đề án đào tạo và thu hút nguồn nhân lực chất lượng cao phục vụ thực hiện Nghị quyết số 57-NQ/TW, gắn với đặt hàng đào tạo, tuyển dụng và chính sách thu hút nhân lực chất lượng cao.'),
(280, 12, 'Xây dựng cơ chế phát hiện, ươm tạo, bảo hộ và thương mại hóa các ý tưởng, sản phẩm sáng tạo số của học sinh, sinh viên; định kỳ tổ chức các cuộc thi, sân chơi về dữ liệu, trí tuệ nhân tạo, sản phẩm số, gắn với nhu cầu thực tiễn của Thành phố.'),
(281, 9, 'Hoàn thành triển khai xây dựng, đưa vào khai thác, sử dụng 114 cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành, trong đó tập trung ưu tiên hoàn thiện cơ sở dữ liệu: đất đai, xây dựng, bảo hiểm, tài chính, doanh nghiệp, lao động việc làm, y tế, giáo dục và kết nối, xác thực với Cơ sở dữ liệu quốc gia về dân cư trong tháng 8/2025, đồng bộ dữ liệu về Trung tâm dữ liệu quốc gia'),
(282, 13, 'Sở Giáo dục và Đào tạo chủ trì, phối hợp Sở Khoa học và Công nghệ và các đơn vị liên quan xây dựng phương án đầu tư, triển khai phòng học STEM tại các trường học trên địa bàn Thành phố. Trong quá trình xây dựng phương án, bảo đảm định hướng tăng cường nội địa hóa thiết bị, giải pháp công nghệ đáp ứng yêu cầu kỹ thuật, an toàn, khả năng vận hành, khai thác lâu dài; tính toán hiệu quả đầu tư gắn với quy mô hệ thống trường học của Thành phố và mời chuyên gia phù hợp tham gia tư vấn hoàn thiện phương án'),
(283, 1, 'Xác định 03 ngành Giáo dục, Y tế, Văn hóa là các lĩnh vực có lợi thế thị trường lớn, cơ sở dữ liệu tương đối ổn định, được lựa chọn làm lĩnh vực đột phá, tiên phong trong chuyển đổi số của Thành phố; tập trung chỉ đạo quyết liệt, triển khai bài bản, tạo hiệu ứng lan tỏa sang các ngành, lĩnh vực khác. Yêu cầu mỗi đơn vị phân công rõ 01 đồng chí trong Ban Giám đốc trực tiếp phụ trách, chỉ đạo xuyên suốt và chịu trách nhiệm toàn diện về tiến độ, chất lượng, hiệu quả thực hiện'),
(284, 1, 'Sở Giáo dục và Đào tạo khẩn trương ban hành bộ tiêu chí, quy chuẩn trường học mới làm cơ sở phê duyệt đầu tư; đồng thời xây dựng bài toán tuyển sinh tổng thể trên nền tảng số, quản lý chặt chẽ biến động dân cư, chủ động điều tiết, tránh tình trạng quá tải, bị động trong tổ chức thực hiện'),
(285, 1, 'Yêu cầu các Sở Xây dựng, Sở Nông nghiệp và Môi trường, Sở Y tế, Sở Giáo dục và Đào tạo khẩn trương chuẩn hóa, hoàn thiện dữ liệu nền địa lý chuyên ngành thuộc phạm vi quản lý; bảo đảm đầy đủ, chính xác, đồng bộ, sẵn sàng tích hợp và ưu tiên áp dụng ngay vào hệ thống Bản sao số, phục vụ hiệu quả công tác quản lý, điều hành của Thành phố'),
(286, 16, 'Rà soát, hoàn thiện, khai thác hiệu quả cơ sở dữ liệu ngành; nghiên cứu, thí điểm ứng dụng trí tuệ nhân tạo hỗ trợ dạy, học, quản lý và đánh giá; rà soát việc đầu tư, sử dụng trang thiết bị phục vụ giáo dục STEAM, chuyển đổi số trong nhà trường; chủ động chuẩn bị nguồn nhân lực cho các lĩnh vực công nghệ chiến lược, công nghệ lõi.'),
(287, 17, 'Về các nội dung trong lĩnh vực giáo dục Rà soát, đánh giá các mô hình ứng dụng công nghệ số, trí tuệ nhân tạo trong giáo dục đã triển khai; đề xuất phương án hoàn thiện, chuẩn hóa, nhân rộng theo lộ trình phù hợp.'),
(288, 17, 'Về các nội dung trong lĩnh vực giáo dục Trên cơ sở kết quả thí điểm, nghiên cứu, đề xuất mở rộng ứng dụng trí tuệ nhân tạo trong giáo dục với quy mô khoảng 500 trường; bảo đảm chặt chẽ về cơ sở pháp lý, chất lượng chuyên môn, khả năng nhân rộng và yêu cầu dữ liệu phải thuộc quản lý thống nhất của Thành phố.'),
(289, 17, 'Về các nội dung trong lĩnh vực giáo dục Khẩn trương hoàn thiện Khung năng lực số đối với giáo viên, cán bộ quản lý cơ sở giáo dục mầm non, phổ thông và giáo dục thường xuyên; xây dựng kế hoạch đào tạo, bồi dưỡng, tập huấn đối với các đối tượng có liên quan.'),
(290, 17, 'Về các nội dung trong lĩnh vực giáo dục Đối chương trình STEAM, thư viện điện tử, bản đồ số trường học và các nội dung liên quan, tiếp tục rà soát, hoàn thiện, báo cáo cấp có thẩm quyền xem xét, quyết định trước khi triển khai diện rộng.'),
(291, 4, 'Chỉ đạo Sở Giáo dục và Đào tạo chủ trì, phối hợp Sở Khoa học và Công nghệ và các cơ quan liên quan xây dựng phương án nền tảng số dùng chung cho trường học, gắn với học bạ điện tử, sổ liên lạc điện tử, quản trị nhà trường, học liệu số, dịch vụ giáo dục số và khảo thí trên môi trường số; đề xuất phương án triển khai trước ngày 30/6/2026.'),
(292, 19, 'Về phát triển nền tảng giáo dục số, tổ chức thi trên máy tính và trang thiết bị giáo dục số: Giao Sở Giáo dục và Đào tạo chủ trì, phối hợp các cơ quan, đơn vị liên quan tập trung triển khai các nhiệm vụ như sau: (i) Hoàn thiện cơ sở dữ liệu ngành giáo dục; bảo đảm đồng bộ, liên thông, an toàn thông tin; (ii) Nghiên cứu, xây dựng phương án tổ chức thi trên máy tính, tập trung thí điểm trước đối với kỳ thi tuyển sinh vào lớp 10; (iii) Nghiên cứu, xây dựng ngân hàng đề thi dùng chung và lộ trình thực hiện kiểm tra, đánh giá đồng bộ trên môi trường số; (iv) Rà soát, đề xuất phương án triển khai mô hình phòng học STEM/STEAM và trang bị thiết bị giáo dục số. Thực hiện chế độ báo cáo gửi đồng chí Phó Chủ tịch UBND Thành phố phụ trách, đồng thời gửi Tổ Thường trực Ban Chỉ đạo 57 Thành ủy (qua Văn phòng Thành ủy) trước ngày 24 hằng tháng.'),
(293, 22, 'Phối hợp Sở Khoa học và Công nghệ hoàn thành cập nhật các lớp dữ liệu hiện có của ngành phục vụ việc rà soát, cụ thể hóa Quy hoạch tổng thể Thủ đô Hà Nội tầm nhìn 100 năm, hoàn thành trước ngày 25/8/2026. (Giáo dục)'),
(294, 22, 'Khẩn trương rà soát, bổ sung, cấu trúc lại cơ sở dữ liệu ngành giáo dục phù hợp với mô hình tổ chức mới; hoàn thiện dữ liệu về đội ngũ giáo viên, cán bộ quản lý và các trường thông tin phục vụ phân tích, đánh giá, bảo đảm kịp thời phục vụ năm học 2026-2027, hoàn thành trước ngày 01/9/2026.'),
(295, 22, 'Ngay từ đầu năm học 2026-2027, tổ chức áp dụng KPI trong đánh giá cán bộ quản lý, giáo viên và cơ sở giáo dục, gắn với mục tiêu, chỉ tiêu cụ thể; xây dựng kế hoạch năm học đến từng tuần để theo dõi, kiểm đếm tiến độ và kết quả thực hiện. Khẩn trương tổ chức kiểm tra chất lượng đầu năm học, sử dụng kết quả làm dữ liệu đầu vào cho việc đánh giá, xếp loại; từng bước xếp hạng các trường theo khối và khu vực, bảo đảm thực chất, khách quan. Kết quả thực hiện nhiệm vụ của các cơ sở giáo dục là một trong những căn cứ đánh giá trách nhiệm của Chủ tịch UBND xã, phường trên địa bàn.'),
(296, 19, 'Về kinh tế số, đổi mới sáng tạo và doanh nghiệp khoa học công nghệ: Giao Sở Công Thương chủ trì, phối hợp Sở Khoa học và Công nghệ và các cơ quan liên quan rà soát, hoàn thiện kế hoạch hỗ trợ doanh nghiệp nhỏ và vừa, hộ kinh doanh, làng nghề chuyển đổi số, phát triển thương mại điện tử, mô hình chợ 4.0, gian hàng số; bảo đảm rõ đối tượng, phương thức hỗ trợ, sản phẩm đầu ra và tiêu chí đánh giá hiệu quả.'),
(297, 22, 'Chủ động phối hợp Sở Khoa học và Công nghệ triển khai bản đồ số kinh tế của ngành Công Thương Hà Nội, bảo đảm bám sát, thống nhất với Quy hoạch tổng thể Thủ đô Hà Nội tầm nhìn 100 năm.'),
(298, 5, 'Sở Công Thương phối hợp với Sở Khoa học và Công nghệ rà soát, hỗ trợ phát triển doanh nghiệp khoa học và công nghệ; trước mắt tập trung hỗ trợ Công ty Cổ phần Giống gia súc Hà Nội phát triển, ứng dụng khoa học, công nghệ, đổi mới sáng tạo vào sản xuất, kinh doanh.'),
(299, 5, 'Sở Công Thương chủ động xác định, đăng ký chỉ tiêu cụ thể về phát triển thương mại điện tử; tăng cường kết nối, khai thác dữ liệu với cơ quan thuế để thúc đẩy thương mại điện tử; khẩn trương hoàn thiện “Gian hàng OCOP Hà Nội” trên các sàn thương mại điện tử lớn, phấn đấu đưa vào hoạt động dịp 10/10/2026, là sản phẩm tiêu biểu của Thành phố gắn với thực hiện Nghị quyết số 57-NQ/TW và phát triển kinh tế số.'),
(300, 12, 'Tiếp tục thí điểm mô hình Trạm y tế thông minh tại một số xã, phường trên địa bàn Thành phố, trong đó nghiên cứu thí điểm tại phường Cầu Giấy; tổng kết, đánh giá kết quả thực hiện, báo cáo Ban Chỉ đạo 57 Thành ủy.'),
(301, 12, 'Thiết lập cơ chế kết nối, chia sẻ dữ liệu y tế, thống nhất danh mục trường thông tin cần thu thập, bảo đảm phù hợp quy định về bảo vệ dữ liệu cá nhân, an toàn, an ninh thông tin; từng bước triển khai các tiện ích y tế trên nền tảng số của Thành phố.'),
(302, 23, 'Khẩn trương rà soát tổng thể năng lực cấp cứu ngoại viện trên địa bàn.Thành phố, xác định rõ các điểm nghẽn theo từng khu vực; xây dựng và triển khai cơ chế điều phối cấp cứu theo nguyên tắc “gần nhất - phù hợp nhất - nhanh nhất”, kết nối và khai thác hiệu quả toàn bộ nguồn lực cấp cứu (công lập, ngoài công lập, Trung ương), bảo đảm phục vụ kịp thời người dân; đồng thời xây dựng phương án đầu tư, nâng cấp Trung tâm Cấp cứu 115 theo hướng đáp ứng yêu cầu, khắc phục tình trạng phương tiện, trang thiết bị lạc hậu, thiếu đồng bộ'),
(303, 28, 'Xây dựng và vận hành hệ thống y tế chăm sóc sức khỏe toàn dân dựa trên nền tảng dữ liệu lớn, bảo đảm tuyệt đối an toàn, bảo mật thông tin. Nghiên cứu, đề xuất hình thành các trung tâm nghiên cứu, ứng dụng, đào tạo y tế chuyên sâu, chất lượng cao phục vụ nhu cầu của Thủ đô và cả nước'),
(304, 26, 'Hoàn thành triển khai xây dựng, đưa vào khai thác, sử dụng 114 cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành, trong đó tập trung ưu tiên hoàn thiện cơ sở dữ liệu: đất đai, xây dựng, bảo hiểm, tài chính, doanh nghiệp, lao động việc làm, y tế, giáo dục và kết nối, xác thực với Cơ sở dữ liệu quốc gia về dân cư trong tháng 8/2025, đồng bộ dữ liệu về Trung tâm dữ liệu quốc gia'),
(305, 13, 'Sở Y tế khẩn trương rà soát tổng thể năng lực cấp cứu ngoại viện trên địa bàn Thành phố, xác định rõ các điểm nghẽn theo từng khu vực; xây dựng, triển khai cơ chế điều phối theo nguyên tắc “gần nhất - phù hợp nhất - nhanh nhất”, kết nối, khai thác hiệu quả toàn bộ nguồn lực cấp cứu (công lập, ngoài công lập, Trung ương), bảo đảm phục vụ kịp thời người dân; đồng thời xây dựng phương án đầu tư, nâng cấp Trung tâm Cấp cứu 115, khắc phục tình trạng phương tiện, trang thiết bị lạc hậu, thiếu đồng bộ; báo cáo Tổ Thường trực trước ngày 01/3/2026'),
(306, 1, 'Xác định 03 ngành Giáo dục, Y tế, Văn hóa là các lĩnh vực có lợi thế thị trường lớn, cơ sở dữ liệu tương đối ổn định, được lựa chọn làm lĩnh vực đột phá, tiên phong trong chuyển đổi số của Thành phố; tập trung chỉ đạo quyết liệt, triển khai bài bản, tạo hiệu ứng lan tỏa sang các ngành, lĩnh vực khác. Yêu cầu mỗi đơn vị phân công rõ 01 đồng chí trong Ban Giám đốc trực tiếp phụ trách, chỉ đạo xuyên suốt và chịu trách nhiệm toàn diện về tiến độ, chất lượng, hiệu quả thực hiện'),
(307, 1, 'Sở Y tế chủ trì, phối hợp Sở Tài chính khẩn trương triển khai đầu tư, mua sắm hệ thống máy xạ trị Proton tiên tiến, bảo đảm người dân được tiếp cận công nghệ điều trị hiện đại, chất lượng cao; xác định đây là khoản đầu tư có ý nghĩa xã hội lớn, cần triển khai đồng bộ, không chia giai đoạn, tổ chức thực hiện trong thời gian sớm nhất theo đúng quy định.'),
(308, 1, 'Yêu cầu các Sở Xây dựng, Sở Nông nghiệp và Môi trường, Sở Y tế, Sở Giáo dục và Đào tạo khẩn trương chuẩn hóa, hoàn thiện dữ liệu nền địa lý chuyên ngành thuộc phạm vi quản lý; bảo đảm đầy đủ, chính xác, đồng bộ, sẵn sàng tích hợp và ưu tiên áp dụng ngay vào hệ thống Bản sao số, phục vụ hiệu quả công tác quản lý, điều hành của Thành phố'),
(309, 17, 'Về một số nội dung trọng tâm trong lĩnh vực y tế Khẩn trương rà soát, làm sạch, chuẩn hóa, đối soát và liên thông dữ liệu hồ sơ sức khỏe điện tử với cơ sở dữ liệu dân cư; nâng cao hiệu quả khai thác, sử dụng sổ sức khỏe điện tử, bảo đảm dữ liệu đồng bộ, chính xác, phục vụ thực chất công tác quản lý, khám bệnh, chữa bệnh và chăm sóc sức khỏe Nhân dân; phấn đấu hoàn thành các nội dung trọng tâm trước ngày 15/4/2026.'),
(310, 17, 'Về một số nội dung trọng tâm trong lĩnh vực y tế Rà soát, đánh giá tổng thể mô hình cấp cứu ngoại viện trên địa bàn Thành phố; làm rõ yêu cầu tổ chức, vận hành, khả năng đáp ứng theo địa bàn, mạng lưới cơ sở y tế và hiệu quả đầu tư; đề xuất phương án triển khai phù hợp, báo cáo UBND Thành phố trong tháng 4/2026, đồng gửi Cơ quan Thường trực Ban Chỉ đạo 57 Thành ủy để theo dõi, đôn đốc.'),
(311, 17, 'Về một số nội dung trọng tâm trong lĩnh vực y tế Tiếp tục nghiên cứu, đánh giá và đề xuất triển khai ứng dụng thiết bị bay không người lái (drone/UAV) trong lĩnh vực y tế theo cơ chế sandbox; bảo đảm phù hợp, hiệu quả, đúng quy định; làm rõ phạm vi, điều kiện triển khai, cơ chế phối hợp, tiêu chí đánh giá và trách nhiệm quản lý trong quá trình thực hiện; báo cáo UBND Thành phố trong tháng 4/2026, đồng gửi Cơ quan Thường trực Ban Chỉ đạo 57 Thành ủy để theo dõi, đôn đốc.'),
(312, 19, 'Về hồ sơ sức khỏe điện tử và kết nối VNeID: Giao UBND Thành phố chỉ đạo Sở Y tế chủ trì, phối hợp Công an Thành phố, Sở Khoa học và Công nghệ và các cơ quan liên quan rà soát việc kết nối hồ sơ sức khỏe điện tử với iHanoi, VNeID và các hệ thống liên quan; làm việc với Cục C06 - Bộ Công an để thống nhất giải pháp kỹ thuật, điều kiện kết nối, xác thực dữ liệu và lộ trình thực hiện.'),
(313, 19, 'Về hồ sơ sức khỏe điện tử và kết nối VNeID: Sở Y tế báo cáo kết quả trước ngày 15/6/2026; trong đó làm rõ hiện trạng kết nối, phương án kỹ thuật, lộ trình hoàn thành, khó khăn, vướng mắc và kiến nghị xử lý; bảo đảm kết nối, xác thực, tái sử dụng dữ liệu theo quy định.'),
(314, 22, 'Phối hợp Sở Khoa học và Công nghệ hoàn thành cập nhật các lớp dữ liệu hiện có của ngành phục vụ việc rà soát, cụ thể hóa Quy hoạch tổng thể Thủ đô Hà Nội tầm nhìn 100 năm, hoàn thành trước ngày 25/8/2026. (Y tế)'),
(315, 22, 'Khẩn trương rà soát, xây dựng cơ sở dữ liệu cho các đối tượng bảo trợ xã hội; bảo đảm quản lý đầy đủ, chính xác đối tượng, chế độ, chính sách và kết nối với các cơ sở dữ liệu có liên quan, hoàn thành trước ngày 31/12/2026.'),
(316, 9, 'Xây dựng kế hoạch và triển khai hạ tầng 5G, IoT trong các khu khu công nghiệp, cụm công nghiệp'),
(317, 7, 'Rà soát, cập nhật, hoàn thiện quy hoạch các khu công nghiệp, khu công nghệ cao trên địa bàn; kịp thời điều chỉnh hoặc kiến nghị cấp có thẩm quyền điều chỉnh các quy hoạch không còn phù hợp, bảo đảm đồng bộ với định hướng phát triển của Thành phố. Tập trung nghiên cứu, đề xuất giải pháp bảo đảm nguồn năng lượng ổn định, bền vững phục vụ phát triển công nghiệp công nghệ cao; định hướng xây dựng các mô hình ‘Khu công nghiệp thế hệ mới’ (sinh thái, thông minh, tuần hoàn) nhằm thu hút và đón đầu dòng vốn đầu tư chất lượng cao'),
(318, 2, 'Nghiêm túc tiếp thu đầy đủ ý kiến của các đại biểu dự họp, khẩn trương khắc phục tồn tại, hạn chế; xác định rõ lộ trình, nhiệm vụ và giải pháp cụ thể để tổ chức thực hiện quyết liệt, hiệu quả trong năm 2026'),
(319, 2, 'Chủ trì, phối hợp các đơn vị có liên quan tham mưu, xây dựng kế hoạch triển khai đồng bộ 07 điều kiện trọng tâm nêu tại Mục 2 Thông báo này (kế hoạch triển khai 07 điều kiện phải kèm: (i) danh mục các trường đại học và viện nghiên cứu dự kiến thu hút; (ii) danh mục ngành lõi; (iii) danh mục doanh nghiệp công nghệ đầu tàu hiện có/dự kiến thu hút; (iv) danh mục bài toán/đơn hàng công nghệ dự kiến đặt hàng 2026–2028; (v) danh mục hạ tầng tri thức dùng chung phải có ngay, gắn với các đơn hàng và doanh nghiệp đầu tàu; (vi) Xác định KPI lõi gồm: số trường đại học và viện nghiên cứu; số đơn hàng/đặt hàng công nghệ quy mô đủ lớn được triển khai; số sản phẩm, công nghệ được thương mại hóa; số doanh nghiệp công nghệ đầu tàu và chuỗi vệ tinh hình thành xung quanh). Xác định rõ nhiệm vụ, tiến độ, sản phẩm, đầu mối phối hợp. Phân định rõ nội dung thuộc thẩm quyền Thành phố nội dung thuộc trách nhiệm của Ban Quản lý và các đơn vị liên quan; báo cáo Ban chỉ đạo 57 Thành ủy trước ngày 15/03/2026'),
(320, 2, 'Khẩn trương tổng hợp, đề xuất những chính sách đột phá để phát triển Khu công nghệ cao Hòa Lạc, bảo đảm đồng bộ, thống nhất với Quy hoạch tổng thể Thủ đô tầm nhìn 100 năm'),
(321, 2, 'Chủ trì, phối hợp với các doanh nghiệp đang hoạt động tại Khu Công nghệ cao Hòa lạc tổ chức rà soát, đánh giá lại lộ trình phát triển; xác định rõ những nội dung cần điều chỉnh, bổ sung nhằm nâng cao hiệu quả hoạt động. Trên cơ sở đó, xây dựng phương án cơ cấu lại phù hợp; xử lý theo quy định đối với các mô hình hoạt động kém hiệu quả, bảo đảm sử dụng nguồn lực đúng mục tiêu, hiệu quả và bền vững'),
(322, 6, 'Phân công đồng chí Trương Việt Dũng, Thành ủy viên, Phó Chủ tịch UBND Thành phố trực tiếp chỉ đạo Ban Quản lý các Khu công nghệ cao và Khu công nghiệp thành phố Hà Nội chủ trì, phối hợp với các cơ quan, đơn vị liên quan xây dựng Báo cáo tổng thể về định hướng, nhiệm vụ và giải pháp phát triển Khu công nghệ cao Hòa Lạc trong giai đoạn mới; báo cáo Ban Thường vụ Thành ủy. Báo cáo tập trung làm rõ: Kết quả thực hiện các kết luận, chỉ đạo liên quan; tồn tại, hạn chế, nguyên nhân, trách nhiệm và những nội dung cần thay đổi trong phương thức tổ chức thực hiện. Vị trí, vai trò, mục tiêu, định hướng và mô hình phát triển Khu công nghệ cao Hòa Lạc trong tổng thể phát triển khu vực phía Tây Thành phố. Việc rà soát quy hoạch Khu công nghệ cao Hòa Lạc với quy mô hiện có 1.586 ha và phạm vi mở rộng 460 ha, tổng quy mô 2.046 ha; việc kết nối với Đại học Quốc gia Hà Nội, các trường đại học, viện nghiên cứu, hệ thống giao thông, các khu đô thị, đô thị thông minh và không gian phát triển xung quanh. Lợi thế cạnh tranh thực chất của Khu Công nghệ cao Hòa Lạc so với các điểm đến đầu tư cạnh tranh trong khu vực; giải pháp thu hút nhà đầu tư có chất lượng, nhất là nhà đầu tư lớn, doanh nghiệp dẫn dắt có khả năng kéo hệ sinh thái, doanh nghiệp vệ tinh, chuỗi cung ứng, nhân lực chất lượng cao, trung tâm nghiên cứu và phát triển vào Hòa Lạc; đề xuất chính sách đặc biệt đủ sức cạnh tranh, gắn với ràng buộc cụ thể về vốn, công nghệ, tiến độ, hiệu quả sử dụng đất và mức độ đóng góp cho hệ sinh thái. Kết quả rà soát các dự án đã được chấp thuận và các dự án đang nghiên cứu, chuẩn bị đầu tư; năng lực nhà đầu tư, tiến độ thực hiện, hiệu quả sử dụng đất, mức độ đáp ứng tiêu chí công nghệ cao và phương án xử lý theo quy định đối với các dự án không triển khai, chậm triển khai, sử dụng đất kém hiệu quả hoặc không còn đáp ứng tiêu chí. Kết quả rà soát các cơ chế, chính sách, quy định và thủ tục hành chính liên quan đến hoạt động của Khu công nghệ cao Hòa Lạc; mô hình quản lý, vận hành, khai thác và phương án tổ chức bộ máy phù hợp, bảo đảm hoạt động hiệu lực, hiệu quả.'),
(323, 26, 'Hoàn thành kiện toàn Ban Chỉ đạo về phát triển khoa học, công nghệ, đổi mới sáng tạo, chuyển đổi số do đồng chí Bí thư tỉnh uỷ, thành uỷ làm Trưởng Ban Chỉ đạo, không duy trì 02 Ban Chỉ đạo như trước đây.'),
(324, 26, 'Thành lập Hội đồng/Tổ Tư vấn Thành phố về phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số gồm các chuyên gia, nhà quản lý, nhà khoa học.'),
(325, 26, 'Thành lập Tổ Thường trực, theo dõi đôn đốc, giám sát thực hiện các nhiệm vụ của Ban Chỉ đạo 57 Thành ủy và tham mưu, đề xuất 04 nhóm trụ cột (Thể chế - Hạ tầng - Nhân lực - Đổi mới sáng tạo).'),
(326, 29, 'Quy định tạm thời về công tác theo dõi, đôn đốc và kiểm tra việc thực hiện nhiệm vụ trên Hệ thống theo dõi nhiệm vụ của Thành phố'),
(327, 29, 'Xây dựng Dự thảo Đề án đầu tư xây dựng Trung tâm điều hành thông minh của Thành ủy'),
(328, 29, 'Xây dựng kế hoạch triển khai Hệ thống thông tin điều hành tác nghiệp trong các cơ quan đảng thành phố Hà Nội trên mạng Internet'),
(329, 30, 'Văn phòng Thành ủy rà soát, tổng hợp những cơ quan, đơn vị không thực hiện nghiêm túc chế độ thông tin, báo cáo (nếu có), kịp thời báo cáo Ban Chỉ đạo 57 Thành ủy, Tổ Thường trực để xem xét, xử lý trách nhiệm theo quy định.'),
(330, 30, 'Dự thảo Báo cáo đánh giá kết quả triển khai thực hiện Nghị quyết số 57-NQ/TW của Bộ Chính trị; đồng thời rà soát, xác định những khó khăn, vướng mắc, điểm nghẽn trong quá trình triển khai; đề xuất các giải pháp và nhiệm vụ trọng tâm năm 2026'),
(331, 31, 'Chuẩn bị bài phát biểu tham luận của đại diện lãnh đạo thành phố Hà Nội tại Hội nghị Tổng kết chuyển đổi số trong các cơ quan đảng năm 2025 và nhiệm vụ trọng tâm năm 2026 do Văn phòng Trung ương Đảng tổ chức'),
(332, 31, 'Hoàn thiện Tờ trình xin ý kiến đồng chí Bí thư Thành ủy về việc tổ chức Hội nghị tổng kết năm 2025 và nhiệm vụ trọng tâm triển khai năm 2026 của Ban chỉ đạo 57 của Thành ủy.'),
(333, 27, 'Xây dựng Báo cáo của Ban Chỉ đạo 57 Thành ủy về kết quả triển khai thực hiện Nghị quyết số 57-NQ/TW và nhiệm vụ trọng tâm năm 2026 (Khối Đảng)'),
(334, 7, 'Giao Văn phòng Thành ủy chủ trì theo dõi, tổng hợp, đánh giá kết quả triển khai thực tế của từng cơ quan, đơn vị, làm rõ nội dung đã thực hiện, chưa thực hiện, nguyên nhân và trách nhiệm của các tập thể, cá nhân liên quan, báo cáo phục vụ giao ban tháng của toàn hệ thống chính trị Thành phố.'),
(335, 24, 'Văn phòng Thành ủy theo dõi, đôn đốc việc Đảng ủy UBND Thành phố  chỉ đạo các cơ quan, đơn vị liên quan tổ chức thực hiện nghiêm các kết luận của Thường trực Thành ủy, Ban Thường vụ Thành ủy và rà soát, xác định rõ đơn vị chủ trì, loại bỏ các khâu trung gian trong toàn bộ hệ thống chính trị; tổng hợp, báo cáo Thường trực Thành ủy để xem xét, chỉ đạo'),
(336, 24, 'Giao Tổ Thường trực Ban Chỉ đạo 57 Thành ủy đề xuất Ban Chỉ đạo xây dựng, hoàn thiện thể chế, chính sách đặc thù phát triển Thủ đô nghiên cứu, ban hành những chính sách đột phá để phát triển Khu công nghệ cao và các khu công nghiệp trên địa bàn Thành phố; bảo đảm đồng bộ, thống nhất với định hướng của Ban Chỉ đạo rà soát, nghiên cứu lập Quy hoạch tổng thể Thủ đô tầm nhìn 100 năm và Kế hoạch số 20-KH/BCĐ57 ngày 19/01/2026 của Ban Chỉ đạo 57 Thành ủy.'),
(337, 13, 'Rà soát, tham mưu kiện toàn Ban Chỉ đạo 57 Thành ủy; đề xuất bổ sung, điều chỉnh thành phần và phân công nhiệm vụ các thành viên theo cơ cấu tổ chức, chức năng, nhiệm vụ mới của các sở, ngành, bảo đảm rõ người, rõ việc, đúng thẩm quyền, nâng cao hiệu lực, hiệu quả tổ chức thực hiện, tránh chồng chéo, bỏ sót nhiệm vụ'),
(338, 13, 'Chủ trì, phối hợp các cơ quan liên quan khẩn trương ban hành mẫu báo cáo số thống nhất và hướng dẫn triển khai thực hiện; giảm tối đa việc yêu cầu báo cáo bằng văn bản giấy, hạn chế trùng lặp, bảo đảm thống nhất, hiệu quả trong tổ chức thực hiện'),
(339, 1, 'Chủ trì, phối hợp chặt chẽ với các cơ quan, đơn vị liên quan, đặc biệt là Văn phòng UBND Thành phố, tăng cường trao đổi thông tin, thống nhất nội dung, bảo đảm chuẩn bị đầy đủ, kịp thời các tài liệu phục vụ các cuộc họp của Ban Chỉ đạo 57 Thành ủy và báo cáo Trung ương theo yêu cầu'),
(340, 1, 'Định kỳ hằng tuần, hằng tháng tổng hợp, công khai kết quả thực hiện nhiệm vụ của Ban Chỉ đạo; kịp thời tham mưu đề xuất khen thưởng đột xuất đối với các đơn vị hoàn thành vượt tiến độ, bảo đảm chất lượng; đồng thời thông báo cụ thể các nhiệm vụ có nguy cơ chậm tiến độ, lãng phí, gửi trực tiếp đến từng cơ quan, đơn vị để rà soát, khắc phục'),
(341, 1, 'Tổ chức số hóa toàn bộ Kế hoạch của Thành ủy; xây dựng, vận hành kế hoạch tháng, quý, năm và lịch công tác tuần trên môi trường số, bảo đảm theo dõi, kiểm đếm được tiến độ và kết quả thực hiện'),
(342, 1, 'Chủ trì tổng hợp, hoàn thiện văn bản để Thường trực Thành ủy ký gửi Ban Chỉ đạo Trung ương; xây dựng danh mục kiến nghị riêng, rõ nội dung, rõ đề xuất; trong đó có kiến nghị Ban Tổ chức Trung ương chia sẻ dữ liệu và tháo gỡ khó khăn trong việc triển khai đóng đảng phí trực tuyến của đảng viên'),
(343, 14, 'Chủ trì, phối hợp với các cơ quan, đơn vị liên quan thiết lập cơ chế theo dõi, cảnh báo tiến độ thực hiện nhiệm vụ trên môi trường số đối với các nhiệm vụ thuộc Kế hoạch số 20-KH/BCĐ57, bảo đảm kiểm soát tiến độ theo từng nhiệm vụ, cơ quan chủ trì, mốc thời gian và sản phẩm cụ thể, kịp thời phát hiện các nhiệm vụ chậm tiến độ hoặc phát sinh khó khăn, vướng mắc để tham mưu Ban Chỉ đạo 57 Thành ủy xem xét, chỉ đạo'),
(344, 17, 'Về hệ thống Trung tâm giám sát, điều hành thông minh (IOC) Giao Văn phòng Thành ủy tiếp tục hoàn thiện, triển khai và tổ chức vận hành Hệ thống Trung tâm giám sát, điều hành thông minh (IOC) của Thành ủy; khẩn trương rà soát, hoàn thiện Quy chế vận hành, khai thác, gắn với nền tảng AI và hệ thống theo dõi, đôn đốc nhiệm vụ dùng chung; bảo đảm đưa hệ thống vào vận hành từ ngày 01/5/2026.'),
(345, 17, 'Giao Văn phòng Thành ủy chủ trì, phối hợp các cơ quan, đơn vị liên quan rà soát lại toàn bộ danh mục nhiệm vụ chậm muộn, quá hạn; phân biệt rõ nhiệm vụ còn chậm thực chất với nhiệm vụ đã được cấp có thẩm quyền thống nhất điều chỉnh tiến độ để cập nhật theo mốc mới; báo cáo Ban Chỉ đạo 57 Thành ủy trước ngày 14/4/2026; đồng thời tiếp tục duy trì chế độ báo cáo hằng tuần với Thường trực Thành ủy, Ban Thường vụ Thành ủy và Ban Chỉ đạo 57 Thành ủy để phục vụ theo dõi, chỉ đạo.'),
(346, 18, 'Văn phòng Thành ủy - Cơ quan Thường trực Ban Chỉ đạo 57 Thành ủy chủ trì, phối hợp với các cơ quan, đơn vị liên quan rà soát, phân loại toàn bộ danh mục nhiệm vụ về khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số đang theo dõi; xác định rõ nhóm nhiệm vụ trọng tâm, cấp bách, có tác động lớn đến tiến độ chung; nhóm nhiệm vụ tiếp tục đôn đốc thường xuyên; nhóm nhiệm vụ cần điều chỉnh tiến độ, phạm vi hoặc phương thức thực hiện.'),
(347, 18, 'Tập trung rà soát 30 nhiệm vụ quá hạn; làm rõ nguyên nhân, cơ quan chủ trì, cơ quan phối hợp, khâu đang chậm, sản phẩm còn thiếu, thời hạn hoàn thành mới và nội dung vượt thẩm quyền nếu có. Trên cơ sở đó, tham mưu lựa chọn một số nhiệm vụ quan trọng, có tính nền tảng hoặc đang là điểm nghẽn lớn để báo cáo Thường trực Thành ủy, Ban Thường vụ Thành ủy, Ban Chỉ đạo 57 Thành ủy xem xét, chỉ đạo trong tháng 5/2026.'),
(348, 4, 'Chủ trì, phối hợp các cơ quan liên quan rà soát, phân loại danh mục nhiệm vụ về khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số; xác định nhiệm vụ trọng tâm, cấp bách, nhiệm vụ chậm, muộn, sắp đến hạn và nhiệm vụ cần điều chỉnh; tham mưu đường găng tiến độ đối với nhiệm vụ then chốt. Đối với nhiệm vụ chậm, quá hạn hoặc có nguy cơ chậm, yêu cầu cơ quan chủ trì báo cáo rõ nguyên nhân, trách nhiệm, phương án xử lý; trường hợp cần thiết, báo cáo Trưởng Ban Chỉ đạo xem xét, chỉ đạo. Hoàn thành rà soát lần đầu trước ngày 30/5/2026.'),
(349, 4, 'Phối hợp với Văn phòng UBND Thành phố, Sở Khoa học và Công nghệ và các cơ quan liên quan nghiên cứu, đề xuất xây dựng hệ thống báo cáo số dùng chung cho 04 trục; thí điểm trong tháng 6/2026 đối với các nội dung đủ điều kiện, bảo đảm phân quyền, an toàn thông tin, kết nối với hệ thống của Trung ương, giảm báo cáo trùng lặp, báo cáo thủ công, nhập liệu nhiều lần.'),
(350, 19, 'Về Không gian làm việc số HanoiWork và hệ thống báo cáo số: Văn phòng Thành ủy chủ trì, phối hợp các cơ quan liên quan rà soát chế độ báo cáo số, hệ thống theo dõi, đôn đốc nhiệm vụ trên nền tảng số; đề xuất phương án khắc phục tình trạng nhập liệu nhiều lần, báo cáo trùng lặp, báo cáo thủ công; báo cáo Ban Chỉ đạo 57 Thành ủy đối với nội dung vượt thẩm quyền hoặc cần chỉ đạo tháo gỡ'),
(351, 6, 'Theo dõi, đôn đốc việc thực hiện Thông báo này; tổng hợp tiến độ, kết quả, khó khăn, vướng mắc, kịp thời báo cáo Thường trực Thành ủy xem xét, chỉ đạo.'),
(352, 20, 'Giao Văn phòng Thành ủy - Cơ quan Thường trực Ban Chỉ đạo 57 Thành ủy theo dõi, tổng hợp tình hình thực hiện; tham mưu báo cáo Ban Chỉ đạo theo quy định.'),
(353, 21, '(1) Phối hợp với Ban Tổ chức Thành ủy chuẩn hóa đầu bài, tổ chức khảo sát; cung cấp thông tin, dữ liệu và điều kiện kỹ thuật phục vụ đánh giá.'),
(354, 21, '(2) Tổ chức thí điểm đánh giá cán bộ gắn với phương pháp OKR/KPI trên Hệ thống quản lý, theo dõi, đôn đốc thực hiện nhiệm vụ dùng chung 04 trục tại một số cơ quan, đơn vị không trùng với các đơn vị đang thí điểm trên HanoiWork; bảo đảm cùng đầu bài, điều kiện và bộ tiêu chí để đối chiếu, đánh giá khách quan, không làm phát sinh nhập liệu trùng lặp.'),
(355, 22, 'Tham mưu đồng chí Phó Bí thư Thành ủy chỉ đạo các đồng chí Bí thư Đảng ủy 126 xã, phường tập trung lãnh đạo, chỉ đạo thực hiện làm sạch dữ liệu đất đai. Kết quả thực hiện đến ngày 30/8/2026 được đối chiếu với KPI đã được thông báo đến từng xã, phường và sử dụng làm căn cứ đánh giá kết quả thực hiện nhiệm vụ, trách nhiệm người đứng đầu trong quý III/2026.'),
(356, 22, 'Khẩn trương tham mưu văn bản giao nhiệm vụ cho các cơ quan, đơn vị liên quan xây dựng kế hoạch khắc phục 08 nội dung hạn chế thuộc lĩnh vực khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số theo kết luận kiểm tra của Bộ Chính trị đối với Ban Thường vụ Thành ủy về thực hiện nhiệm vụ phát triển tăng trưởng hai con số,'),
(357, 22, 'Chủ trì, phối hợp Sở Khoa học và Công nghệ, Văn phòng UBND Thành phố và các cơ quan đơn vị có liên quan chuẩn bị nội dung họp Ban Chỉ đạo 57 Thành ủy, tập trung vào 02 nội dung: (i) xây dựng, kết nối, chia sẻ và khai thác cơ sở dữ liệu; (ii) phát triển kinh tế số.'),
(358, 5, 'Về điều chỉnh kế hoạch hành động số 20-KH/BCĐ57: Giao Văn phòng Thành ủy khẩn trương rà soát, hoàn thiện dự thảo văn bản điều chỉnh, trình đồng chí Bí thư Thành ủy xem xét, quyết định để tổ chức triển khai thực hiện.'),
(359, 8, 'lãnh đạo, chỉ đạo triển khai chuyển đổi số đồng bộ, thực chất, xác định đây là yêu cầu bắt buộc, không làm hình thức. Kiên quyết đổi mới phương thức lãnh đạo, chỉ đạo, điều hành và tổ chức thực hiện nhiệm vụ trên môi trường số; chấm dứt tình trạng vận hành song song giữa phương thức truyền thống và phương thức số đối với các quy trình, nghiệp vụ đã đủ điều kiện. Chậm nhất trước ngày 15/02/2026, ban hành Kế hoạch chuyển đổi số toàn hệ thống chính trị Thành phố (phân công rõ đầu mối, nhiệm vụ, lộ trình, chỉ tiêu định lượng, nguồn lực); gắn kết quả chuyển đổi số với trách nhiệm người đứng đầu và đánh giá mức độ hoàn thành nhiệm vụ của từng cơ quan, đơn vị.'),
(360, 9, 'Xây dựng kế hoạch kiểm tra, giám sát việc thực hiện NQ57 và kết luận Thành ủy'),
(361, 10, 'Ủy ban Kiểm tra Thành ủy làm việc với các Sở Công Thương, Sở Tư pháp, Sở Y tế xem xét nguyên nhân chủ quan, khách quan về việc chưa mở dữ liệu theo danh mục đã ban hành'),
(362, 24, 'Ủy ban Kiểm tra Thành ủy tăng cường giám sát việc tổ chức triển khai thực hiện các kết luận của Ban Thường vụ, Thường trực Thành ủy; kịp thời phát hiện, xem xét, xử lý hoặc đề xuất xử lý đối với các tập thể, cá nhân chậm trễ, không đạt yêu cầu theo quy định.'),
(363, 13, 'Giao Ủy ban Kiểm tra Thành ủy tăng cường theo dõi việc chấp hành kỷ luật báo cáo, làm rõ trách nhiệm người đứng đầu đối với trường hợp phát sinh yêu cầu báo cáo không đúng quy định'),
(364, 16, 'Tăng cường theo dõi, kiểm tra, giám sát; chủ động cảnh báo sớm các biểu hiện chậm tiến độ, kém hiệu quả, lệch hướng trong quá trình tổ chức thực hiện; kiến nghị xử lý nghiêm các trường hợp thiếu trách nhiệm, né tránh, đùn đẩy, chậm trễ kéo dài.'),
(365, 22, 'tăng cường theo dõi, giám sát, đôn đốc đối với 03 nhóm nội dung trọng tâm: (i) Tiến độ và kết quả xây dựng cơ sở dữ liệu đất đai tại 126 xã, phường; (ii) Tiến độ giải ngân kinh phí khoa học, công nghệ, đổi mới sáng tạo, chuyển đổi số; (iii) Việc hình thành các cơ sở dữ liệu chuyên ngành theo kế hoạch. Kết quả thực hiện nhiệm vụ là căn cứ xem xét, đánh giá trách nhiệm, năng lực tổ chức thực hiện của cơ quan, đơn vị và người đứng đầu trong quý III/2026.'),
(366, 16, 'Hoàn thiện đề xuất ứng dụng trí tuệ nhân tạo trong hỗ trợ hộ kinh doanh kê khai, nộp thuế, phân tích sức khỏe doanh nghiệp, phục vụ quản lý thuế, quản trị rủi ro và nuôi dưỡng nguồn thu; bảo đảm rõ mục tiêu, rõ phạm vi, rõ lộ trình, rõ hiệu quả, rõ điều kiện triển khai.'),
(367, 32, 'Chủ động triển khai đầy đủ giải pháp bảo đảm an toàn hệ thống thông tin theo cấp độ ngay từ khâu thiết kế, đầu tư, vận hành; ưu tiên các hệ thống nền tảng, hệ thống phục vụ thủ tục hành chính và hệ thống dữ liệu lõi. Nhiệm vụ thường xuyên; định kỳ hằng tháng báo cáo.'),
(368, 32, 'Hướng dẫn thực hiện Luật Bảo vệ dữ liệu cá nhân; nghiên cứu triển khai các giải pháp ngăn chặn lừa đảo trực tuyến và nhận diện thông tin giả mạo để bảo vệ người dân.'),
(369, 32, 'Xây dựng Đề án phát triển đô thị thông minh thành phố Hà Nội'),
(370, 32, 'Công an Thành phố chủ trì thực hiện chuẩn hóa hệ thống camera (Điều chỉnh tên, đơn vị chủ trì theo Quyết định số 37- QĐ/BCĐ57)'),
(371, 32, 'Tái cấu trúc 80% thủ tục hành chính dựa trên cơ sở dữ liệu.'),
(372, 32, 'Rà soát, cắt giảm, đơn giản hóa thủ tục hành chính dựa trên dữ liệu.'),
(373, 33, 'Lựa chọn nhóm thủ tục hành chính có tần suất cao, liên quan trực tiếp đến người dân, doanh nghiệp'),
(374, 33, 'Tái thiết kế quy trình theo hướng đơn giản hoá thành phần hồ sơ, giảm thao tác trên môi trường số bảo đảm người dân, doanh nghiệp không phải cung cấp lại dữ liệu đã có trong CSDL của cơ quan nhà nước'),
(375, 33, 'Kết nối Hệ thống thông tin giải quyết TTHC với các CSDL đã công bố và các CSDL mới hoàn thành; tự động điền, xác thực và tái sử dụng dữ liệu'),
(376, 32, 'Nghiên cứu, tham mưu đề xuất sửa đổi, bổ sung, hoàn thiện các quy định của Luật Thủ đô liên quan đến khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số theo hướng tạo cơ chế, chính sách đột phá, đặc thù cho Thủ đô.'),
(377, 32, 'Xây dựng và áp dụng hệ thống quy chuẩn, tiêu chuẩn, yêu cầu về khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số trong quản lý nhà nước của Thành phố; quy định rõ trách nhiệm của các cơ quan, đơn vị trong việc áp dụng, tuân thủ và giải trình. Đồng thời, tích hợp các yêu cầu về khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số thành cấu phần bắt buộc trong quy trình lập, thẩm định và phê duyệt quy hoạch, đề án, dự án, đồ án. Song song với đó, xây dựng định mức kinh tế – kỹ thuật và đơn giá đối với các sản phẩm, dịch vụ trong lĩnh vực khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số, bảo đảm phù hợp với thực tiễn triển khai.'),
(378, 32, 'Xây dựng và ban hành hệ thống “bài toán lớn” của Thành phố làm cơ sở thống nhất để đặt hàng, tổ chức triển khai các nhiệm vụ khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số.'),
(379, 32, 'Ban hành quy chế bắt buộc áp dụng các công cụ số, không gian làm việc số, bộ KPI đo lường và AI trong xử lý văn bản, báo cáo (“AI First” trong quy trình làm việc).'),
(380, 32, 'Ban hành khung năng lực số của đảng viên, cán bộ, công chức, viên chức, người lao động trong hệ thống chính trị của Thành phố, gắn với từng vị trí việc làm.'),
(381, 32, 'Thí điểm mô hình Trợ lý ảo công vụ tại đơn vị có khối lượng hồ sơ lớn, đánh giá và nhân rộng toàn Thành phố; thử nghiệm tích hợp AI Copilot chuyên ngành vào hệ thống quản lý văn bản; đào tạo kỹ năng làm việc với AI cho cán bộ, công chức, viên chức, người lao động.'),
(382, 32, 'Trang bị Dashboard cá nhân hóa cho các cấp lãnh đạo theo dõi chỉ số kinh tế - xã hội và xử lý kiến nghị người dân theo thời gian thực.'),
(383, 32, 'Ban hành khung pháp lý và hướng dẫn thống nhất về xây dựng, áp dụng và sử dụng KPI trong hệ thống chính trị Thành phố.'),
(384, 32, 'Xây dựng và triển khai bộ KPI phù hợp với đặc thù Hà Nội để định lượng hiệu quả hoạt động của các cơ quan, đơn vị trong hệ thống chính trị Thành phố, từ Thành ủy - HĐND - UBND đến các sở, ban, ngành và chính quyền cấp cơ sở. Ưu tiên triển khai theo mô hình 3 nhà (ưu tiên phối hợp với Trường Đại học Kinh tế - Đại học Quốc gia Hà Nội).'),
(385, 32, 'Tổng kiểm kê, quy hoạch lại toàn bộ tài sản số; cắt bỏ các hệ thống chồng chéo; hợp nhất dữ liệu, hệ thống thông tin; ban hành quy chế chia sẻ dữ liệu bắt buộc.'),
(386, 32, 'Rà soát, nâng cấp và bảo đảm điều kiện tối thiểu phục vụ chuyển đổi số của Thành phố (đặc biệt là tại cấp xã) như: (1) đường truyền và kết nối mạng ổn định, chữ ký số cá nhân; (2) trang bị máy tính cấu hình tối thiểu và thiết bị làm việc thiết yếu; (3) bố trí cán bộ phụ trách công nghệ thông tin, chuyển đổi số phù hợp với khối lượng công việc. Đối với đơn vị cấp xã, việc rà soát, nâng cấp bảo đảm đồng bộ, thống nhất với Mô hình chuyển đổi số cấp xã do Bộ Khoa học và Công nghệ hướng dẫn. Hoàn thành trong Quý I/2026'),
(387, 32, 'Xây trợ lý ảo, tổng đài thông minh dùng chung; chia sẻ camera dùng chung; đầu tư nội địa hóa camera AI, máy tính và sản phẩm công nghệ.'),
(388, 32, 'Hoàn thành toàn diện việc xây dựng Kho dữ liệu tập trung. Hoàn thành đầu tư Trung tâm dữ liệu dùng chung của Thành phố, Trung tâm tính toán thông minh (AIDC)'),
(389, 32, 'Xây dựng và triển khai các chương trình nghiên cứu cơ bản trọng điểm cấp Thành phố, có tính liên ngành, liên cơ sở, thời gian thực hiện dài hạn (5–10 năm), gắn trực tiếp với hệ thống “bài toán lớn” của Thủ đô; tập trung vào các lĩnh vực then chốt như: đô thị thông minh, phát triển bền vững, môi trường – năng lượng, giao thông, y tế – giáo dục, kinh tế số, quản trị công và các lĩnh vực ưu tiên khác của Thủ đô. Hoàn thành việc ban hành danh mục chương trình trong Quý I/2026; việc triển khai thực hiện theo thời hạn của từng chương trình cụ thể'),
(390, 32, 'Thực hiện đặt hàng nghiên cứu cơ bản đối với các trường đại học, viện nghiên cứu, nhóm nghiên cứu mạnh trên địa bàn Thành phố và trong cả nước; khuyến khích sự tham gia của các nhà khoa học đầu ngành, chuyên gia quốc tế, bảo đảm chất lượng khoa học, tính kế thừa và khả năng phát triển dài hạn'),
(391, 32, 'Nghiên cứu, đề xuất giải pháp thúc đẩy kinh phí chi cho nghiên cứu phát triển (R&D) đạt 2% GDP, trong đó kinh phí từ xã hội chiếm hơn 60%.'),
(392, 32, 'Chuẩn hóa, số hóa toàn bộ kết quả nghiên cứu cơ bản để tích hợp vào Kho dữ liệu tri thức dùng chung của Thành phố.'),
(393, 32, 'Ban hành Danh mục công nghệ chiến lược ưu tiên của Thành phố Hà Nội giai đoạn 2026–2035.'),
(394, 32, 'Ban hành cơ chế, chính sách đặc thù để thúc đẩy hợp tác nghiên cứu, tiếp nhận và làm chủ công nghệ chiến lược.'),
(395, 32, 'Rà soát, đánh giá tổng thể hiện trạng các viện nghiên cứu, trung tâm nghiên cứu, phòng thí nghiệm, cơ sở thử nghiệm trên địa bàn Thành phố; xác định rõ năng lực, mức độ trùng lặp, hiệu quả khai thác và khả năng phát triển; trên cơ sở đó, xây dựng Đề án quy hoạch, sắp xếp và phát triển hệ thống viện nghiên cứu và phòng thí nghiệm/thử nghiệm trọng điểm của Thủ đô theo hướng tập trung, có trọng tâm, trọng điểm, tránh dàn trải, để phục vụ cho hoạt động nghiên cứu cơ bản, thử nghiệm các công nghệ lõi, công nghệ chiến lược, các giải pháp mới, mô hình mới của Thành phố. Hoàn thành trong Quý I/2026.'),
(396, 32, 'Thành lập Phòng Kinh tế số – Xã hội số trực thuộc Sở Khoa học và Công nghệ.'),
(397, 32, 'Tổ chức đánh giá trình độ công nghệ đối với doanh nghiệp/cụm ngành chủ lực của Thành phố'),
(398, 32, 'Xây dựng kế hoạch nâng cấp dây chuyền gắn mục tiêu nâng năng suất, chất lượng; Hình thành tối thiểu 01 mô hình thí điểm có thể nhân rộng (theo chuỗi giá trị hoặc theo ngành chủ lực của Thành phố), có bộ chỉ tiêu kết quả và cơ chế duy trì sau thí điểm (đặt hàng dịch vụ, doanh thu, xã hội hóa),'),
(399, 32, 'Tham mưu ban hành Nghị quyết Hội đồng nhân dân Thành phố về chính sách đặc thù để phát triển kinh tế số Thủ đô, thúc đẩy tăng trưởng từ khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số'),
(400, 32, 'Xây dựng và triển khai Chương trình “Doanh nghiệp tăng trưởng nhanh dựa trên công nghệ”; Đề án hỗ trợ doanh nghiệp nhỏ và vừa chuyển đổi số, tham gia chuỗi cung ứng và mở rộng thị trường; Đề án thu hút doanh nghiệp khởi nghiệp của người Việt ở nước ngoài về Việt Nam'),
(401, 32, 'Xây dựng khung năng lực số của công dân Thủ đô; kèm theo Quy chế đánh giá, phân loại và áp dụng khung năng lực này trong các lĩnh vực kinh tế – xã hội; làm căn cứ thống nhất cho tổ chức đào tạo, phổ cập và đánh giá mức độ sẵn sàng số của người dân'),
(402, 32, 'Tổ chức phổ cập năng lực số cho công dân theo lộ trình và phân nhóm đối tượng (học sinh, sinh viên, người lao động, người cao tuổi, nhóm yếu thế) thông qua Đề án phổ cập năng lực số, gắn với nhu cầu sử dụng thực tế. Phát huy vai trò của nhà trường, tổ dân phố, tổ công nghệ số cộng đồng và các nền tảng số của Thành phố. Trong đó, dùng áp lực học tập bằng các thao tác số bắt buộc phải thực hiện trong các dịch vụ thiết yếu'),
(403, 32, 'Rà soát, xác định và công bố danh mục (danh mục chi tiết) các điểm nghẽn đô thị trọng tâm của Thủ đô cần ưu tiên giải quyết bằng khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số, tập trung vào các lĩnh vực: giao thông – ùn tắc, môi trường – ô nhiễm, quản lý đất đai – quy hoạch – xây dựng, hạ tầng kỹ thuật đô thị, an toàn – trật tự đô thị, phòng chống thiên tai và thích ứng biến đổi khí hậu.'),
(404, 32, 'Tổ chức đặt hàng các bài toán công nghệ và đổi mới sáng tạo để giải quyết các điểm nghẽn đô thị theo danh mục được phê duyệt; khuyến khích tiếp cận theo hướng tích hợp liên ngành, kết hợp dữ liệu, mô hình dự báo, trí tuệ nhân tạo, công nghệ số và các giải pháp phi công nghệ (thể chế, quy trình, tổ chức).'),
(405, 32, 'Ứng dụng dữ liệu số, mô hình mô phỏng và phân tích dự báo (bao gồm bản sao số – Digital Twin đối với một số cấu phần đô thị) để hỗ trợ công tác quy hoạch, điều hành đô thị theo thời gian thực, giảm độ trễ trong ra quyết định và nâng cao hiệu quả quản lý.'),
(406, 32, 'Sở Khoa học và Công nghệ chủ trì tham mưu ban hành Nghị quyết của Hội đồng nhân dân Thành phố về chính sách đặc thù phát triển hệ sinh thái đổi mới sáng tạo “Make in Hanoi”, trong đó xác định rõ: đối tượng hỗ trợ, cơ chế ưu đãi, phương thức Nhà nước tham gia với vai trò kiến tạo và dẫn dắt thị trường; gói chính sách thu hút có chọn lọc; tăng cường xúc tiến đầu tư trọng điểm; kết nối doanh nghiệp với hệ sinh thái đổi mới sáng tạo của Thành phố. Đồng thời, xây dựng bộ chỉ số theo dõi, đánh giá hệ sinh thái khởi nghiệp đổi mới sáng tạo (bao gồm chỉ số kết quả và chỉ số điều hành), làm công cụ quản trị, giám sát và điều chỉnh chính sách. Hoàn thành trong Quý I/2026.'),
(407, 32, 'Thí điểm và mở rộng cơ chế đặt hàng, mua sắm công đối với sản phẩm từ kết quả của hoạt động KHCN, ĐMST; tổ chức thí điểm tối thiểu 03 gói mua sắm công đối với sản phẩm/giải pháp từ kết quả của hoạt động KHCN, ĐMST được ứng dụng trong khu vực công.'),
(408, 32, 'Tổ chức triển khai mô hình chuyển đổi số cấp xã như một mô hình đổi mới phương thức quản trị cơ sở, làm nền tảng cho chính quyền số cấp xã, đồng thời thúc đẩy kinh tế số và xã hội số tại cộng đồng dân cư (thôn, bản, tổ dân phố). Hoàn thành trong Quý I/2026.'),
(409, 32, 'Thí điểm các mô hình đổi mới quản trị, không gian thử nghiệm thể chế tại một số địa bàn, lĩnh vực ưu tiên; tổng hợp, đánh giá và báo cáo kết quả trong tháng 12/2026 (Điều chỉnh tên nhiệm vụ theo Quyết định số 37- QĐ/BCĐ57)'),
(410, 32, 'Xây dựng các mô hình thử nghiệm “sandbox” đột phá về cơ chế hỗ trợ các doanh nghiệp khởi nghiệp sáng tạo, như: cơ chế về thủ tục thành lập doanh nghiệp; cơ chế về thuế, phí; cơ chế tiếp cận vốn từ quỹ phát triển khoa học, công nghệ, quỹ đầu tư rủi ro, quỹ đầu tư thiên thần, cơ chế đồng tài trợ giữa Nhà nước và doanh nghiệp; cơ chế mua sản phẩm đầu ra của các doanh nghiệp khởi nghiệp sáng tạo... Các cơ chế này phải đạt được mức độ ưu đãi ngang bằng hoặc vượt các nước trong khu vực'),
(411, 32, 'Xây dựng chương trình “Next 1.000” nhằm phát hiện sớm và ươm mầm năng khiếu khoa học – công nghệ trong các cấp giáo dục, gắn với giáo dục STEM/STEAM, khoa học dữ liệu, AI phù hợp từng cấp học.'),
(412, 32, 'Tổ chức các chương trình ươm mầm, trại hè khoa học, phòng thí nghiệm mở, cuộc thi nghiên cứu – sáng tạo, kết nối học sinh, sinh viên với giảng viên, nhà khoa học, doanh nghiệp công nghệ.'),
(413, 32, 'Xây dựng các chương trình liên kết đào tạo giữa các cơ sở giáo dục đại học chủ lực của Hà Nội với các trường đại học uy tín quốc tế; gắn đào tạo với nhu cầu sử dụng thực tiễn và chính sách đãi ngộ. Kết nối chặt chẽ kết quả ươm mầm, bồi dưỡng nhân tài với Chương trình học bổng đào tạo nghiên cứu sinh và các nhiệm vụ khoa học – công nghệ của Thành phố, bảo đảm tính kế thừa và phát triển liên tục'),
(414, 32, 'Xây dựng và ban hành Chương trình học bổng đào tạo 1.000 nghiên cứu sinh của Thành phố, xác định rõ lĩnh vực ưu tiên, tiêu chí lựa chọn, yêu cầu đầu ra của luận án và trách nhiệm sử dụng kết quả nghiên cứu.'),
(415, 32, 'Xây dựng Nghị quyết Hội đồng nhân dân Thành phố về chính sách hỗ trợ, phát triển đội ngũ thực hiện nhiệm vụ về khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số trong các cơ quan nhà nước thuộc Thành phố.'),
(416, 32, 'Ban hành Đề án Kiện toàn bộ máy chuyên trách thực hiện nhiệm vụ khoa học và công nghệ; trong đó, hình thành Trung tâm dữ liệu và công nghệ số Thành phố Hà Nội - đầu mối duy nhất và tập trung của Thành phố, trên cơ sở hợp nhất các đơn vị sự nghiệp về dữ liệu, hệ thống, ứng dụng, chuyển đổi số của Sở Khoa học và Công nghệ và Trung tâm Phục vụ hành chính công Thành phố. Trong bộ máy của Sở Khoa học và Công nghệ, thành lập Phòng chiến lược khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số; và các phòng chuyên trách về Kinh tế số - Xã hội số, Phòng Dữ liệu và Chính quyền số. 
Bổ sung nhân lực thực hiện nhiệm vụ tại Sở Khoa học và Công nghệ: (1) Bổ sung tối thiểu 30 chỉ tiêu lao động hợp đồng theo Luật Thủ đô phù hợp với vị trí việc làm tại các phòng chuyên môn; (2) bổ sung tối thiểu 30 chuyên gia phù hợp với các lĩnh vực.'),
(417, 32, 'Nghiên cứu, đề xuất sửa đổi, bổ sung, hoàn thiện các quy định của Luật Thủ đô về KHCN, ĐMST và CĐS'),
(418, 32, 'Bản sao số (Digital Twin) thành phố Hà Nội (Điều chỉnh thời hạn theo Quyết định số 37- QĐ/BCĐ57)'),
(419, 32, 'Xây dựng Trung tâm dữ liệu dùng chung của Thành phố và Trung tâm tính toán thông minh (AIDC)'),
(420, 32, 'Đề án “Xây dựng cơ sở dữ liệu dùng chung từ số hóa tài liệu tập trung của các cơ quan trên địa bàn thành phố Hà Nội”'),
(421, 32, 'Hoàn thành Kho dữ liệu tập trung Thành phố'),
(422, 32, 'Phát triển Ứng dụng Công dân Thủ đô số (iHanoi)'),
(423, 32, 'Xây dựng Cơ sở dữ liệu chuyên gia, nhà khoa học của Thành phố'),
(424, 32, 'Mô hình Không gian làm việc số (HanoiWork)'),
(425, 32, 'Xây dựng Đề án phát triển kinh tế không gian tầm thấp đến năm 2030, định hướng đến năm 2045 (Điều chỉnh tên, thời hạn nhiệm vụ theo Quyết định số 37- QĐ/BCĐ57)'),
(426, 32, 'Phát triển mạng lưới Trung tâm đổi mới sáng tạo của Thành phố'),
(427, 32, 'Triển khai các Công viên công nghệ của Thành phố'),
(428, 32, 'Xây dựng và vận hành Chợ Chuyển đổi số, Sàn giao dịch công nghệ của Thành phố'),
(429, 32, 'Hình thành 03 trung tâm nghiên cứu đầu tư đổi mới sáng tạo, liên kết thử nghiệm và chuẩn hóa công nghệ trọng điểm của Thành phố'),
(430, 32, 'Đề án tổng thể về phát triển nguồn nhân lực chất lượng cao của Thành phố gắn với khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số và các bài toán, điểm nghẽn lớn của Thủ đô, thúc đẩy xã hội số thực chất'),
(431, 32, 'Xây dựng Quỹ Phát triển Khoa học và Công nghệ Thành phố theo cơ chế đặc thù (Hanoi Science Fund)'),
(432, 32, 'Hình thành các Không gian nghiên cứu - thử nghiệm công nghệ chiến lược của Thành phố'),
(433, 32, 'Đề án đào tạo năng lực số cho Đảng viên, công chức và công dân Thủ đô'),
(434, 32, 'Xây dựng nền tảng 360Hanoi tích hợp du lịch thông minh, văn hóa số, thương mại điện tử đặc sản địa phương (Điều chỉnh tách tên nhiệm vụ theo Quyết định số 37- QĐ/BCĐ57)'),
(435, 32, 'Nghiên cứu, lựa chọn, xác định và triển khai từ 3-5 nhiệm vụ có quy mô lớn để tập trung thúc đẩy và đột phá phát triển KHCN, ĐMST, CĐS trong phạm vi quản lý ngành, lĩnh vực. Nhiệm vụ có quy mô lớn cần có các thành phần chủ yếu sau: (1) Sáng kiến mang tính đột phá; (2) Bài toán trọng điểm, có tầm ảnh hưởng lớn; (3) Cụm hoặc chuỗi nhiệm vụ KHCN, ĐMST, CĐS; (4) Sản phẩm đầu ra cụ thể; (5) Các chỉ tiêu đo lường; (6) Đơn vị dự kiến tiếp nhận hoặc triển khai ứng dụng; (7) Mốc tiến độ hoàn thành theo từng quý. Ưu tiên các vấn đề lớn phục vụ nâng cao năng suất, chất lượng và có khả năng nhân rộng. Gửi Sở Khoa học và Công nghệ theo dõi, phối hợp triển khai.'),
(436, 32, 'Triển khai thí điểm xây dựng hệ thống quản trị công việc gắn với phương pháp đánh giá, đo lường bằng KPI/OKR, ứng dụng giải pháp công nghệ thông tin; bảo đảm hệ thống có chức năng theo dõi tiến độ, kiểm đếm kết quả và tổng hợp báo cáo phục vụ công tác lãnh đạo, điều hành'),
(437, 32, 'Triển khai hỗ trợ, vận hành hệ thống; đồng thời rà soát, tối ưu hóa quy trình áp dụng phương pháp KPI/OKR trên nền tảng số; bảo đảm phù hợp thực tiễn, khả năng mở rộng và duy trì vận hành ổn định sau giai đoạn thí điểm'),
(438, 33, 'Rà soát, khắc phục tình trạng lõm sóng, thiếu điện tại trụ sở cơ quan nhà nước, cơ sở giáo dục và cơ sở y tế công lập. (Danh mục gửi về Bộ Khoa học và Công nghệ và Bộ Công Thương trước ngày 30/7/2026;  Hoàn thành xử lý các điểm lõm sóng, thiếu điện tại các điểm ưu tiên trước 30/11/2026)(Sở Khoa học và Công nghệ về lõm sóng, Sở Công Thương về điện)'),
(439, 33, 'Rà soát, ban hành khung kiến trúc dữ liệu, khung quản trị dữ liệu và từ điển dữ liệu của bộ, ngành, địa phương theo yêu cầu tại Quyết định số 2439/QĐ-TTg của Thủ tướng Chính phủ ngày 04/11/2025'),
(440, 33, 'Tiếp tục triển khai quyết liệt Kế hoạch số 220/KH-UBND;'),
(441, 33, 'Tổng rà soát, kiểm kê, đánh giá hiện trạng các phần mềm, hệ thống thông tin đang sử dụng; phân loại đề xuất phương án giữ lại, tích hợp, dừng, hợp nhất hoặc thay thế bằng nền tảng dùng chung (theo Kế hoạch số 20-KH/BCĐ 57 ngày 19/01/2026)'),
(442, 32, 'Tham mưu phát triển hạ tầng xã hội, không gian sáng tạo, trong đó: xây dựng chính sách ưu đãi thuê, mua nhà ở cho nhân lực số, nhân lực khoa học – công nghệ; chuyển đổi công năng các cơ sở công nghiệp cũ, công trình phù hợp thành không gian đổi mới sáng tạo, không gian làm việc chung, trung tâm hỗ trợ khởi nghiệp.  (Chính sách nhà ở: Quý I/2026; chuyển đổi công năng: Quý III/2026)'),
(443, 32, 'Xây dựng và triển khai Đề án phát triển Kinh tế đêm'),
(444, 32, 'Đẩy mạnh phát triển công nghiệp văn hóa trên cơ sở ứng dụng công nghệ số thông qua thí điểm. Trong năm 2026 hoàn thành xây dựng khung mô hình, năm 2027 triển khai thực hiện. (Điều chỉnh tách tên nhiệm vụ, đơn vị chủ trì theo Quyết định số 37- QĐ/BCĐ57)'),
(445, 32, 'Số hóa di tích Quốc gia, di tích Quốc gia đặc biệt, thiết chế văn hóa nhằm bảo tồn số với độ chính xác cao, hỗ trợ quản lý - tu bổ - phục dựng và khai thác giá trị di sản cho giáo dục, du lịch, truyền thông. Hoàn thành số hóa cơ bản tại Văn Miếu - Quốc Tử Giám, Hoàng thành Thăng Long, Đền Ngọc Sơn, Nhà tù Hỏa Lò, Bảo tàng Hà Nội; và triển khai sản phẩm số khai thác giá trị số hóa di sản tại 5 địa điểm trên trong Quý IV/2026. (Điều chỉnh tách tên nhiệm vụ, đơn vị chủ trì theo Quyết định số 37- QĐ/BCĐ57)'),
(446, 32, 'Phát triển hệ thống không gian văn hóa sáng tạo gắn với công nghiệp văn hóa Thủ đô (Điều chỉnh đơn vị chủ trì theo Quyết định số 37- QĐ/BCĐ57)'),
(447, 32, 'Số hóa, chuẩn hóa hồ sơ dự án; theo dõi, giám sát tiến độ thực hiện dự án trên môi trường số. Bố trí ngân sách địa phương cho KHCN, ĐMST, CĐS'),
(448, 32, 'Xây dựng hồ sơ số dự án xuyên suốt vòng đời; triển khai cơ chế thẩm định song song giữa các cơ quan liên quan.'),
(449, 32, 'Số hóa dữ liệu đầu tư và quản lý dự án đầu tư công'),
(450, 33, 'Rà soát, đầu tư, mua sắm, nâng cấp trang thiết bị đầu cuối phục vụ giải quyết thủ tục hành chính và vận hành chính quyền địa phương 02 cấp, bảo đảm minh bạch, tiết kiệm, hiệu quả.'),
(451, 33, 'Rà soát, hoàn thiện phương án phân bổ, giao dự toán đối với kinh phí năm 2026 đã được bố trí nhưng chưa phân bổ, chưa giao dự toán; ưu tiên cơ sở dữ liệu, nền tảng dùng chung, an ninh mạng, thiết bị thiết yếu và nhiệm vụ cấp bách.'),
(452, 32, 'Sở Giáo dục và Đào tạo, Sở Y tế (theo lĩnh vực chuyên ngành) chủ trì liên thông dữ liệu chuyên ngành với cơ sở dữ liệu dân cư; tự động hóa các khâu nghiệp vụ lặp lại; ứng dụng công nghệ số để giảm phụ thuộc vào xử lý thủ công và thực hiện Chương trình hành động của Thành phố đối với các Nghị quyết của Bộ Chính trị: số 71-NQ/TW ngày 22/08/2025 về việc đột phá phát triển giáo dục và đào tạo và 72-NQ/TW ngày 9/9/2025 về một số giải pháp đột phá, tăng cường bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân'),
(453, 32, 'Thí điểm mô hình lớp học mở/lớp học hỗn hợp, khắc phục thiếu giáo viên cục bộ; quản lý lịch học, học liệu và tương tác học tập thông qua nền tảng số, kết nối với iHanoi (Điều chỉnh thời hạn theo Quyết định số 37- QĐ/BCĐ57)'),
(454, 32, 'Hoàn thành số hóa 100% học liệu và bài giảng cốt lõi, hình thành kho học liệu số dùng chung, giảm trùng lặp và thời gian chuẩn bị bài; cho phép phụ huynh, học sinh tra cứu, tiếp cận học liệu phù hợp qua iHanoi'),
(455, 32, 'Thiết lập Hệ sinh thái Giáo dục Thông minh Thủ đô (Hanoi Smart Education Hub - HSE), đóng vai trò là "trục xương sống" kết nối giữa Sở Giáo dục & Đào tạo, Nhà trường, Giáo viên, Học sinh và Phụ huynh. Trong đó, nền tảng "Học tập Cá nhân hóa" dựa trên AI (Personalized AI Learning) chứa hồ sơ số suốt đời, gia sư AI 24/7, hệ thống dự báo sớm, v.v'),
(456, 32, 'Triển khai Trợ lý ảo hỗ trợ giáo viên, giảm đáng kể khối lượng công việc hành chính'),
(457, 33, 'Tiếp tục đẩy mạnh triển khai học bạ số trên toàn địa bàn Thành phố'),
(458, 33, 'Rà soát, chuẩn hóa, đối soát, làm sạch dữ liệu cán bộ, công chức, viên chức thuộc thẩm quyền quản lý của Thành phố'),
(459, 33, 'Triển khai đầy đủ, kịp thời chính sách hỗ trợ đối với người làm công tác chuyên trách chuyển đổi số, an ninh mạng theo Nghị định số 179/2025/NĐ-CP.'),
(460, 32, 'Thí điểm Đề án “Mô hình tiêu dùng số và bảo trợ thương mại điện tử Hà Nội”'),
(461, 32, 'Đề án Liên thông dữ liệu, tối ưu hóa chi phí logistics - xuất nhập khẩu'),
(462, 33, 'Rà soát, khắc phục tình trạng lõm sóng, thiếu điện tại trụ sở cơ quan nhà nước, cơ sở giáo dục và cơ sở y tế công lập. (Danh mục gửi về Bộ Khoa học và Công nghệ và Bộ Công Thương trước ngày 30/7/2026;  Hoàn thành xử lý các điểm lõm sóng, thiếu điện tại các điểm ưu tiên trước 30/11/2026)(Sở Khoa học và Công nghệ về lõm sóng, Sở Công Thương về điện)'),
(463, 32, 'Sở Giáo dục và Đào tạo, Sở Y tế (theo lĩnh vực chuyên ngành) chủ trì liên thông dữ liệu chuyên ngành với cơ sở dữ liệu dân cư; tự động hóa các khâu nghiệp vụ lặp lại; ứng dụng công nghệ số để giảm phụ thuộc vào xử lý thủ công và thực hiện Chương trình hành động của Thành phố đối với các Nghị quyết của Bộ Chính trị: số 71-NQ/TW ngày 22/08/2025 về việc đột phá phát triển giáo dục và đào tạo và 72-NQ/TW ngày 9/9/2025 về một số giải pháp đột phá, tăng cường bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân (Sở Y tế)  (Điều chỉnh thời hạn theo Quyết định số 37- QĐ/BCĐ57)'),
(464, 32, 'Hình thành kho lưu trữ hình ảnh y tế tập trung, chia sẻ kết quả chẩn đoán hình ảnh giữa 100% cơ sở y tế trên địa bàn Thành phố; cho phép người dân truy cập kết quả khám, chẩn đoán trên iHanoi (Điều chỉnh thời hạn theo Quyết định số 37- QĐ/BCĐ57)'),
(465, 32, 'Hoàn thành thiết lập mô hình khám, hội chẩn từ xa chuẩn hóa, có bác sĩ tại 100% cơ sở y tế tham gia; tích hợp lịch hẹn, tư vấn trực tuyến và theo dõi điều trị trên iHanoi'),
(466, 32, 'Nâng cao hiệu quả vận hành và khai thác Hồ sơ sức khỏe điện tử (Điều chỉnh tên, thời hạn nhiệm vụ theo Quyết định số 37- QĐ/BCĐ57)'),
(467, 32, 'Phát triển mô hình kinh tế tóc bạc trên địa bàn Thành phố'),
(468, 32, 'Xây dựng và vận hành hệ thống khám, chữa bệnh từ xa (Telehealth) của Thành phố'),
(469, 32, 'Bố trí, bảo đảm nguồn vốn đầu tư công trang bị máy xạ trị proton'),
(470, 33, 'Phát triển Sổ sức khỏe điện tử và nền tảng số chăm sóc sức khỏe toàn dân; chuẩn hóa, liên thông dữ liệu khám, chữa bệnh, bảo hiểm.'),
(471, 32, 'Mở rộng, hoàn thiện Khu Công nghệ cao Hòa Lạc'),
(472, 32, 'Văn phòng Thành ủy chủ trì, phối hợp với Công an Thành phố thực hiện kết nối hệ thống camera. (Điều chỉnh tên, đơn vị chủ trì, thời hạn theo Quyết định số 37- QĐ/BCĐ57)'),
(473, 32, 'Triển khai đánh giá sức khỏe doanh nghiệp và dự báo thu NSNN bằng AI (để hỗ trợ tăng trưởng kinh tế, thu hút đầu tư phù hợp, chống thất thu ngân sách) (Điều chỉnh thời hạn theo Quyết định số 37- QĐ/BCĐ57)'),
(474, 32, 'Lãnh đạo việc tổ chức triển khai Kế hoạch trong toàn bộ khối các cơ quan Đảng Thành phố; bảo đảm sự thống nhất, đồng bộ, phù hợp với chức năng, nhiệm vụ của từng cơ quan, đơn vị'),
(475, 32, 'Lãnh đạo việc tiếp tục triển khai Đề án chuyển đổi số trong các cơ quan Đảng thuộc Thành ủy Hà Nội; bảo đảm đúng định hướng, yêu cầu của Trung ương và Thành ủy'),
(476, 32, 'Ủy ban Kiểm tra Thành ủy đưa nội dung thực hiện Nghị quyết số 57-NQ/TW và Kế hoạch này vào chương trình kiểm tra, giám sát hằng năm; tăng cường giám sát việc thực hiện trách nhiệm của cấp ủy, tổ chức đảng và người đứng đầu; kịp thời kiến nghị xử lý theo thẩm quyền'),
(477, 32, 'Tổ chức nghiên cứu, quán triệt, tuyên truyền sâu rộng Kế hoạch này, xây dựng và tổ chức thực hiện kế hoạch triển khai năm 2026, xác định rõ nhiệm vụ trọng tâm, sản phẩm đầu ra, tiến độ và nguồn lực thực hiện; bảo đảm nguyên tắc “một việc - một đầu mối - một sản phẩm - một thời hạn”.'),
(478, 32, 'Bí thư cấp ủy chịu trách nhiệm trực tiếp, toàn diện trước cấp có thẩm quyền về kết quả thực hiện; lãnh đạo việc phân công nhiệm vụ theo phương châm “rõ người - rõ việc - rõ trách nhiệm giải trình”.'),
(479, 32, 'Lãnh đạo tổ chức thực hiện đầy đủ 04 nội dung cốt lõi:
(1) Đề xuất bài toán quản trị, điều hành;
(2) Chuẩn hóa, cung cấp dữ liệu đầu vào;
(3) Phối hợp triển khai thí điểm có đối chứng;
(4) Báo cáo kết quả thực hiện theo chu kỳ trên cơ sở hệ thống chỉ tiêu đánh giá'),
(480, 32, 'Căn cứ Danh mục bài toán ưu tiên của Thành phố đã được phê duyệt, lãnh đạo các cơ quan, đơn vị có trách nhiệm tổ chức triển khai các bài toán thuộc phạm vi quản lý địa bàn; chủ động phối hợp với các cơ quan, đơn vị liên quan trong quá trình thử nghiệm, đánh giá và nhân rộng. Việc triển khai bài toán là nội dung bắt buộc trong kế hoạch công tác năm, làm căn cứ theo dõi, đánh giá kết quả thực hiện nhiệm vụ'),
(481, 32, 'Phối hợp cung cấp thông tin, dữ liệu ngành; điều tra, khảo sát thực trạng, nhu cầu theo hướng dẫn của cơ quan, tổ chức chuyên môn, cơ quan thống kê; trên cơ sở dữ liệu điều tra, thống kê, chịu trách nhiệm xác định và đề xuất các bài toán nâng cao hiệu suất theo ngành, lĩnh vực'),
(482, 32, 'Kịp thời phản ánh các điểm nghẽn liên ngành; trường hợp phát sinh vướng mắc trong phối hợp mà chưa thống nhất được phương án xử lý, các đơn vị báo cáo cơ quan Thường trực Ban Chỉ đạo trong thời hạn không quá 03 ngày làm việc để tổng hợp, điều phối xử lý thống nhất'),
(483, 32, 'Ban Nội chính Thành ủy theo dõi, tổng hợp tình hình; tham mưu, đề xuất các giải pháp phòng ngừa, xử lý sai phạm trong quá trình triển khai các chương trình, dự án khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số'),
(484, 32, 'Tham mưu, giúp Ban Chỉ đạo theo dõi, đôn đốc, kiểm tra, giám sát việc tổ chức triển khai Kế hoạch tại các cấp, các ngành; tổng hợp, phân tích tình hình thực hiện trên cơ sở dữ liệu và báo cáo của các cơ quan, đơn vị liên quan'),
(485, 32, 'Chuẩn bị nội dung, chương trình, tài liệu phục vụ hoạt động của Ban Chỉ đạo; chủ động rà soát, tổng hợp các nội dung chuyên môn phục vụ công tác tham mưu, bảo đảm chất lượng trước khi báo cáo, trình Ban Chỉ đạo xem xét'),
(486, 32, 'Tham gia tư vấn, phản biện, đề xuất với Ban Chỉ đạo các định hướng chiến lược, mô hình, cơ chế, chính sách đột phá trong lĩnh vực khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số'),
(487, 32, 'Chủ động tham vấn đội ngũ chuyên gia, nhà khoa học, cộng đồng doanh nghiệp; nhận diện sớm các xu hướng, rủi ro, điểm nghẽn từ thực tiễn để kiến nghị Ban Chỉ đạo báo cáo cấp có thẩm quyền xem xét, chỉ đạo'),
(488, 32, 'Tham mưu, giúp Trưởng Ban Chỉ đạo điều phối chung việc tổ chức triển khai Kế hoạch; bảo đảm sự phối hợp đồng bộ, thông suốt giữa các chủ thể trong hệ thống chính trị'),
(489, 32, 'Rà soát, tham mưu kiện toàn tổ chức, nhân sự Ban Chỉ đạo, Tổ Thường trực và Tổ tư vấn, chuyên gia theo yêu cầu nhiệm vụ từng thời kỳ; bảo đảm bộ máy hoạt động hiệu lực, hiệu quả.'),
(490, 32, 'Theo dõi, tổng hợp tình hình triển khai; kịp thời báo cáo, tham mưu đề xuất Trưởng Ban Chỉ đạo xem xét, định hướng xử lý các vấn đề phát sinh; tham mưu công tác thi đua, khen thưởng theo quy định'),
(491, 32, 'Căn cứ chức năng, nhiệm vụ được giao, cụ thể hóa và lồng ghép các mục tiêu, nhiệm vụ của Kế hoạch vào chương trình, kế hoạch công tác hằng năm; đồng thời lãnh đạo việc rà soát, điều chỉnh quy trình công tác, phương thức làm việc theo hướng đẩy mạnh ứng dụng khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số; tổ chức thực hiện nghiêm việc sử dụng các nền tảng số dùng chung; bảo đảm kỷ luật dữ liệu, an toàn thông tin và hiệu quả thực chất trong xử lý công việc trên môi trường số; gắn kết quả thực hiện Kế hoạch với công tác đánh giá, xếp loại tổ chức đảng, cán bộ, đảng viên và trách nhiệm của người đứng đầu trong khối các cơ quan Đảng Thành phố'),
(492, 32, 'Ban hành Kế hoạch chi tiết để triển khai Kế hoạch này tại từng cơ quan, đơn vị phụ trách, bảo đảm bám sát thực tiễn, rõ người, rõ việc, rõ trách nhiệm, rõ thời hạn, rõ kết quả; theo mô hình OKR và lượng hóa các chỉ số đánh giá kết quả thực hiện (KPI) tương ứng với từng nhiệm vụ; gửi Tổ Thường trực theo dõi, đôn đốc, kiểm tra, giám sát việc thực hiện các nhiệm vụ của Ban Chỉ đạo 57 Thành ủy để tổng hợp, cập nhật và theo dõi tập trung trên Hệ thống. Hoàn thành chậm nhất trong vòng 05 ngày làm việc kể từ ngày Kế hoạch này được ban hành'),
(493, 32, 'Thường xuyên rà soát, cập nhật, điều chỉnh Kế hoạch nhằm bảo đảm phù hợp, thống nhất với Chương trình công tác năm 2026 của Ban Chỉ đạo 57 Trung ương và các chỉ đạo của Ban Chỉ đạo 57 Thành ủy trong quá trình thực hiện'),
(494, 32, 'Triển khai thí điểm các mô hình, giải pháp công nghệ tại một số khu vực, tuyến, điểm nóng đô thị (theo nguyên tắc làm thật – đo được – điều chỉnh được), làm cơ sở đánh giá hiệu quả trước khi nhân rộng.'),
(495, 32, 'Chuyển đổi số thực chất các ngành có ảnh hưởng tới an sinh và phúc lợi của người dân như: y tế, giáo dục, văn hóa, lao động, việc làm, an sinh xã hội, thực phẩm và môi trường; đối với các ngành, lĩnh vực có tác động lớn đến tăng trưởng, năng suất và năng lực cạnh tranh; ưu tiên các chuỗi giá trị có quy mô lớn và khả năng lan tỏa cao như: công nghiệp nền tảng; công nghiệp ưu tiên; công nghiệp mũi nhọn; công nghiệp năng lượng; khai thác tài nguyên, khoáng sản; thương mại và phân phối; tài chính, ngân hàng; giao thông vận tải và logistics; nông nghiệp; xây dựng; du lịch'),
(496, 33, 'Tập trung hoàn thành các nhiệm vụ quá hạn và sắp tới hạn (theo số liệu được công bố trên Hệ thống theo dõi các nghị quyết tại địa chỉ theodoinq.dcs.vn.'),
(497, 33, 'Cập nhật kết quả nhiệm vụ hằng tuần, hằng tháng trên Hệ thống theodoinq.dcs.vn hoặc báo cáo đột xuất theo yêu cầu Ban Chỉ đạo Trung ương'),
(498, 33, 'Phê duyệt hồ sơ đề xuất cấp độ an toàn hệ thống thông tin đối với các hệ thống trước khi đưa vào vận hành, khai thác; tổ chức kiểm tra, đánh giá an ninh mạng định kỳ.'),
(499, 32, 'Lãnh đạo HĐND Thành phố và HĐND các cấp triển khai chuyển đổi số trong hoạt động của cơ quan dân cử theo đúng chức năng, nhiệm vụ, thẩm quyền; từng bước nâng cao hiệu quả hoạt động của HĐND trên môi trường số'),
(500, 32, 'Lãnh đạo đổi mới phương thức giám sát việc thực hiện Nghị quyết số 57-NQ/TW và Kế hoạch này theo hướng dựa trên dữ liệu và kết quả thực hiện; khai thác dữ liệu từ các hệ thống thông tin của Thành phố; tăng cường giám sát trực tuyến; tham mưu hoàn thiện các cơ chế, chính sách cần thiết theo thẩm quyền nhằm tháo gỡ các điểm nghẽn trong triển khai Kế hoạch'),
(501, 33, 'Tập trung hoàn thành các nhiệm vụ quá hạn và sắp tới hạn (theo số liệu được công bố trên Hệ thống theo dõi các nghị quyết tại địa chỉ theodoinq.dcs.vn.'),
(502, 33, 'Cập nhật kết quả nhiệm vụ hằng tuần, hằng tháng trên Hệ thống theodoinq.dcs.vn hoặc báo cáo đột xuất theo yêu cầu Ban Chỉ đạo Trung ương'),
(503, 32, 'Lãnh đạo UBND Thành phố tổ chức thực hiện Kế hoạch theo đúng chức năng, thẩm quyền của chính quyền; cụ thể hóa các mục tiêu, nhiệm vụ của Kế hoạch thành chương trình, đề án và kế hoạch công tác năm 2026, bảo đảm phân công trách nhiệm tổ chức thực hiện theo nguyên tắc “6 rõ”: rõ người, rõ việc, rõ thời gian, rõ trách nhiệm giải trình, rõ sản phẩm đầu ra và rõ thẩm quyền'),
(504, 32, 'Lãnh đạo thống nhất danh mục các bài toán quản trị, hệ thống chỉ tiêu đánh giá (KPI), kiến trúc dữ liệu và các nền tảng số dùng chung của Thành phố trong phạm vi tổ chức thực hiện của UBND Thành phố'),
(505, 32, 'Lãnh đạo UBND Thành phố theo dõi, giám sát việc tổ chức thực hiện Kế hoạch đối với các sở, ban, ngành và UBND các xã, phường trên cơ sở dữ liệu và kết quả đầu ra; chủ động xử lý các khó khăn, vướng mắc liên ngành theo thẩm quyền; kịp thời báo cáo Ban Chỉ đạo đối với các vấn đề vượt thẩm quyền hoặc tác động đến định hướng, mục tiêu lớn của Kế hoạch'),
(506, 33, 'Tập trung hoàn thành các nhiệm vụ quá hạn và sắp tới hạn (theo số liệu được công bố trên Hệ thống theo dõi các nghị quyết tại địa chỉ theodoinq.dcs.vn.'),
(507, 33, 'Xúc tiến, tháo gỡ và triển khai các dự án đầu tư mới trong lĩnh vực kinh tế số trên địa bàn'),
(508, 33, 'Cập nhật kết quả nhiệm vụ hằng tuần, hằng tháng trên Hệ thống theodoinq.dcs.vn hoặc báo cáo đột xuất theo yêu cầu Ban Chỉ đạo Trung ương'),
(509, 32, 'Lãnh đạo, chỉ đạo triển khai sâu rộng phong trào "Chuyển đổi số cộng đồng", lấy đoàn viên, hội viên làm nòng cốt với phương châm "đi từng ngõ, gõ từng nhà, hướng dẫn từng người"'),
(510, 32, 'Lãnh đạo, chỉ đạo xây dựng và triển khai các ứng dụng số phục vụ cơ sở, gồm: phần mềm Tổ dân phố số hướng tới triển khai đồng bộ tại 126 xã, phường; ứng dụng giám sát và phản biện xã hội nhằm theo dõi việc tiếp thu, giải quyết của chính quyền, tăng cường giám sát đầu tư của cộng đồng đối với các dự án trọng điểm, công tác giải phóng mặt bằng, bồi thường, tái định cư,…'),
(511, 32, 'Triển khai các nền tảng số đặc thù: Chỉ đạo Đoàn Thanh niên vận hành hiệu quả "Mạng lưới tình nguyện số"; Hội Phụ nữ triển khai ứng dụng quản lý hội viên; Liên đoàn Lao động triển khai "Công đoàn số",...'),
(512, 32, 'Thực hiện vai trò giám sát và phản biện xã hội trên môi trường số: Tổng hợp ý kiến, kiến nghị của Nhân dân qua các kênh trực tuyến (iHanoi, mạng xã hội) để phản ánh với cấp ủy, chính quyền; giám sát việc giải quyết thủ tục hành chính và thái độ phục vụ của cán bộ công chức qua dữ liệu hệ thống'),
(513, 33, 'Tập trung hoàn thành các nhiệm vụ quá hạn và sắp tới hạn (theo số liệu được công bố trên Hệ thống theo dõi các nghị quyết tại địa chỉ theodoinq.dcs.vn.'),
(514, 33, 'Rà soát, chuẩn hóa, làm sạch dữ liệu đoàn viên, hội viên, tổ chức cơ sở, giám sát – phản biện và phản ánh kiến nghị của nhân dân'),
(515, 33, 'Cập nhật kết quả nhiệm vụ hằng tuần, hằng tháng trên Hệ thống theodoinq.dcs.vn hoặc báo cáo đột xuất theo yêu cầu Ban Chỉ đạo Trung ương'),
(516, 32, 'Ban Tuyên giáo và Dân vận Thành ủy chủ trì tham mưu, định hướng công tác thông tin, tuyên truyền; tạo sự thống nhất về nhận thức, sự đồng thuận trong cán bộ, đảng viên và Nhân dân; kịp thời phát hiện, cổ vũ, nhân rộng các mô hình hay, cách làm hiệu quả'),
(517, 32, 'Ban Tổ chức Thành ủy chủ trì tham mưu Ban Thường vụ Thành ủy về công tác cán bộ gắn với yêu cầu phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số; xây dựng định hướng, tiêu chí đối với đội ngũ cán bộ lãnh đạo, quản lý trong các lĩnh vực có liên quan; tham mưu công tác quy hoạch, đào tạo, bồi dưỡng nhằm nâng cao năng lực số, năng lực đổi mới sáng tạo; lồng ghép tiêu chí về năng lực và kết quả thực hiện nhiệm vụ khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số vào công tác đánh giá, xếp loại cán bộ hằng năm theo quy định'),
(518, 33, 'Rà soát, chuẩn hóa, làm sạch, đối soát dữ liệu tổ chức đảng, đảng viên trong toàn Đảng bộ Thành phố'),
(519, 34, 'Rà soát, đẩy nhanh tiến độ và xử lý dứt điểm các nhiệm vụ đã quá hạn, các nhiệm vụ sắp đến hạn theo văn bản giao nhiệm vụ và số liệu trên các hệ thống theo dõi.'),
(520, 34, 'Rà soát, ban hành mới hoặc sửa đổi, bổ sung các văn bản, quy định, quy chế và quy trình còn thiếu, chưa đồng bộ hoặc không còn phù hợp phục vụ chuyển đổi số trong các cơ quan Đảng.'),
(521, 34, 'Rà soát, ban hành quy định về quản lý, khai thác, chia sẻ và bảo vệ dữ liệu; phân cấp, phân quyền và kiểm soát truy cập.'),
(522, 35, 'UBND Thành phố chỉ đạo các đơn vị có tỷ lệ giải ngân dưới 30% giải trình bằng văn bản, nêu rõ khối lượng đã hoàn thành, điều kiện thanh toán, vướng mắc về thủ tục, mốc giải ngân tiếp theo và gửi kế hoạch xử lý trước ngày 15/7/2026; bảo đảm đạt mốc giải ngân 55% trước ngày 31/8/2026 theo yêu cầu điều hành.'),
(523, 36, 'Về việc rà soát, đánh giá Đề án “Xây dựng cơ sở dữ liệu dùng chung từ số hóa tài liệu tập trung của các cơ quan trên địa bàn thành phố Hà Nội” theo Báo cáo số 283/BC-UBND của UBND Thành phố'),
(524, 34, 'Rà soát, đẩy nhanh tiến độ và xử lý dứt điểm các nhiệm vụ đã quá hạn, các nhiệm vụ sắp đến hạn theo văn bản giao nhiệm vụ và số liệu trên các hệ thống theo dõi.'),
