UPDATE tmp_check_nv
SET TenNorm = LOWER(TRIM(TRIM(TRAILING '.' FROM TRIM(
                  REPLACE(REPLACE(REPLACE(REPLACE(
                      REPLACE(REPLACE(REPLACE(Ten, CHAR(13), ' '), CHAR(10), ' '), CHAR(9), ' '),
                  '  ', ' '), '  ', ' '), '  ', ' '), '  ', ' '))))),
    TenHash = MD5(TenNorm);

-- Quét qlnv_task một lần, chuẩn hoá Title
DROP TEMPORARY TABLE IF EXISTS tmp_task_norm;
CREATE TEMPORARY TABLE tmp_task_norm (
    TaskId    BIGINT PRIMARY KEY,
    TitleNorm TEXT COLLATE utf8mb4_bin,
    TitleHash CHAR(32),
    KEY ix_hash (TitleHash)
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

INSERT INTO tmp_task_norm (TaskId, TitleNorm)
SELECT  t.TaskId,
        LOWER(TRIM(TRIM(TRAILING '.' FROM TRIM(
            REPLACE(REPLACE(REPLACE(REPLACE(
                REPLACE(REPLACE(REPLACE(CONVERT(IFNULL(t.Title, '') USING utf8mb4), CHAR(13), ' '), CHAR(10), ' '), CHAR(9), ' '),
            '  ', ' '), '  ', ' '), '  ', ' '), '  ', ' ')))))
FROM qlnv_task t;

UPDATE tmp_task_norm SET TitleHash = MD5(TitleNorm);

-- Khớp tên theo "chứa" (sau chuẩn hoá 2 phía):
--   Title DB chứa tên Excel, HOẶC tên Excel chứa Title DB (chỉ khi Title DB >= 30 ký tự,
--   tránh title ngắn kiểu "Báo cáo" khớp bừa vào mọi tên dài)
DROP TEMPORARY TABLE IF EXISTS tmp_nv_match;
CREATE TEMPORARY TABLE tmp_nv_match (
    Stt        INT,
    TaskId     BIGINT,
    PRIMARY KEY (Stt, TaskId),
    KEY ix_task (TaskId)
);

-- So "chứa" trên Title đã gộp trùng (~19k thay vì ~94k task), chia lô theo STT để mỗi câu
-- không quá ~60s (server ngắt kết nối nếu 1 câu chạy lâu)
DROP TEMPORARY TABLE IF EXISTS tmp_title_distinct;
CREATE TEMPORARY TABLE tmp_title_distinct (
    TitleHash CHAR(32) PRIMARY KEY,
    TitleNorm TEXT COLLATE utf8mb4_bin
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

INSERT IGNORE INTO tmp_title_distinct (TitleHash, TitleNorm)
SELECT TitleHash, TitleNorm FROM tmp_task_norm WHERE TitleNorm <> '';

DROP TEMPORARY TABLE IF EXISTS tmp_nv_title_match;
CREATE TEMPORARY TABLE tmp_nv_title_match (
    Stt       INT,
    TitleHash CHAR(32),
    PRIMARY KEY (Stt, TitleHash)
);

INSERT IGNORE INTO tmp_nv_title_match (Stt, TitleHash)
SELECT c.Stt, d.TitleHash FROM tmp_check_nv c JOIN tmp_title_distinct d
  ON c.TenNorm <> '' AND (LOCATE(c.TenNorm, d.TitleNorm) > 0
                          OR (CHAR_LENGTH(d.TitleNorm) >= 30 AND LOCATE(d.TitleNorm, c.TenNorm) > 0))
WHERE c.Stt BETWEEN 1 AND 130;

INSERT IGNORE INTO tmp_nv_title_match (Stt, TitleHash)
SELECT c.Stt, d.TitleHash FROM tmp_check_nv c JOIN tmp_title_distinct d
  ON c.TenNorm <> '' AND (LOCATE(c.TenNorm, d.TitleNorm) > 0
                          OR (CHAR_LENGTH(d.TitleNorm) >= 30 AND LOCATE(d.TitleNorm, c.TenNorm) > 0))
WHERE c.Stt BETWEEN 131 AND 260;

INSERT IGNORE INTO tmp_nv_title_match (Stt, TitleHash)
SELECT c.Stt, d.TitleHash FROM tmp_check_nv c JOIN tmp_title_distinct d
  ON c.TenNorm <> '' AND (LOCATE(c.TenNorm, d.TitleNorm) > 0
                          OR (CHAR_LENGTH(d.TitleNorm) >= 30 AND LOCATE(d.TitleNorm, c.TenNorm) > 0))
WHERE c.Stt BETWEEN 261 AND 390;

INSERT IGNORE INTO tmp_nv_title_match (Stt, TitleHash)
SELECT c.Stt, d.TitleHash FROM tmp_check_nv c JOIN tmp_title_distinct d
  ON c.TenNorm <> '' AND (LOCATE(c.TenNorm, d.TitleNorm) > 0
                          OR (CHAR_LENGTH(d.TitleNorm) >= 30 AND LOCATE(d.TitleNorm, c.TenNorm) > 0))
WHERE c.Stt > 390;

-- Bung lại ra từng task theo Title đã khớp
INSERT IGNORE INTO tmp_nv_match (Stt, TaskId)
SELECT m.Stt, t.TaskId
FROM tmp_nv_title_match m
JOIN tmp_task_norm t ON t.TitleHash = m.TitleHash;

-- Các văn bản DB đã khớp với từng văn bản Excel (để biết task tìm theo tên có nằm đúng văn bản không)
DROP TEMPORARY TABLE IF EXISTS tmp_vb_res;
CREATE TEMPORARY TABLE tmp_vb_res (PRIMARY KEY (VbStt, ResolutionId)) AS
SELECT DISTINCT Stt AS VbStt, ResolutionId FROM tmp_chi_tiet_vb;

-- Chi tiết từng task khớp theo tên
DROP TEMPORARY TABLE IF EXISTS tmp_nv_ct;
CREATE TEMPORARY TABLE tmp_nv_ct AS
SELECT
    c.Stt,
    c.VbStt,
    t.TaskId,
    t.Code,
    (t.DeletedDate IS NOT NULL)        AS DaXoa,
    t.ResolutionId,
    r.DocCode                          AS DocCodeVB,
    r.ResolutionGroupId,
    (r.ResolutionGroupId = 55)         AS Nhom55,
    (vr.ResolutionId IS NOT NULL)      AS DungVanBan
FROM tmp_nv_match m
JOIN tmp_check_nv c          ON c.Stt = m.Stt
JOIN qlnv_task t             ON t.TaskId = m.TaskId
LEFT JOIN qlnv_resolution r  ON r.ResolutionId = t.ResolutionId
LEFT JOIN tmp_vb_res vr      ON vr.VbStt = c.VbStt AND vr.ResolutionId = t.ResolutionId;


-- KẾT QUẢ) Mỗi nhiệm vụ Excel đúng 1 dòng (571 dòng) với 1 task đại diện.
--      Một nhiệm vụ nhiều chủ trì sinh ra nhiều task (gốc + con / mỗi chủ trì 1 task); chọn theo thứ tự ưu tiên:
--      chưa xoá > đúng văn bản > nhóm 55 > task gốc (ParentId NULL) > TaskId nhỏ nhất.
--      Khoá ưu tiên ghép thành chuỗi rồi lấy MIN (MySQL 5.7 chưa có ROW_NUMBER).
DROP TEMPORARY TABLE IF EXISTS tmp_nv_dai_dien;
CREATE TEMPORARY TABLE tmp_nv_dai_dien (PRIMARY KEY (Stt)) AS
SELECT m.Stt,
       CAST(SUBSTRING(MIN(CONCAT(m.DaXoa,
                                 1 - IFNULL(m.DungVanBan, 0),
                                 1 - IFNULL(m.Nhom55, 0),
                                 (t.ParentId IS NOT NULL),
                                 LPAD(m.TaskId, 12, '0'))), 5) AS UNSIGNED) AS TaskId,
       COUNT(*)                AS SoTaskKhop,
       SUM(m.DaXoa = 0)        AS SoTaskKhopChuaXoa
FROM tmp_nv_ct m
JOIN qlnv_task t ON t.TaskId = m.TaskId
GROUP BY m.Stt;

SELECT c.Stt,
       vb.DocCode                                  AS VanBanExcel,
       LEFT(c.Ten, 200)                            AS TenExcel,
       d.TaskId,
       t.Code,
       t.ParentId,
       (t.DeletedDate IS NOT NULL)                 AS DaXoa,
       t.ResolutionId,
       r.DocCode                                   AS DocCodeDB,
       r.ResolutionGroupId,
       (SELECT GROUP_CONCAT(u.UserName SEPARATOR ', ') FROM qlnv_user u
         WHERE u.eGovUserId = t.TargetUser)        AS ChuTri,   -- 1 eGovUserId có thể có 2 tài khoản
       t.ExpireDate,
       t.IsRecurring,
       t.Status,
       LEFT(t.Title, 200)                          AS TitleDB,
       IFNULL(d.SoTaskKhop, 0)                     AS SoTaskKhop,
       IFNULL(d.SoTaskKhopChuaXoa, 0)              AS SoTaskKhopChuaXoa
FROM tmp_check_nv c
JOIN tmp_check_vb vb          ON vb.Stt = c.VbStt
LEFT JOIN tmp_nv_dai_dien d   ON d.Stt = c.Stt
LEFT JOIN qlnv_task t         ON t.TaskId = d.TaskId
LEFT JOIN qlnv_resolution r   ON r.ResolutionId = t.ResolutionId
ORDER BY c.Stt;

-- Dọn bảng lớn
DROP TEMPORARY TABLE IF EXISTS tmp_res_norm;
DROP TEMPORARY TABLE IF EXISTS tmp_task_norm;
DROP TEMPORARY TABLE IF EXISTS tmp_title_distinct;